# ============================================================================
# 4. LEDGER v10 — SQLite com migração automática (adicionado referral e stake)
# ============================================================================

class LedgerV10:
    SCHEMA_VERSION = 24
    def __init__(self, path: Path):
        self.path = path
        self.lock = threading.Lock()
        self._local = threading.local()
        self._init()
        self._migrate_legacy()

    def _conn(self):
        """v23 FIX CRÍTICO: conexão thread-local PERSISTENTE.
        A v22 abria uma conexão nova por operação e nunca fechava
        ('with sqlite3.connect()' faz commit, mas NÃO fecha). Com gunicorn
        gthread, conexões vazavam segurando locks → 'database is locked'
        no boot (crash visto no log do Railway) e em produção.
        Agora: 1 conexão por thread, busy_timeout 30s, WAL com fallback."""
        c = getattr(self._local, "conn", None)
        if c is not None:
            return c
        last_err = None
        for attempt in range(6):
            try:
                c = sqlite3.connect(self.path, check_same_thread=False, timeout=30)
                c.execute("PRAGMA busy_timeout=30000")
                try:
                    c.execute("PRAGMA journal_mode=WAL")
                except sqlite3.OperationalError:
                    c.execute("PRAGMA journal_mode=DELETE")
                c.execute("PRAGMA synchronous=NORMAL")
                self._local.conn = c
                return c
            except sqlite3.OperationalError as e:
                last_err = e
                if "locked" in str(e).lower():
                    time.sleep(0.4 * (attempt + 1))
                    continue
                raise
        raise last_err

    def _init(self):
        with self.lock, self._conn() as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT);
            CREATE TABLE IF NOT EXISTS revenue (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts INTEGER NOT NULL,
                endpoint TEXT NOT NULL,
                amount REAL NOT NULL,
                tx_sig TEXT,
                payer TEXT,
                source TEXT DEFAULT 'direct',
                chain TEXT DEFAULT 'solana',
                jwt_session TEXT,
                referral_code TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_rev_ts ON revenue(ts);
            CREATE INDEX IF NOT EXISTS idx_rev_endpoint ON revenue(endpoint);
            CREATE INDEX IF NOT EXISTS idx_rev_payer ON revenue(payer);""")
            # v44.8.2: migracao unica — settles AVM eram gravados como "solana"
            # (deteccao de chain caia no else). Txid Algorand = 52 chars, tudo
            # maiusculo; assinaturas Solana base58 tem ~88 chars com minusculas.
            try:
                _fixed = c.execute(
                    "UPDATE revenue SET chain='algorand' "
                    "WHERE chain='solana' AND length(tx_sig)=52 AND upper(tx_sig)=tx_sig"
                ).rowcount
                if _fixed:
                    log.info(f"🧭 migracao v44.8.2: {_fixed} receipts reclassificados solana→algorand")
            except Exception as _me:
                log.warning(f"migracao chain algorand: {_me}")
            c.executescript("""
            CREATE TABLE IF NOT EXISTS requests (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts INTEGER NOT NULL,
                endpoint TEXT NOT NULL,
                ok INTEGER NOT NULL,
                latency_ms INTEGER,
                ip TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_req_ts ON requests(ts);
            CREATE TABLE IF NOT EXISTS replay (
                hash TEXT PRIMARY KEY,
                ts INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS peers (
                node_id TEXT PRIMARY KEY,
                url TEXT,
                public_key TEXT,
                last_seen INTEGER,
                reputation REAL DEFAULT 1.0,
                win_rate REAL DEFAULT 50.0
            );
            CREATE TABLE IF NOT EXISTS signals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts INTEGER NOT NULL,
                symbol TEXT NOT NULL,
                action TEXT NOT NULL,
                confidence REAL,
                price_at REAL,
                result TEXT,
                pnl_pct REAL,
                validated_at INTEGER
            );
            CREATE INDEX IF NOT EXISTS idx_sig_ts ON signals(ts);
            CREATE TABLE IF NOT EXISTS cache (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                ts INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS jwt_sessions (
                jti TEXT PRIMARY KEY,
                payer TEXT,
                endpoint TEXT,
                ts INTEGER,
                exp INTEGER,
                tx_sig TEXT
            );
            CREATE TABLE IF NOT EXISTS sweeps (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts INTEGER, amount REAL, tx_sig TEXT, dest TEXT
            );
            -- Novo: tabela de referidos
            CREATE TABLE IF NOT EXISTS referrals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT UNIQUE,
                owner TEXT,
                created INTEGER,
                total_commission REAL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS referral_uses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT,
                buyer TEXT,
                ts INTEGER,
                amount REAL,
                commission REAL
            );
            -- Novo: tabela de stakes
            CREATE TABLE IF NOT EXISTS stakes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staker TEXT,
                amount REAL,
                ts INTEGER,
                status TEXT DEFAULT 'active',  -- active, withdrawn, slashed
                tx_sig TEXT
            );
            -- v23: créditos pré-pagos / passes (motor de conversão)
            CREATE TABLE IF NOT EXISTS api_keys (
                key TEXT PRIMARY KEY,
                payer TEXT,
                plan TEXT,              -- credits | day-pass | pro | whale
                balance_usd REAL,       -- -1 = ilimitado na janela
                created INTEGER,
                expires INTEGER,
                tx_sig TEXT,
                calls_used INTEGER DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_keys_payer ON api_keys(payer);
            CREATE INDEX IF NOT EXISTS idx_keys_tx ON api_keys(tx_sig);
            -- v48.17.10-FUNNEL: um requestId por desafio 402; o cliente v2 ecoa
            -- o accept escolhido (com extra.requestId) no PaymentPayload, e o
            -- settle casa as duas pontas. É o elo probe→pagamento que nenhum
            -- nó x402 mede hoje (pedido do relatório do Beck, out/2026).
            CREATE TABLE IF NOT EXISTS funnel (
                rid TEXT PRIMARY KEY,
                ts INTEGER,
                endpoint TEXT,
                settled INTEGER DEFAULT 0,
                settle_ts INTEGER,
                payer TEXT,
                chain TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_funnel_ts ON funnel(ts);
            """)
            c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('schema_version', ?)",
                      (str(self.SCHEMA_VERSION),))

    def _migrate_legacy(self):
        for src in (LEGACY_V9_DB, LEGACY_V8_DB):
            if not src.exists():
                continue
            try:
                with self._conn() as c:
                    cur = c.execute("SELECT COUNT(*) FROM revenue")
                    existing = cur.fetchone()[0]
                if existing > 0:
                    continue
                log.info(f"📦 Migrando ledger legacy: {src}")
                with sqlite3.connect(src) as legacy:
                    tables = [r[0] for r in legacy.execute(
                        "SELECT name FROM sqlite_master WHERE type='table'")]
                    if "revenue" in tables:
                        rows = legacy.execute(
                            "SELECT ts, endpoint, amount, tx_sig, payer FROM revenue"
                        ).fetchall()
                        with self._conn() as c:
                            for r in rows:
                                c.execute(
                                    "INSERT INTO revenue(ts,endpoint,amount,tx_sig,payer,source,chain) "
                                    "VALUES(?,?,?,?,?,'migrated','solana')", r)
                        log.info(f"   ✅ {len(rows)} receitas migradas de {src.name}")
            except Exception as e:
                log.warning(f"   ⚠️  migração {src.name}: {e}")

    # ---------- REVENUE ----------
    def add_revenue(self, endpoint: str, amount: float, tx_sig: str,
                    payer: str = "", source: str = "direct",
                    chain: str = "solana", jwt_session: str = "",
                    referral_code: str = ""):
        # v43: detecta PRIMEIRO settle deste pagador antes do INSERT — é o
        # evento comercial mais importante do funil (alguém que nunca pagou
        # virou cliente). O operador é avisado na hora, no Telegram.
        _new_buyer = False
        with self.lock, self._conn() as c:
            if payer:
                _new_buyer = c.execute(
                    "SELECT 1 FROM revenue WHERE payer=? LIMIT 1",
                    (payer,)).fetchone() is None
            c.execute("INSERT INTO revenue(ts,endpoint,amount,tx_sig,payer,source,chain,jwt_session,referral_code) "
                      "VALUES(?,?,?,?,?,?,?,?,?)",
                      (int(time.time()), endpoint, amount, tx_sig, payer, source, chain, jwt_session, referral_code))
        if _new_buyer and payer and source != "bootstrap":
            try:
                _is_op = (payer or "").lower() in OPERATOR_WALLETS
            except Exception:
                _is_op = False
            if not _is_op:
                try:
                    _notify_telegram(
                        f"🆕 NOVO COMPRADOR ORGÂNICO\n"
                        f"Carteira: {payer[:24]}...\n"
                        f"Primeira compra: {endpoint} — ${amount:.4f} ({chain})\n"
                        f"É o funil fechando: sondagem → avaliação → PAGAMENTO.")
                except Exception:
                    pass

    # ---------- FUNNEL (v48.17.10) ----------
    _FUNNEL_GC_EVERY = 200

    def funnel_challenge(self, rid: str, endpoint: str) -> None:
        """Registra a emissão de um desafio 402. Nunca pode quebrar a venda:
        qualquer falha aqui é engolida — instrumentação jamais derruba caixa."""
        if not rid:
            return
        try:
            with self.lock, self._conn() as c:
                c.execute("INSERT OR IGNORE INTO funnel(rid,ts,endpoint) VALUES(?,?,?)",
                          (rid, int(time.time()), endpoint))
                # coleta de lixo oportunista: retém 30 dias (~cobre a janela do Bazaar)
                self._funnel_gc_n = getattr(self, "_funnel_gc_n", 0) + 1
                if self._funnel_gc_n >= self._FUNNEL_GC_EVERY:
                    self._funnel_gc_n = 0
                    c.execute("DELETE FROM funnel WHERE ts < ?",
                              (int(time.time()) - 30 * 86400,))
        except Exception:
            pass

    def funnel_settle(self, rid: str, payer: str = "", chain: str = "") -> bool:
        """Casa o pagamento com o desafio que o originou (requestId ecoado no
        accept do PaymentPayload v2). True quando o elo foi fechado."""
        if not rid:
            return False
        try:
            with self.lock, self._conn() as c:
                cur = c.execute(
                    "UPDATE funnel SET settled=1, settle_ts=?, payer=?, chain=? "
                    "WHERE rid=? AND settled=0",
                    (int(time.time()), payer or "", chain or "", rid))
                return cur.rowcount > 0
        except Exception:
            return False

    def funnel_stats(self, window_s: int = 7 * 86400) -> Dict[str, Any]:
        """Conversão desafio→pagamento na janela (padrão: 7 dias)."""
        out = {"window_seconds": window_s, "challenges": 0, "settled": 0,
               "conversion_rate": None, "median_seconds_to_pay": None,
               "note": ("requestId issued in every 402 challenge, echoed back in "
                        "the v2 PaymentPayload accepted.extra — links a probe to "
                        "the wallet that later paid, per endpoint.")}
        try:
            since = int(time.time()) - window_s
            with self._conn() as c:  # leitura sem lock (WAL)
                n_ch = c.execute("SELECT COUNT(*) FROM funnel WHERE ts>?",
                                 (since,)).fetchone()[0]
                rows = c.execute(
                    "SELECT settle_ts - ts FROM funnel WHERE ts>? AND settled=1",
                    (since,)).fetchall()
            deltas = sorted(r[0] for r in rows if r and r[0] is not None)
            out["challenges"] = int(n_ch)
            out["settled"] = len(deltas)
            out["conversion_rate"] = (round(len(deltas) / n_ch, 6) if n_ch else None)
            if deltas:
                out["median_seconds_to_pay"] = int(deltas[len(deltas) // 2])
        except Exception:
            pass
        return out


    def stats(self) -> Dict[str, Any]:
        with self._conn() as c:
            now = int(time.time())
            total = c.execute("SELECT COALESCE(SUM(amount),0) FROM revenue").fetchone()[0]
            today = c.execute("SELECT COALESCE(SUM(amount),0) FROM revenue WHERE ts > ?",
                              (now - 86400,)).fetchone()[0]
            hour = c.execute("SELECT COALESCE(SUM(amount),0) FROM revenue WHERE ts > ?",
                             (now - 3600,)).fetchone()[0]
            reqs = c.execute("SELECT COUNT(*) FROM requests WHERE ts > ?",
                             (now - 86400,)).fetchone()[0]
            paid = c.execute("SELECT COUNT(*) FROM revenue WHERE ts > ?",
                             (now - 86400,)).fetchone()[0]
            by_chain = dict(c.execute(
                "SELECT chain, COALESCE(SUM(amount),0) FROM revenue GROUP BY chain"
            ).fetchall())
            buyers = c.execute("SELECT COUNT(DISTINCT payer) FROM revenue WHERE payer<>''").fetchone()[0]
            by_endpoint = dict(c.execute(
                "SELECT endpoint, COUNT(*) FROM revenue WHERE ts > ? GROUP BY endpoint",
                (now - 86400,)
            ).fetchall())
            # v24.5: separa avaliadores (preview) de sondagens de scanner
            try:
                previews = c.execute("SELECT COUNT(*) FROM requests WHERE ts>? AND kind='preview'",
                                     (now - 86400,)).fetchone()[0]
                probes = c.execute(
                    "SELECT COUNT(*) FROM requests WHERE ts>? AND (kind='probe' OR kind='' "
                    "OR kind='challenge402')", (now - 86400,)).fetchone()[0]
                challenges = c.execute(
                    "SELECT COUNT(*) FROM requests WHERE ts>? AND kind='challenge402'",
                    (now - 86400,)).fetchone()[0]
            except Exception:
                previews, probes, challenges = 0, reqs, 0
            paid_total = c.execute("SELECT COUNT(*) FROM revenue").fetchone()[0]
            # v24.5: QUEM está sondando — separa scanner conhecido de cliente novo
            try:
                top_uas = c.execute(
                    "SELECT COALESCE(NULLIF(ua,''),'(sem user-agent)') u, COUNT(*) n, "
                    "COUNT(DISTINCT ip) ips FROM requests WHERE ts>? "
                    "GROUP BY u ORDER BY n DESC LIMIT 8", (now - 86400,)).fetchall()
                top_uas = [{"ua": r[0][:60], "hits": r[1], "ips": r[2]} for r in top_uas]
            except Exception:
                top_uas = []
            # v28.2: QUEM são os "avaliadores"? Sem isto não dá para saber se os
            # previews vêm de agentes de verdade avaliando antes de comprar, ou
            # do mesmo poller que já domina as sondagens. É a diferença entre
            # "temos prospectos" e "temos um robô curioso".
            try:
                preview_uas = c.execute(
                    "SELECT COALESCE(NULLIF(ua,''),'(sem user-agent)') u, COUNT(*) n, "
                    "COUNT(DISTINCT ip) ips FROM requests "
                    "WHERE ts>? AND kind='preview' "
                    "GROUP BY u ORDER BY n DESC LIMIT 8", (now - 86400,)).fetchall()
                preview_uas = [{"ua": r[0][:60], "hits": r[1], "ips": r[2]}
                               for r in preview_uas]
            except Exception:
                preview_uas = []
            try:  # v37: quantas avaliações foram recusadas pelo experimento
                preview_blocked = c.execute(
                    "SELECT COUNT(*) FROM requests WHERE ts>? AND kind='preview_blocked'",
                    (now - 86400,)).fetchone()[0]
            except Exception:
                preview_blocked = 0
            # v29: O QUE AS MÁQUINAS PEDEM ------------------------------------
            try:  # caminhos inexistentes = pedidos de produto
                demand_404 = [{"path": r[0], "hits": r[1], "ips": r[2], "ua": (r[3] or "")[:40],
                               **_demand_classify_ml(r[0])}
                    for r in c.execute(
                    "SELECT endpoint, COUNT(*) n, COUNT(DISTINCT ip), "
                    "COALESCE(NULLIF(ua,''),'?') FROM requests "
                    "WHERE ts>? AND kind='notfound' GROUP BY endpoint "
                    "ORDER BY n DESC LIMIT 10", (now - 604800,)).fetchall()]
            except Exception:
                demand_404 = []
            try:  # parâmetros mais pedidos = quais ativos interessam
                demand_params = [{"endpoint": r[0], "params": r[1], "hits": r[2],
                                  "ips": r[3]} for r in c.execute(
                    "SELECT endpoint, params, COUNT(*) n, COUNT(DISTINCT ip) "
                    "FROM requests WHERE ts>? AND params<>'' "
                    "GROUP BY endpoint, params ORDER BY n DESC LIMIT 12",
                    (now - 604800,)).fetchall()]
            except Exception:
                demand_params = []
            try:  # quais endpoints recebem mais SONDAGENS (não só vendas)
                probe_targets = [{"endpoint": r[0], "probes": r[1], "ips": r[2]}
                    for r in c.execute(
                    "SELECT endpoint, COUNT(*) n, COUNT(DISTINCT ip) FROM requests "
                    "WHERE ts>? AND kind IN ('probe','preview') "
                    "GROUP BY endpoint ORDER BY n DESC LIMIT 12", (now - 86400,)).fetchall()]
            except Exception:
                probe_targets = []
        win = self.win_rate()
        return {
            "total_usdc":     round(total, 6),
            "today_usdc":     round(today, 6),
            # v42.1 FIX: /live/api lia a chave "revenue_24h", que nunca existiu
            # — a página pública mostrava "$0.0000" com 32 settlements no ar.
            "revenue_24h":    round(today, 6),
            "hour_usdc":      round(hour, 6),
            "requests_24h":   reqs,
            "paid_24h":       paid,
            "conv_rate":      round((paid / reqs * 100) if reqs else 0, 1),
            "win_rate":       round(win, 1),
            "by_chain":       {k: round(v, 6) for k, v in by_chain.items()},
            "by_endpoint":    by_endpoint,
            "buyers":         buyers,
            "poi_multiplier": round(self.get_poi_multiplier(), 3),
            "previews_24h":   previews,
            "probes_24h":     probes,
            "challenges_24h": challenges,
            "top_uas":        top_uas,
            "preview_uas":    preview_uas,
            "preview_blocked_24h": preview_blocked,
            "paywall_active":  sorted(PREVIEW_PAYWALL),
            "demand_404":     demand_404,
            "demand_params":  demand_params,
            "probe_targets":  probe_targets,
            "paid_total":     paid_total,
            "avg_ticket":     round((total / paid_total) if paid_total else 0, 4),
            "conv_evaluators": round((paid / (paid + previews) * 100)
                                     if (paid + previews) else 0, 1),
        }

    _req_kind_ready = False
    def log_request(self, endpoint: str, ok: bool, latency_ms: int, ip: str,
                    kind: str = "probe", ua: str = "", params: str = ""):
        # v24.5: kind classifica o tráfego — 'probe' (scanner/402), 'preview'
        # (avaliador usando ?preview=1) ou 'paid' (venda liquidada/créditos/JWT).
        # ua identifica QUEM sonda (scanner conhecido × cliente novo).
        with self.lock, self._conn() as c:
            if not LedgerV10._req_kind_ready:
                for ddl in ("ALTER TABLE requests ADD COLUMN kind TEXT DEFAULT ''",
                            "ALTER TABLE requests ADD COLUMN ua TEXT DEFAULT ''",
                            # v29: o QUE a máquina pediu — parâmetros e caminhos
                            # inexistentes. Sem isto sabíamos QUEM sondava, mas
                            # não o que procurava. É a diferença entre contar
                            # visitantes e entender demanda.
                            "ALTER TABLE requests ADD COLUMN params TEXT DEFAULT ''"):
                    try:
                        c.execute(ddl)
                    except Exception:
                        pass
                LedgerV10._req_kind_ready = True
            c.execute("INSERT INTO requests(ts,endpoint,ok,latency_ms,ip,kind,ua,params) "
                      "VALUES(?,?,?,?,?,?,?,?)",
                      (int(time.time()), endpoint, 1 if ok else 0, latency_ms, ip,
                       kind, (ua or "")[:120], (params or "")[:160]))

    def replay_check(self, h: str) -> bool:
        with self.lock, self._conn() as c:
            r = c.execute("SELECT 1 FROM replay WHERE hash=?", (h,)).fetchone()
            if r:
                return True
            c.execute("INSERT INTO replay(hash, ts) VALUES(?,?)", (h, int(time.time())))
            c.execute("DELETE FROM replay WHERE ts < ?", (int(time.time()) - 86400 * 7,))
            return False

    def replay_delete(self, h: str) -> bool:
        with self.lock, self._conn() as c:
            c.execute("DELETE FROM replay WHERE hash=?", (h,))
            return c.rowcount > 0

    # ---------- SIGNALS ----------
    def add_signal(self, symbol: str, action: str, confidence: float, price: float):
        with self.lock, self._conn() as c:
            c.execute("INSERT INTO signals(ts,symbol,action,confidence,price_at) "
                      "VALUES(?,?,?,?,?)",
                      (int(time.time()), symbol, action, confidence, price))

    def pending_signals(self, max_age=86400):
        with self._conn() as c:
            cutoff = int(time.time()) - max_age
            return c.execute(
                "SELECT id,symbol,action,price_at,ts FROM signals "
                "WHERE result IS NULL AND ts > ?", (cutoff,)
            ).fetchall()

    def validate_signal(self, sid: int, current_price: float):
        with self.lock, self._conn() as c:
            r = c.execute("SELECT action, price_at FROM signals WHERE id=?", (sid,)).fetchone()
            if not r: return
            action, p0 = r
            pnl = ((current_price - p0) / p0 * 100) if action in ("buy", "long") else \
                  ((p0 - current_price) / p0 * 100) if action in ("sell", "short") else 0
            result = "win" if pnl > 0 else "loss"
            c.execute("UPDATE signals SET result=?, pnl_pct=?, validated_at=? WHERE id=?",
                      (result, pnl, int(time.time()), sid))

    def win_rate(self) -> float:
        with self._conn() as c:
            cutoff = int(time.time()) - 30 * 86400
            r = c.execute(
                "SELECT COUNT(*), SUM(CASE WHEN result='win' THEN 1 ELSE 0 END) "
                "FROM signals WHERE result IS NOT NULL AND ts > ?", (cutoff,)
            ).fetchone()
            total, wins = r or (0, 0)
            if not total:
                return BASE_WIN_RATE
            return (wins or 0) * 100.0 / total

    def get_poi_multiplier(self) -> float:
        win = self.win_rate()
        if win >= 70: return 1.5
        if win >= 60: return 1.2
        if win >= 50: return 1.0
        if win >= 40: return 0.8
        return 0.5

    # ---------- CACHE ----------
    def cache_get(self, key: str, ttl: int):
        with self._conn() as c:
            r = c.execute("SELECT value, ts FROM cache WHERE key=?", (key,)).fetchone()
            if not r:
                return None
            value, ts = r
            if int(time.time()) - ts > ttl:
                return None
            try:
                return json.loads(value)
            except Exception:
                return None

    def cache_set(self, key: str, value: Any):
        with self.lock, self._conn() as c:
            c.execute("INSERT OR REPLACE INTO cache(key,value,ts) VALUES(?,?,?)",
                      (key, json.dumps(value, default=str), int(time.time())))

    # ---------- JWT SESSIONS ----------
    def jwt_save(self, jti: str, payer: str, endpoint: str, tx_sig: str, ttl: int):
        with self.lock, self._conn() as c:
            now = int(time.time())
            c.execute("INSERT OR REPLACE INTO jwt_sessions(jti,payer,endpoint,ts,exp,tx_sig) "
                      "VALUES(?,?,?,?,?,?)",
                      (jti, payer, endpoint, now, now + ttl, tx_sig))

    def jwt_valid(self, jti: str, endpoint: str) -> bool:
        with self._conn() as c:
            r = c.execute(
                "SELECT exp FROM jwt_sessions WHERE jti=? AND endpoint=?",
                (jti, endpoint)
            ).fetchone()
            if not r:
                return False
            return int(time.time()) < r[0]

    # ---------- PEERS ----------
    def upsert_peer(self, node_id: str, url: str, public_key: str, win_rate: float = 50.0):
        with self.lock, self._conn() as c:
            c.execute(
                "INSERT INTO peers(node_id,url,public_key,last_seen,win_rate) "
                "VALUES(?,?,?,?,?) ON CONFLICT(node_id) DO UPDATE SET "
                "url=excluded.url, last_seen=excluded.last_seen, win_rate=excluded.win_rate",
                (node_id, url, public_key, int(time.time()), win_rate))

    def active_peers(self, max_age=600):
        with self._conn() as c:
            cutoff = int(time.time()) - max_age
            return c.execute(
                "SELECT node_id,url,reputation,win_rate FROM peers WHERE last_seen > ? "
                "ORDER BY reputation DESC LIMIT 50", (cutoff,)
            ).fetchall()

    def log_sweep(self, amount: float, tx_sig: str, dest: str):
        with self.lock, self._conn() as c:
            c.execute("INSERT INTO sweeps(ts,amount,tx_sig,dest) VALUES(?,?,?,?)",
                      (int(time.time()), amount, tx_sig, dest))

    # ---------- REFERRAL ----------
    def create_referral(self, code: str, owner: str) -> bool:
        with self.lock, self._conn() as c:
            try:
                c.execute("INSERT INTO referrals(code, owner, created) VALUES(?,?,?)",
                          (code, owner, int(time.time())))
                return True
            except sqlite3.IntegrityError:
                return False

    def get_referral(self, code: str) -> Optional[Dict]:
        with self._conn() as c:
            r = c.execute("SELECT code, owner, total_commission FROM referrals WHERE code=?", (code,)).fetchone()
            if not r:
                return None
            return {"code": r[0], "owner": r[1], "total_commission": r[2]}

    def add_referral_use(self, code: str, buyer: str, amount: float, commission: float):
        with self.lock, self._conn() as c:
            c.execute("INSERT INTO referral_uses(code, buyer, ts, amount, commission) VALUES(?,?,?,?,?)",
                      (code, buyer, int(time.time()), amount, commission))
            c.execute("UPDATE referrals SET total_commission = total_commission + ? WHERE code=?",
                      (commission, code))

    # ---------- STAKE ----------
    def add_stake(self, staker: str, amount: float, tx_sig: str):
        with self.lock, self._conn() as c:
            c.execute("INSERT INTO stakes(staker, amount, ts, tx_sig) VALUES(?,?,?,?)",
                      (staker, amount, int(time.time()), tx_sig))

    def get_stakes(self, staker: str = None):
        with self._conn() as c:
            if staker:
                return c.execute("SELECT * FROM stakes WHERE staker=? AND status='active'", (staker,)).fetchall()
            return c.execute("SELECT * FROM stakes WHERE status='active'").fetchall()


    # --- v23: replay SEGURO (marca só após settle — não bloqueia retry legítimo) ---
    def replay_seen(self, h: str) -> bool:
        with self._conn() as c:
            return c.execute("SELECT 1 FROM replay WHERE hash=?", (h,)).fetchone() is not None

    def replay_mark(self, h: str):
        with self.lock, self._conn() as c:
            c.execute("INSERT OR IGNORE INTO replay(hash,ts) VALUES(?,?)", (h, int(time.time())))
            c.execute("DELETE FROM replay WHERE ts < ?", (int(time.time()) - 86400*7,))

    def replay_claim(self, h: str) -> bool:
        """Reserva atômica: True só para QUEM inseriu a linha.

        v41.1 — `replay_seen()` seguido de `replay_mark()` não é seguro sob
        concorrência: entre a leitura e a escrita cabe outra thread inteira, e
        o gunicorn roda com --threads 8. `INSERT OR IGNORE` sozinho também não
        resolve, porque não distingue "inseri" de "já existia". Aqui o
        rowcount decide: 1 = ganhei a corrida, 0 = alguém chegou antes.
        É o mesmo padrão que protege um cupom de uso único em qualquer
        checkout — e aqui o que está em jogo é entrega de produto grátis.
        """
        with self.lock, self._conn() as c:
            cur = c.execute("INSERT OR IGNORE INTO replay(hash,ts) VALUES(?,?)",
                            (h, int(time.time())))
            return cur.rowcount == 1

    def replay_unmark(self, h: str):
        """Devolve a reserva quando a falha foi nossa, não do cliente."""
        try:
            with self.lock, self._conn() as c:
                c.execute("DELETE FROM replay WHERE hash=?", (h,))
        except Exception as e:
            log.debug(f"replay_unmark {h[:24]}: {e}")

    def tx_recorded(self, tx_sig: str) -> bool:
        if not tx_sig:
            return False
        with self._conn() as c:
            return c.execute("SELECT 1 FROM revenue WHERE tx_sig=?", (tx_sig,)).fetchone() is not None

    # --- v23: CRÉDITOS / PASSES ---
    def api_key_create(self, key: str, payer: str, plan: str, balance_usd: float,
                       ttl_seconds: int, tx_sig: str = ""):
        with self.lock, self._conn() as c:
            c.execute("""INSERT INTO api_keys(key,payer,plan,balance_usd,created,expires,tx_sig)
                         VALUES(?,?,?,?,?,?,?)""",
                      (key, payer, plan, balance_usd, int(time.time()),
                       int(time.time()) + ttl_seconds, tx_sig))

    def api_key_by_tx(self, tx_sig: str):
        """Idempotência: se a mesma tx já gerou uma key, retorna ela (retry seguro)."""
        if not tx_sig:
            return None
        with self._conn() as c:
            r = c.execute("SELECT key, plan, balance_usd, expires FROM api_keys WHERE tx_sig=?",
                          (tx_sig,)).fetchone()
        return {"key": r[0], "plan": r[1], "balance_usd": r[2], "expires": r[3]} if r else None

    def api_key_get(self, key: str):
        with self._conn() as c:
            r = c.execute("""SELECT payer, plan, balance_usd, created, expires, calls_used, tx_sig
                             FROM api_keys WHERE key=?""", (key,)).fetchone()
        if not r:
            return None
        return {"payer": r[0], "plan": r[1], "balance_usd": r[2], "created": r[3],
                "expires": r[4], "calls_used": r[5], "tx_sig": r[6]}

    def api_key_use(self, key: str, cost: float):
        """Débito atômico. Retorna dict com remaining ou None se inválida/expirada/sem saldo."""
        with self.lock, self._conn() as c:
            r = c.execute("SELECT balance_usd, expires FROM api_keys WHERE key=?", (key,)).fetchone()
            if not r:
                return None
            bal, exp = r
            if exp and int(time.time()) > exp:
                return None
            if bal is not None and bal >= 0 and bal < cost:
                return None
            if bal is None or bal < 0:  # ilimitado
                c.execute("UPDATE api_keys SET calls_used=calls_used+1 WHERE key=?", (key,))
                return {"remaining": -1, "unlimited": True, "expires": exp}
            new_bal = round(bal - cost, 6)
            c.execute("UPDATE api_keys SET balance_usd=?, calls_used=calls_used+1 WHERE key=?",
                      (new_bal, key))
            return {"remaining": new_bal, "unlimited": False, "expires": exp}

    def api_key_credit(self, key: str, amount: float):
        """v48.10.2-REFUND: recrédito atômico — delivery-or-refund no caminho
        de créditos (handler falhou depois do débito, o saldo volta)."""
        with self.lock, self._conn() as c:
            r = c.execute("SELECT balance_usd FROM api_keys WHERE key=?", (key,)).fetchone()
            if not r:
                return None
            bal = r[0]
            if bal is None or bal < 0:  # ilimitado — nada a recreditar
                return {"remaining": -1, "unlimited": True}
            new_bal = round(bal + amount, 6)
            c.execute("UPDATE api_keys SET balance_usd=? WHERE key=?", (new_bal, key))
            return {"remaining": new_bal, "unlimited": False}

    def api_key_stats(self):
        with self._conn() as c:
            total = c.execute("SELECT COUNT(*) FROM api_keys").fetchone()[0]
            active = c.execute("SELECT COUNT(*) FROM api_keys WHERE expires > ?",
                               (int(time.time()),)).fetchone()[0]
            calls = c.execute("SELECT COALESCE(SUM(calls_used),0) FROM api_keys").fetchone()[0]
        return {"keys_total": total, "keys_active": active, "calls_via_credits": calls}

