class Market:
    @staticmethod
    def _cached(key, fn, ttl=30):
        v = LEDGER.cache_get(key, ttl)
        if v is not None:
            return v
        try:
            v = fn()
            if v is not None:
                LEDGER.cache_set(key, v)
            return v
        except Exception as e:
            log.warning(f"market {key}: {e}")
            return None

    @classmethod
    def fear_greed(cls):
        def f():
            r = requests.get("https://api.alternative.me/fng/", timeout=10).json()
            d = r["data"][0]
            return {"value": int(d["value"]), "classification": d["value_classification"],
                    "ts": d["timestamp"]}
        return cls._cached("fng", f, 600) or {"value": 50, "classification": "Neutral"}

    @classmethod
    def top_coins(cls, n=20):
        def f():
            headers = {"Accept": "application/json"}
            if COINGECKO_KEY:
                headers["x-cg-pro-api-key"] = COINGECKO_KEY
            r = requests.get("https://api.coingecko.com/api/v3/coins/markets",
                params={"vs_currency": "usd", "order": "market_cap_desc",
                        "per_page": n, "page": 1,
                        "price_change_percentage": "1h,24h,7d"},
                timeout=15, headers=headers)
            return r.json() if r.ok else []
        return cls._cached(f"top_{n}", f, 60) or []

    @classmethod
    def binance_24h(cls):
        def f():
            # v44.3.1 — FONTE MORTA NÃO PODE VIRAR PRODUTO VAZIO.
            # api.binance.com responde 451 (região restrita) para vários IPs de
            # cloud — inclusive o do Railway. Com r.ok=False o código devolvia
            # [] e /anomalias, /arbitrage e /forex-arbitrage serviam listas
            # vazias PAGAS. Agora: 5 hosts Binance e, se todos falharem,
            # CoinGecko /coins/markets normalizado para o MESMO shape
            # (symbol *USDT, priceChangePercent, quoteVolume, lastPrice).
            # v44.6.0: data-api.binance.vision é o espelho PÚBLICO de market
            # data da própria Binance (só /api/v3/*, sem conta/saque) e não
            # sofre o 451 geo-regulatório do host principal — vai primeiro.
            for host in ("https://data-api.binance.vision",
                         "https://api.binance.com", "https://api1.binance.com",
                         "https://api2.binance.com", "https://api3.binance.com",
                         "https://api4.binance.com"):
                try:
                    r = requests.get(host + "/api/v3/ticker/24hr", timeout=12)
                    if r.ok:
                        return r.json()
                except Exception:
                    continue
            try:
                r = requests.get("https://api.coingecko.com/api/v3/coins/markets",
                                 params={"vs_currency": "usd", "order": "volume_desc",
                                         "per_page": "250", "page": "1",
                                         "price_change_percentage": "24h"},
                                 timeout=15)
                if r.ok:
                    out = []
                    for c in r.json():
                        sym = (c.get("symbol") or "").upper()
                        if not sym:
                            continue
                        out.append({
                            "symbol": sym + "USDT",
                            "priceChangePercent": str(c.get("price_change_percentage_24h") or 0),
                            "quoteVolume": str(c.get("total_volume") or 0),
                            "lastPrice": str(c.get("current_price") or 0),
                        })
                    if out:
                        log.info("binance_24h: servindo fallback CoinGecko "
                                 f"({len(out)} símbolos) — Binance inalcançável")
                        return out
            except Exception:
                pass
            return []
        return cls._cached("binance_24h", f, 60) or []

    @classmethod
    def jupiter_quote(cls, input_mint, output_mint, amount=1000000):
        def f():
            headers = {}
            if JUPITER_KEY:
                headers["x-api-key"] = JUPITER_KEY
            for base_url in ["https://api.jup.ag/swap/v1/quote",
                             "https://lite-api.jup.ag/swap/v1/quote"]:
                try:
                    r = requests.get(base_url, params={
                        "inputMint": input_mint, "outputMint": output_mint,
                        "amount": str(amount), "slippageBps": "50"
                    }, timeout=10, headers=headers)
                    if r.ok:
                        return r.json()
                except Exception:
                    continue
            return {}
        return cls._cached(f"jup_{input_mint}_{output_mint}_{amount}", f, 15) or {}

    @classmethod
    def raydium_pools(cls):
        def f():
            r = requests.get("https://api-v3.raydium.io/pools/info/list",
                params={"poolType": "all", "poolSortField": "liquidity",
                        "sortType": "desc", "pageSize": 30, "page": 1},
                timeout=10)
            return r.json() if r.ok else {}
        return cls._cached("ray_pools", f, 60) or {}

    @classmethod
    def pump_new(cls):
        def f():
            try:
                r = requests.get("https://api.dexscreener.com/token-profiles/latest/v1",
                                 timeout=10)
                if r.ok:
                    return r.json()
            except Exception:
                pass
            return []
        return cls._cached("pump_new", f, 30) or []

    @classmethod
    def whale_alert(cls, min_usd=100000):
        def f():
            data = cls.binance_24h() or []
            whales = []
            for d in data:
                qv = float(d.get("quoteVolume", 0))
                if qv > min_usd:
                    whales.append({
                        "symbol": d["symbol"],
                        "volume_24h": qv,
                        "price_change": float(d.get("priceChangePercent", 0)),
                        "price": float(d.get("lastPrice", 0)),
                    })
            whales.sort(key=lambda x: -x["volume_24h"])
            return whales[:25]
        return cls._cached("whales", f, 120) or []

