_WMO_CODES = {
    0: "clear sky", 1: "mainly clear", 2: "partly cloudy", 3: "overcast",
    45: "fog", 48: "depositing rime fog",
    51: "light drizzle", 53: "drizzle", 55: "dense drizzle",
    56: "light freezing drizzle", 57: "freezing drizzle",
    61: "light rain", 63: "rain", 65: "heavy rain",
    66: "light freezing rain", 67: "freezing rain",
    71: "light snow", 73: "snow", 75: "heavy snow", 77: "snow grains",
    80: "light showers", 81: "showers", 82: "violent showers",
    85: "light snow showers", 86: "snow showers",
    95: "thunderstorm", 96: "thunderstorm with light hail",
    99: "thunderstorm with hail",
}


def _wmo_code(c) -> str:
    try:
        return _WMO_CODES.get(int(c), f"wmo code {c}")
    except Exception:
        return "unknown"


def _ig(lst, i):
    """Index-get tolerante: listas hourly/daily da API podem vir curtas."""
    try:
        return lst[i] if i < len(lst) else None
    except Exception:
        return None


class Brain:
    # ---------- CHEAP TIER ----------
    @staticmethod
    def fear_greed():
        d = Market.fear_greed()
        v = d.get("value", 50)
        interp = ("Extreme fear \u2014 historically a contrarian buy zone" if v < 25 else
                  "Fear — elevated caution; contrarian buy zone historically"                          if v < 45 else
                  "Neutral — balanced market, no strong contrarian edge"                       if v < 55 else
                  "Greed \u2014 correction risk rising"                   if v < 75 else
                  "Extreme greed \u2014 elevated risk of a local top")
        return {"value": v, "classification": d.get("classification"),
                "interpretation": interp, "version": VERSION}

    @staticmethod
    def regime():
        top = Market.top_coins(10)
        if not top:
            return {"regime": "unknown", "confidence": 0.0}
        ch24 = [c.get("price_change_percentage_24h") or 0 for c in top]
        ch7d = [c.get("price_change_percentage_7d_in_currency") or 0 for c in top]
        mean24 = sum(ch24) / len(ch24)
        mean7d = sum(ch7d) / len(ch7d)
        vol = (sum((x - mean24) ** 2 for x in ch24) / len(ch24)) ** 0.5
        if mean7d > 5 and mean24 > 1:
            regime = "bull-strong"
        elif mean7d > 1:
            regime = "bull-weak"
        elif mean7d < -5 and mean24 < -1:
            regime = "bear-strong"
        elif mean7d < -1:
            regime = "bear-weak"
        elif vol > 4:
            regime = "transition"
        else:
            regime = "range"
        conf = min(1.0, abs(mean7d) / 10)
        return {"regime": regime, "confidence": round(conf, 2),
                "mean_24h_pct": round(mean24, 2), "mean_7d_pct": round(mean7d, 2),
                "volatility": round(vol, 2), "version": VERSION}

    @staticmethod
    def mempool():
        fees = SOL.get_priority_fees()
        return {
            "priority_fee_lamports": fees,
            "fee_usd_estimate": round(fees.get("mean", 0) / 1e9 * 200, 6),
            "network_load": "high" if fees.get("p90", 0) > 100000 else "normal",
            "ts": int(time.time()),
            "version": VERSION,
        }

    @staticmethod
    def anomalias():
        data = Market.binance_24h() or []

        def _scan(limiar):
            out = []
            for d in data:
                try:
                    ch = float(d.get("priceChangePercent", 0))
                    vol = float(d.get("quoteVolume", 0))
                    if abs(ch) >= limiar and vol > 1e6 and d["symbol"].endswith("USDT"):
                        out.append({
                            "symbol": d["symbol"], "change_pct": ch,
                            "volume_usd": round(vol, 0),
                            "type": "pump" if ch > 0 else "dump",
                        })
                except Exception:
                    pass
            out.sort(key=lambda x: -abs(x["change_pct"]))
            return out

        # v44.3.0: mercado quieto NÃO pode devolver vitrine vazia — era a
        # amostra pública do endpoint e um count=0 parecia produto quebrado.
        # Desce o limiar em degraus e sempre lista os maiores movimentos do
        # dia, rotulados com o limiar de fato usado. Dado real, rótulo honesto.
        anomalies, limiar = [], 15
        for limiar in (15, 8, 3, 0):
            anomalies = _scan(limiar)
            if anomalies:
                break
        fortes = [a for a in anomalies if abs(a["change_pct"]) >= 15]
        return {"count": len(fortes), "top": anomalies[:15],
                "threshold_pct": limiar,
                "market_state": "active" if fortes else "quiet",
                "note": (None if fortes else
                         f"No anomalies above 15% in the last 24h — listing the "
                         f"largest moves above {limiar}% instead."),
                "version": VERSION}

    @staticmethod
    def jupiter_swap():
        inp = request.args.get("input", USDC_MINT)
        out = request.args.get("output", "So11111111111111111111111111111111111111112")
        amt = int(request.args.get("amount", "1000000"))
        q = Market.jupiter_quote(inp, out, amt)
        return {
            "input_mint": inp, "output_mint": out, "amount_in": amt,
            "amount_out": q.get("outAmount"),
            "price_impact_pct": q.get("priceImpactPct"),
            "route_plan_steps": len(q.get("routePlan", [])),
            "raw": q if request.args.get("verbose") == "1" else None,
            "version": VERSION,
        }

    # ---------- MID TIER ----------
    @staticmethod
    def analise():
        top = Market.top_coins(5)
        fg = Market.fear_greed()
        ctx = "\n".join([f"{c['symbol'].upper()}: ${c.get('current_price')} "
                         f"({(c.get('price_change_percentage_24h') or 0):.1f}% 24h)"
                         for c in top])
        memory = RAG_STORE.retrieve("market analysis btc eth sol", k=3)
        memory_str = "\n".join([f"- {m[1][:120]}" for m in memory])
        # v41.1: o prompt continuava em PT mesmo depois do patch v41. O sufixo
        # LLM_FORCE_ENGLISH corrige o IDIOMA da saída, mas um prompt em PT com
        # instrução em inglês no fim produz texto pior que um prompt nativo —
        # o modelo gasta atenção reconciliando duas línguas em vez de analisar.
        prompt = (f"You are a crypto market analyst. Fear & Greed index: "
                  f"{fg.get('value')} ({fg.get('classification', 'n/a')}).\n"
                  f"Top 5 coins by market cap:\n{ctx}\n\n"
                  f"Recent context from prior analyses:\n{memory_str}\n\n"
                  f"Write a concise analysis: exactly 4 bullet points covering "
                  f"momentum, flows, positioning risk and the level that would "
                  f"invalidate the read, then one line with the directional bias "
                  f"(bullish / neutral / bearish) and your confidence. "
                  f"No preamble. Not financial advice.")
        # v39: era LLM.ask() cru. Quando a cadeia caía, a string
        # "[LLM offline — configure ...]" ia direto para dentro da resposta
        # PAGA e ainda era ingerida no RAG, envenenando as buscas seguintes.
        analysis = _ai_required(prompt, max_tokens=400)
        RAG_STORE.ingest("analise", analysis)
        return {"fear_greed": fg, "top_5": top, "analysis": analysis,
                "ai_status": "ok", "version": VERSION}

    @staticmethod
    def swarm_vote():
        peers = LEDGER.active_peers()
        votes = []
        for node_id, url, _rep, _wr in peers[:10]:
            try:
                r = requests.get(f"{url}/health", timeout=3)
                if r.ok:
                    votes.append({"node": node_id[:8], "online": True})
            except Exception:
                votes.append({"node": node_id[:8], "online": False})
        regime = Brain.regime()
        return {"swarm_size": len(peers), "votes": votes,
                "consensus_regime": regime.get("regime"),
                "version": VERSION}

    @staticmethod
    def sentiment(symbol: str = None):
        # v23: symbol parametrizável (market_brief chamava sem request ctx e
        # devolvia o MESMO sentimento p/ BTC, ETH e SOL)
        if not symbol:
            try:
                symbol = request.args.get("symbol", "BTC")
            except RuntimeError:
                symbol = "BTC"
        symbol = symbol.upper()
        top = Market.top_coins(50)
        coin = next((c for c in top if (c.get("symbol") or "").upper() == symbol), None)
        if not coin:
            return {"symbol": symbol, "sentiment": "neutral", "score": 0.0,
                    "version": VERSION}
        ch24 = coin.get("price_change_percentage_24h") or 0
        ch7d = coin.get("price_change_percentage_7d_in_currency") or 0
        fg = Market.fear_greed().get("value", 50)
        score = (ch24 * 0.4 + ch7d * 0.3 + (fg - 50) * 0.6) / 30
        score = max(-1.0, min(1.0, score))
        sent = "bullish" if score > 0.2 else "bearish" if score < -0.2 else "neutral"
        return {"symbol": symbol, "sentiment": sent, "score": round(score, 3),
                "fear_greed": fg, "ch_24h": ch24, "ch_7d": ch7d,
                "version": VERSION}

    @staticmethod
    def rugcheck():
        mint = request.args.get("mint", "").strip()
        # v44.0.9: sem ?mint=, o default útil é o lançamento Solana mais fresco
        # (o caso de uso real do produto) — nunca erro cru pago (v21.11).
        if not mint or len(mint) < 32:
            try:
                _fresh = [t for t in (Market.pump_new() or [])
                          if t.get("chainId") == "solana"
                          and len(t.get("tokenAddress", "")) >= 32]
                mint = _fresh[0]["tokenAddress"] if _fresh else USDC_MINT
            except Exception:
                mint = USDC_MINT
        risk = {"mint": mint, "checks": {}, "risk_level": "unknown", "score": 50,
                "hint": "passe ?mint=<token_address> para auditar qualquer token"}
        try:
            if HELIUS_KEY:
                r = requests.post(f"https://mainnet.helius-rpc.com/?api-key={HELIUS_KEY}",
                    json={"jsonrpc":"2.0","id":1,"method":"getAsset",
                          "params":{"id": mint}}, timeout=8)
                if r.ok:
                    asset = r.json().get("result", {})
                    auth = asset.get("authorities", [])
                    risk["checks"]["mint_authority_renounced"] = not bool(auth)
                    risk["checks"]["mutable"] = asset.get("mutable", True)
        except Exception:
            pass
        ok_count = sum(1 for v in risk["checks"].values() if v is True)
        risk["score"] = 30 + ok_count * 20
        risk["risk_level"] = ("high" if risk["score"] < 50 else
                              "medium" if risk["score"] < 75 else "low")
        risk["version"] = VERSION
        return risk

    @staticmethod
    def sinais():
        top = Market.top_coins(20)
        signals = []
        for c in top:
            ch24 = c.get("price_change_percentage_24h") or 0
            ch7d = c.get("price_change_percentage_7d_in_currency") or 0
            ch1h = c.get("price_change_percentage_1h_in_currency") or 0
            sym = (c.get("symbol") or "").upper()
            if ch1h > 1 and ch24 > 3 and ch7d > 5:
                conf = min(0.95, (ch1h + ch24 + ch7d) / 100)
                price = c.get("current_price", 0)
                LEDGER.add_signal(sym, "buy", conf, price)
                signals.append({"symbol": sym, "action": "buy",
                                "confidence": round(conf, 2), "price": price,
                                "ch_1h": ch1h, "ch_24h": ch24, "ch_7d": ch7d})
            elif ch1h < -1 and ch24 < -3 and ch7d < -5:
                conf = min(0.95, abs(ch1h + ch24 + ch7d) / 100)
                price = c.get("current_price", 0)
                LEDGER.add_signal(sym, "sell", conf, price)
                signals.append({"symbol": sym, "action": "sell",
                                "confidence": round(conf, 2), "price": price,
                                "ch_1h": ch1h, "ch_24h": ch24, "ch_7d": ch7d})
        signals.sort(key=lambda x: -x["confidence"])
        return {"signals": signals[:10], "win_rate_30d": round(LEDGER.win_rate(), 1),
                "version": VERSION}

