    # --- Novos endpoints v12 (já incluídos) ---
    @staticmethod
    @staticmethod
    def _serper_search(q: str, num: int = 8):
        """v44.4.0 — Google real via Serper (~$0.001/consulta; vendido a $0.008
        = margem de ~87%). É o movimento StableEnrich: o que se vende no x402
        é dado NÃO-gratuito fatiado por chamada. Sem SERPER_API_KEY, devolve
        None e o caller cai no DuckDuckGo — o produto nunca quebra."""
        if not SERPER_KEY:
            return None
        try:
            r = requests.post("https://google.serper.dev/search",
                              json={"q": q, "num": num},
                              headers={"X-API-KEY": SERPER_KEY,
                                       "Content-Type": "application/json"},
                              timeout=8)
            if r.ok:
                d = r.json()
                out = []
                ab = d.get("answerBox") or {}
                if ab.get("answer") or ab.get("snippet"):
                    out.append({"title": ab.get("title") or "answer",
                                "url": ab.get("link"),
                                "snippet": ab.get("answer") or ab.get("snippet")})
                out += [{"title": o.get("title"), "url": o.get("link"),
                         "snippet": o.get("snippet")}
                        for o in (d.get("organic") or [])[:num] if o.get("link")]
                return out or None
            log.warning(f"serper HTTP {r.status_code}")
        except Exception as e:
            log.warning(f"serper: {e}")
        return None

    @staticmethod
    def web_search():
        """v44.4.0: Google real (pago) quando SERPER_API_KEY está configurada —
        busca é a categoria nº1 de demanda comprovada do x402 e o nosso sinal
        orgânico mais forte (radar: q=btc de 15 IPs). Sem chave: DuckDuckGo,
        com a fonte declarada — nunca disfarçado."""
        q = request.args.get("q", "crypto market today")
        ts = int(time.time())
        sr = Brain._serper_search(q)
        if sr:
            return {"query": q, "results": sr, "source": "google",
                    "ts": ts, "provider": "Losbeto", "version": VERSION}
        try:
            r = requests.get("https://api.duckduckgo.com/",
                params={"q": q, "format": "json", "no_html": 1, "skip_disambig": 1},
                timeout=6)
            data = r.json()
            results = [{"title": t.get("Text"), "url": t.get("FirstURL")}
                       for t in data.get("RelatedTopics", [])[:5] if t.get("Text")]
            return {"query": q, "results": results, "source": "duckduckgo",
                    "ts": ts, "provider": "Losbeto", "version": VERSION}
        except Exception as e:
            return {"query": q, "results": [], "error": str(e), "ts": ts,
                    "provider": "Losbeto", "version": VERSION}

    @staticmethod
    def research_brief():
        """v44 — RESEARCH BRIEF (a demanda orgânica nº1, produtizada).

        Telemetria: /web-search cru é o endpoint com mais compradores distintos
        (15 IPs em 24h) — agentes conversacionais (Poncho, GPTs) pagando por
        pesquisa. Mas dado cru de busca é commodity; o produto é a SÍNTESE:
        fontes vivas reunidas + leitura de IA com pontos-chave e citações.
        Se nenhum LLM estiver disponível, devolve as fontes estruturadas —
        nunca quebra, nunca inventa síntese.
        """
        q = (request.args.get("q") or request.args.get("query") or "").strip()
        ts = int(time.time())
        if not q:
            # v44.0.9: default = a pergunta mais pedida do radar (btc, 15 IPs
            # distintos) — demonstra o produto em vez de erro cru pago.
            q = "bitcoin market today"

        sources, raw_bits = [], []
        # Fonte 1: DuckDuckGo Instant Answer + tópicos relacionados
        try:
            r = requests.get("https://api.duckduckgo.com/",
                params={"q": q, "format": "json", "no_html": 1, "skip_disambig": 1},
                timeout=7)
            d = r.json()
            if d.get("AbstractText"):
                raw_bits.append(d["AbstractText"])
                sources.append({"title": d.get("Heading") or q,
                                "url": d.get("AbstractURL"), "kind": "reference"})
            for t in d.get("RelatedTopics", [])[:6]:
                if isinstance(t, dict) and t.get("Text"):
                    raw_bits.append(t["Text"])
                    sources.append({"title": t["Text"][:90], "url": t.get("FirstURL"),
                                    "kind": "related"})
        except Exception as e:
            log.warning(f"research-brief ddg: {e}")
        # v44.4.0 — Fonte 1.5: Google real via Serper enriquece a síntese
        # (quando a chave existe). Snippets viram matéria-prima do brief.
        for s in (Brain._serper_search(q, num=5) or []):
            if s.get("snippet"):
                raw_bits.append(s["snippet"])
                sources.append({"title": (s.get("title") or "")[:90],
                                "url": s.get("url"), "kind": "web"})
        # Fonte 2: newswire de mercado quando a pergunta é de mercado/cripto
        _mk = any(k in q.lower() for k in ("bitcoin", "btc", "crypto", "market",
                  "ethereum", "solana", "stock", "token", "defi", "price"))
        if _mk:
            try:
                r = requests.get("https://min-api.cryptocompare.com/data/v2/news/"
                                 "?lang=EN&sortOrder=latest", timeout=6)
                for n in (r.json().get("Data") or [])[:4]:
                    raw_bits.append(f"{n.get('title')} ({n.get('source')})")
                    sources.append({"title": n.get("title"), "url": n.get("url"),
                                    "kind": "news",
                                    "ts": n.get("published_on")})
            except Exception as e:
                log.debug(f"research-brief news: {e}")

        if not raw_bits:
            return {"query": q, "status": "no_sources",
                    "note": ("Live source gathering returned nothing usable for "
                             "this query right now — nothing was synthesized."),
                    "sources": [], "ts": ts, "provider": "Losbeto/ResearchBrief"}

        out = {"query": q, "sources": sources[:10], "source_count": len(sources[:10]),
               "methodology": ("Live sources are gathered first; the synthesis "
                               "is written strictly over what was gathered, with "
                               "the source list attached. No source, no claims."),
               "ts": ts, "provider": "Losbeto/ResearchBrief"}
        try:
            brief = _ai(
                "You are a research analyst for an autonomous agent. Answer the "
                "question below using ONLY the gathered source snippets. "
                "Structure: (1) a 3-4 sentence brief, (2) 3-5 bullet key "
                "points. If the snippets are insufficient, say what is known "
                "and what is not. Question: " + q +
                "\n\nSnippets:\n" + "\n".join(f"- {b[:400]}" for b in raw_bits[:10]),
                max_tokens=600)
            if brief:
                out["brief"] = brief
        except Exception as e:
            log.debug(f"research-brief ai: {e}")
        if "brief" not in out:
            # Degradação honesta: fontes organizadas valem o preço; síntese
            # inventada, não.
            out["status"] = "sources_only"
            out["note"] = ("AI synthesis unavailable — returning the gathered "
                           "sources verbatim, organized. Nothing was invented.")
            out["gathered"] = raw_bits[:10]
        return out


    @staticmethod
    def ai_news():
        """v48.17.9-AINEWS: o tier anonimo da CryptoCompare MORREU (401 com
        Data em dict — o [:8] explodia em "unhashable type: 'slice'" e o
        comprador tomava 502 charged:true sem produto; flagrado no passe
        Algorand de 05/out). Agora: (1) guard de tipo + r.ok; (2) fallback
        RSS gratuito sem chave (CoinTelegraph, CoinDesk). Pior caso: lista
        vazia honesta com status no_sources — nunca mais erro cru pago."""
        news = []
        try:
            r = requests.get("https://min-api.cryptocompare.com/data/v2/news/?lang=EN&sortOrder=latest", timeout=6)
            data = r.json().get("Data", []) if r.ok else []
            if isinstance(data, dict):        # erro da upstream vira dict
                data = []
            news = [{"title": n.get("title"), "source": n.get("source"),
                     "url": n.get("url"), "ts": n.get("published_on")}
                    for n in data[:8] if isinstance(n, dict) and n.get("title")]
        except Exception as e:
            log.debug(f"ai-news cryptocompare: {e}")
        if not news:
            import xml.etree.ElementTree as _ET
            for _feed in ("https://cointelegraph.com/rss",
                          "https://www.coindesk.com/arc/outboundfeeds/rss/"):
                try:
                    _r = requests.get(_feed, timeout=6,
                                      headers={"User-Agent": "Mozilla/5.0"})
                    _root = _ET.fromstring(_r.text)
                    for _it in _root.iter("item"):
                        _t, _u = _it.findtext("title"), _it.findtext("link")
                        if _t:
                            news.append({"title": _t.strip(),
                                         "source": _feed.split("/")[2],
                                         "url": (_u or "").strip(), "ts": None})
                        if len(news) >= 8:
                            break
                except Exception as e:
                    log.debug(f"ai-news rss {_feed}: {e}")
                if news:
                    break
        out = {"count": len(news), "news": news[:8], "ts": int(time.time()),
               "provider": "Losbeto"}
        if not news:
            out["status"] = "no_sources"
            out["note"] = ("Live news sources unavailable right now — "
                           "returned empty rather than inventing headlines.")
        return out

