    @staticmethod
    def sanctions():
        """v23: screening REAL contra a lista OFAC-SDN oficial (publicação
        pública do U.S. Treasury), com cache em disco de 24h. A v22 respondia
        sempre 'clean' sem checar nada — falso positivo de compliance vendido
        como serviço. Match exato para endereços; match por tokens para nomes."""
        address = request.args.get("address", "").strip()
        name    = request.args.get("name", "").strip()
        ts = int(time.time())
        if not address and not name:
            # v44.0.9 (padrão v21.11): default = a carteira do pagador,
            # com fallback para o exemplo estável do nó. Nunca erro cru pago.
            from flask import g as _g
            _payer = str(getattr(_g, "losbeto_payer", "") or "").strip()
            address = _payer if _payer else RECEIVE_ADDRESS
        query = address or name
        text = _ofac_sdn_text()
        matches = []
        if text:
            if address:
                addr_low = address.lower()
                is_evm = addr_low.startswith("0x")
                for line in text.splitlines():
                    if (address.lower() in line.lower()) if is_evm else (address in line):
                        matches.append(line[:300])
                        if len(matches) >= 5:
                            break
            else:
                toks = [t for t in query.upper().split() if len(t) > 2]
                if toks:
                    for line in text.splitlines():
                        lu = line.upper()
                        if all(t in lu for t in toks):
                            matches.append(line[:300])
                            if len(matches) >= 5:
                                break
        status = ("listed" if matches
                  else ("clean" if text else "check-unavailable"))
        return {
            "query": query, "type": "wallet" if address else "entity",
            "lists_checked": ["OFAC-SDN (download oficial sanção U.S. Treasury)"],
            "status": status,
            "match_count": len(matches),
            "matches": matches,
            "list_cached_at": (datetime.utcfromtimestamp(_OFAC_CACHE["ts"]).isoformat() + "Z"
                               if _OFAC_CACHE["ts"] else None),
            "disclaimer": ("Screening informativo contra a lista pública OFAC-SDN. "
                           "Não substitui compliance formal — consulte jurídico."),
            "ts": ts, "provider": "Losbeto/Sanctions", "version": VERSION,
        }

