    @staticmethod
    def forex_arbitrage():
        ts = int(time.time())
        try:
            r = requests.get("https://api.exchangerate-api.com/v4/latest/USD", timeout=8)
            if r.ok:
                rates = r.json().get("rates", {})
                opps = []
                pairs = [("EUR", "GBP", "JPY"), ("USD", "JPY", "EUR"), ("GBP", "USD", "EUR")]
                for a, b, c in pairs:
                    if a in rates and b in rates and c in rates:
                        direct = rates.get(b, 0) / rates.get(a, 1)
                        triangular = (1 / rates.get(a, 1)) * rates.get(c, 0) * (1 / rates.get(c, 1)) * rates.get(b, 0)
                        if direct and triangular:
                            spread = abs(direct - triangular) / direct * 100
                            if spread > 0.01:
                                opps.append({"route": f"{a}->{b}", "direct": round(direct, 6),
                                            "triangular": round(triangular, 6), "spread_pct": round(spread, 4)})
                return {"opportunities": opps[:5], "ts": ts, "provider": "Losbeto/ForexArb",
                        "version": VERSION, "methodology": "Triangular arbitrage via cross-rates"}
        except Exception as e:
            log.warning(f"forex_arbitrage: {e}")
        return {"opportunities": [], "ts": ts, "provider": "Losbeto/ForexArb",
                "version": VERSION, "status": "degraded"}

