# 13. SERVIDOR x402 v2 — SPEC COMPLIANT (com correção de headers)
# ============================================================================

app = Flask(__name__)
# v21: habilita logs Flask para diagnóstico de deploy Railway
if os.environ.get("OMEGA_QUIET", "").lower() == "true":
    app.logger.disabled = True

@app.after_request
def _cors(resp):
    resp.headers["Access-Control-Allow-Origin"]   = "*"
    resp.headers["Access-Control-Allow-Headers"]  = (
        "X-PAYMENT,X-Payment,PAYMENT-SIGNATURE,Payment-Signature,"
        # v48.9.10: X-API-Key/X-Welcome-Token — sem eles, um agente EM BROWSER
        # compra a key e o preflight bloqueia o uso (CORS).
        "Authorization,Content-Type,X-Session-Token,X-API-Key,X-Welcome-Token"
    )
    resp.headers["Access-Control-Allow-Methods"]  = "GET,POST,OPTIONS,HEAD"
    # v48.3.7 FIX: este hook global SOBRESCREVIA o Access-Control-Expose-Headers
    # que cada caminho montou — o 402 perdia X-Plans/X-Cheapest-Plan, o pago
    # perdia X-Next-Step/X-Savings-Tip, os créditos perdiam X-Plan-Expires-In/
    # X-Plan-Renew/X-Credit-Low para qualquer agente em browser. Agora: UNIÃO
    # da base global com o que a rota expôs (ordem preservada, sem duplicata).
    _base_expose = ["WWW-Authenticate", "X-PAYMENT-REQUIRED", "PAYMENT-REQUIRED",
                    "X-Session-Token", "X-Session-TTL", "X-402-Version"]
    _existing = [h.strip() for h in
                 (resp.headers.get("Access-Control-Expose-Headers") or "").split(",")
                 if h.strip()]
    resp.headers["Access-Control-Expose-Headers"] = ",".join(
        dict.fromkeys(_base_expose + _existing))
    return resp

@app.before_request
def _preflight():
    if request.method == "OPTIONS":
        from flask import Response as _R
        r = _R()
        r.headers["Access-Control-Allow-Origin"]  = "*"
        r.headers["Access-Control-Allow-Headers"] = (
            "X-PAYMENT,X-Payment,PAYMENT-SIGNATURE,Payment-Signature,"
            "Authorization,Content-Type,X-Session-Token"
        )
        r.headers["Access-Control-Allow-Methods"] = "GET,POST,OPTIONS,HEAD"
        r.headers["Access-Control-Max-Age"]       = "86400"
        r.headers["Access-Control-Expose-Headers"] = (
            "WWW-Authenticate,X-PAYMENT-REQUIRED,PAYMENT-REQUIRED,"
            "X-Session-Token,X-Session-TTL,X-402-Version"
        )
        return r, 204

_rl_lock   = threading.Lock()
_rl_ip     = defaultdict(deque)
_rl_wallet = defaultdict(deque)
RL_RPM_IP     = int(os.environ.get("OMEGA_RL_RPM", "60"))
RL_RPM_WALLET = int(os.environ.get("OMEGA_RL_RPM_WALLET", "120"))

def _rl_check(ip: str, wallet: str = "") -> bool:
    now = time.time()
    with _rl_lock:
        dq = _rl_ip[ip]
        while dq and dq[0] < now - 60: dq.popleft()
        if len(dq) >= RL_RPM_IP: return False
        dq.append(now)
        if wallet:
            dqw = _rl_wallet[wallet]
            while dqw and dqw[0] < now - 60: dqw.popleft()
            if len(dqw) >= RL_RPM_WALLET: return False
            dqw.append(now)
    return True

def _public_base() -> str:
    return PUBLIC_URL or f"http://localhost:{X402_PORT}"

_INLINE_SAMPLE_MAX = int(os.environ.get("INLINE_SAMPLE_MAX_CHARS", "900"))

def _inline_sample(endpoint: str) -> dict:
    """v24.6: amostra compacta do dado real, embutida no corpo do 402.
    Vem do cache de preview (populado pelo warmer, sem custo). Truncada para
    não canibalizar a venda: mostra a FORMA e a veracidade, não o conteúdo todo."""
    try:
        cached = _PREVIEW_CACHE.get(endpoint) or _preview_db_get(endpoint)
        if not cached:
            return {"status": "warming", "hint": f"GET {endpoint}?preview=1 for a free sample"}
        data = cached.get("data")
        blob = json.dumps(data, default=str, ensure_ascii=False)
        truncated = len(blob) > _INLINE_SAMPLE_MAX
        if truncated and isinstance(data, dict):
            small, used = {}, 0
            for k, v in data.items():
                piece = json.dumps({k: v}, default=str, ensure_ascii=False)
                if used + len(piece) > _INLINE_SAMPLE_MAX:
                    continue
                small[k] = v
                used += len(piece)
            data = small or {"preview": blob[:_INLINE_SAMPLE_MAX]}
        return {"data": data,
                "age_seconds": int(time.time() - cached.get("ts", time.time())),
                "truncated": truncated,
                "note": "Real delayed output. Pay for the full, real-time version."}
    except Exception as e:
        log.debug(f"inline_sample {endpoint}: {e}")
        return {"status": "unavailable"}

def _cheapest_paid(base: str) -> dict:
    """v24.5: antes o 402 anunciava '/pyth-price a $0.005' fixo no código — com
    o preço dinâmico o valor real varia (hoje $0.0024) e o agente recebia uma
    cotação incorreta. Agora calcula de verdade, na hora."""
    try:
        cand = min(((ep, get_dynamic_price(ep)) for ep in BASE_PRICES
                    if not ep.startswith(("/subscribe", "/day-pass", "/week-pass",
                                          "/enterprise", "/buy-credits", "/starter"))),
                   key=lambda kv: kv[1])
        return {"endpoint": f"{base}{cand[0]}", "usd": f"{cand[1]:.4f}"}
    except Exception:
        return {"endpoint": f"{base}/pyth-price", "usd": "0.0030"}

# ---------------------------------------------------------------------------
# v44 — RECOMENDAÇÃO POR PAGADOR (personalização do lado da máquina).
#
# O comprador robô repete comportamento: quem comprou /br-curve tende a
# querer /br-macro; quem comprou /token-intel tem uma carteira para perfilar.
# Cada resposta paga agora carrega `recommended_next`: os próximos 2 produtos
# MAIS PROVÁVEIS para ESTE pagador — histórico dele no ledger + afinidade de
# tags + o que o mercado mais compra. Custo: um SELECT indexado por pagador.
# É o cross-sell que um vendedor humano faria, embutido no JSON.
# ---------------------------------------------------------------------------

def _payer_bought(payer: str, limit: int = 60) -> set:
    if not payer:
        return set()
    try:
        with LEDGER._conn() as c:
            rows = c.execute("SELECT DISTINCT endpoint FROM revenue "
                             "WHERE payer=? ORDER BY ts DESC LIMIT ?",
                             (payer, limit)).fetchall()
        return {r[0] for r in rows}
    except Exception:
        return set()

def _market_top(days: int = 7, limit: int = 5) -> list:
    try:
        with LEDGER._conn() as c:
            rows = c.execute(
                "SELECT endpoint, COUNT(*) n FROM revenue "
                "WHERE ts > ? AND endpoint NOT LIKE '/subscribe%' "
                "AND endpoint NOT IN ('/day-pass','/week-pass','/buy-credits',"
                "'/starter-pack','/enterprise') "
                "GROUP BY endpoint ORDER BY n DESC LIMIT ?",
                (int(time.time()) - days * 86400, limit)).fetchall()
        return [r[0] for r in rows]
    except Exception:
        return []

def _recommended_next(current: str, payer: str, limit: int = 2) -> list:
    """Próximos produtos para ESTE pagador. Ordem: afinidade de tag com o que
    ele acabou de comprar (excluindo o que já tem), depois os mais comprados
    do mercado. Preço vivo sempre junto — decisão numa resposta só."""
    bought = _payer_bought(payer)
    bought.add(current)
    skip = {"/subscribe-pro", "/subscribe-whale", "/day-pass", "/week-pass",
            "/buy-credits", "/buy-credits-5", "/buy-credits-25",
            "/starter-pack", "/enterprise"}
    cur_tags = set(ENDPOINT_TAGS.get(current, []))
    scored = []
    for ep in BASE_PRICES:
        if ep in bought or ep in skip:
            continue
        shared = len(cur_tags & set(ENDPOINT_TAGS.get(ep, [])))
        scored.append((shared, -get_dynamic_price(ep), ep))
    scored.sort(key=lambda t: (-t[0], t[1]))
    recs = []
    for shared, _negp, ep in scored:
        if shared > 0:
            recs.append({"endpoint": ep,
                         "price_usdc": f"{get_dynamic_price(ep):.4f}",
                         "why": f"same category as {current}"})
        if len(recs) >= limit:
            break
    if len(recs) < limit:  # completa com os campeões de venda do mercado
        for ep in _market_top():
            if ep in bought or ep in skip or any(r["endpoint"] == ep for r in recs):
                continue
            recs.append({"endpoint": ep,
                         "price_usdc": f"{get_dynamic_price(ep):.4f}",
                         "why": "most bought on this node this week"})
            if len(recs) >= limit:
                break
    return recs[:limit]

_B58 = set("123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz")

_AVM32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"

def _valid_txid(v: str) -> bool:
    """Assinatura Solana = base58 (43-90 chars). TX EVM = 0x + 64 hex.
    TXID Algorand = base32 A-Z2-7 de 52 chars (v44.9.4: contém O e I, que o
    base58 exclui — era a causa dos recibos Algorand gravados sem link).
    Blob base64 de transação (contém +, /, = ou é gigante) NÃO é assinatura."""
    if not v or not isinstance(v, str):
        return False
    v = v.strip()
    if v.startswith("0x"):
        return len(v) == 66 and all(c in "0123456789abcdefABCDEF" for c in v[2:])
    if len(v) == 52 and all(c in _AVM32 for c in v):
        return True
    return 43 <= len(v) <= 90 and all(c in _B58 for c in v)

def _explorer_url(chain: str, sig: str) -> str:
    """Link de explorer correto por chain — v44.8.2: Algorand ia parar no
    solscan (link morto). allo.info e o explorer padrao do ecossistema AVM."""
    if chain == "algorand":
        return f"https://allo.info/tx/{sig}"
    if chain == "base":
        return f"https://basescan.org/tx/{sig}"
    return f"https://solscan.io/tx/{sig}"

def _clean_tx(sdata: dict, fallback: str = "") -> str:
    """v24.7 FIX: o campo 'transaction' de alguns facilitators traz o BLOB
    base64 da transação, não a assinatura. Isso gravava recibos com hash
    inválido (ex.: 'AgAAAAAAAA...'), cujo link no explorer não abre — dano
    direto à página de transparência, que é o nosso diferencial. Agora
    priorizamos os campos de assinatura e validamos o formato."""
    for key in ("signature", "txSignature", "transactionHash", "txHash",
                "tx", "hash", "transaction"):
        v = sdata.get(key)
        if isinstance(v, str) and _valid_txid(v):
            return v.strip()
        # v44.9.4: settle da PayAI voltou a trazer o BLOB base64 da transação
        # Solana inteira em 'transaction' (campos vistos no log: success,
        # transaction, network, payer). A assinatura são os primeiros 64
        # bytes do blob — recuperamos em vez de gravar recibo sem link.
        if isinstance(v, str) and (len(v) > 90 or any(c in v for c in "+/=")):
            try:
                import base64 as _b64
                raw = _b64.b64decode(v + "=" * (-len(v) % 4))
                if len(raw) >= 64:
                    sig = base58.b58encode(raw[:64]).decode()
                    if _valid_txid(sig):
                        return sig
            except Exception:
                pass
    if _valid_txid(fallback):
        return fallback.strip()
    # v44.9.4: preview do valor ofensor no log — a próxima ocorrência diz
    # exatamente o que o facilitator mandou, sem adivinhação.
    _prev = str(sdata.get("transaction", ""))[:40]
    log.warning(f"⚠️ settle sem assinatura válida (campos: {list(sdata)[:6]}, "
                f"transaction='{_prev}...') — recibo será registrado sem link de explorer")
    return ""

