# v44.4.0: nome de serviço alinhado ao fosso (<=32 chars, ASCII — regra Bazaar)
SERVICE_NAME = os.environ.get("SERVICE_NAME", "Losbeto Market Intelligence")[:32]

def _service_tags(endpoint: str) -> list:
    """v25: até 5 tags, cada uma <=32 chars ASCII imprimível (regra da spec).
    Derivadas das categorias reais + termos que um agente buscaria."""
    base_tags = [t.lower() for t in ENDPOINT_TAGS.get(endpoint, [])][:3]
    extra = []
    if endpoint in ("/forex-rate", "/forex-arbitrage"):
        extra = ["forex", "fx-rates"]
    elif endpoint in ("/stock-quote", "/equity-dossier", "/sector-rotation",
                      "/earnings-whisper"):
        extra = ["stocks", "equities"]
    elif endpoint in ("/commodity-price",):
        extra = ["commodities", "gold-oil"]
    elif endpoint in ("/macro-calendar", "/event-playbook", "/global-macro",
                      "/correlation-matrix"):
        extra = ["macro", "cross-asset"]
    else:
        extra = ["crypto", "market-data"]
    out, seen = [], set()
    for t in base_tags + extra:
        t = "".join(c for c in str(t) if 32 <= ord(c) <= 126)[:32]
        if t and t not in seen:
            seen.add(t)
            out.append(t)
    return out[:5]

def _bazaar_blob(endpoint: str) -> dict:
    """v25: formato EXATO da spec oficial do Bazaar (docs/extensions/bazaar.mdx).
    Três correções que os Seller Tools da agentic.market apontaram como faltantes:
      1. info.input.queryParams  -> valores CONCRETOS (era só method/type)
      2. info.output.example     -> amostra REAL do cache (era warning 'missing')
      3. inputSchema             -> era 'Input schema present: no'
    O schema legado (schema.properties.*) fica preservado para o validador
    @agentcash/discovery, que usa outro shape."""
    desc = _cap500(ENDPOINT_DESC.get(endpoint, endpoint))
    params = dict(ENDPOINT_PARAM_HINTS.get(endpoint, {"format": "json"}))


    # exemplo de saída: dado real que o warmer já mantém quente (custo zero)
    example_out = {}
    try:
        cached = _PREVIEW_CACHE.get(endpoint) or _preview_db_get(endpoint)
        if cached:
            data = cached.get("data")
            if isinstance(data, dict):
                blob = json.dumps(data, default=str)
                if len(blob) <= 1200:
                    example_out = data
                else:  # recorta mantendo a forma
                    example_out, used = {}, 0
                    for k, v in data.items():
                        piece = json.dumps({k: v}, default=str)
                        if used + len(piece) > 1200:
                            continue
                        example_out[k] = v
                        used += len(piece)
    except Exception as e:
        log.debug(f"bazaar example {endpoint}: {e}")

    # v44.9.1: endpoints POST com corpo JSON (ex.: /v1/chat/completions) — o
    # blob padrão descreveria um GET com queryParams, e o x402scan avisava
    # "Paid endpoint is missing an input schema". Aqui o método e o schema
    # do corpo são declarados de verdade.
    _bs = ENDPOINT_BODY_SCHEMAS.get(endpoint) if "ENDPOINT_BODY_SCHEMAS" in globals() else None
    if _bs:
        return {
            "info": {
                "input": {"type": "http", "method": _bs["method"],
                          "contentType": _bs["contentType"],
                          "bodyParams": _bs["example"]},
                "output": ({"type": "json", "example": example_out} if example_out
                           else {"type": "json"}),
            },
            "inputSchema": _bs["schema"],
            "schema": {
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "type": "object",
                "properties": {
                    "input": {"type": "object", "properties": {
                        "method": {"type": "string", "description": _bs["method"]},
                        "bodyParams": _bs["schema"]}},
                    "output": {"type": "object", "properties": {
                        "example": {"type": "object", "description": desc}}},
                },
                "required": ["input"]},
            "description": desc,
            "title": endpoint.strip("/").replace("-", " ").title() + " — Losbeto",
            "tags": _service_tags(endpoint),
            "provider": {"name": SERVICE_NAME, "url": _public_base()},
        }
    props = {k: {"type": "string", "description": _PARAM_DESC.get(k, f"{k} parameter")}
             for k in params}
    # v48.9.19-CATALOG: parâmetros FUNCIONAIS (tudo menos "format") são
    # OBRIGATÓRIOS no schema. Docs CDP Bazaar (24/set/2026): "sem schemas
    # explícitos, agentes descobrem o endpoint mas não conseguem montar uma
    # chamada válida" — e o requisito de curadoria "agent-ready metadata"
    # pede input schema completo. Com required=[], um agente chamava
    # /research-brief sem ?q= e recebia 400 — chamada inválida construída a
    # partir do NOSSO schema. O agente que segue o schema agora sempre monta
    # uma chamada válida (pior caso: envia o exemplo — aceito e cobrado).
    _req_params = sorted(k for k in params if k != "format")
    return {
        "info": {
            "input": {"type": "http", "method": "GET", "queryParams": params},
            "output": ({"type": "json", "example": example_out} if example_out
                       else {"type": "json"}),
        },
        "inputSchema": {"type": "object", "properties": props,
                        "required": _req_params},
        # Shape legado exigido pelo validador @agentcash/discovery (extractSchemas2)
        "schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "type": "object",
            "properties": {
                "input": {"type": "object", "properties": {
                    "queryParams": {"type": "object", "properties": props,
                                    "required": _req_params}}},
                "output": {"type": "object", "properties": {
                    "example": {"type": "object", "description": desc}}},
            },
            "required": ["input"]},
        "description": desc,
        # v47.3.1: spec x402 v2 aceita title/tags/provider no bloco bazaar e
        # buscas por tag só casam com quem declara (docs Kobaru/Bazaar). É
        # aditivo — validadores antigos ignoram o que não conhecem.
        "title": endpoint.strip("/").replace("-", " ").title() + " — Losbeto",
        "tags": _service_tags(endpoint),
        "provider": {"name": SERVICE_NAME, "url": _public_base()},
    }

# ---------------------------------------------------------------------------
# v39 — CACHE DE DESAFIO (corrige uma venda perdida silenciosa)
#
# A v38 reconstruía o desafio no momento da liquidação:
#     accepts = _build_402(endpoint).get_json()["accepts"]
#     amount  = get_dynamic_price(endpoint)
# Como get_dynamic_price() aplica o multiplicador PoI, que muda a cada venda
# registrada, o preço podia MUDAR entre o 402 emitido e o pagamento chegar.
# O cliente assinou uma autorização para o valor antigo; o facilitator recebia
# requirements com o valor novo; verify() falhava e a venda se perdia sem
# nenhum log que apontasse a causa.
#
# Agora o desafio emitido é guardado por endpoint com TTL igual ao
# maxTimeoutSeconds do próprio desafio (300s). Na liquidação usamos o desafio
# EMITIDO, não um recalculado.
# ---------------------------------------------------------------------------
_CHALLENGE_CACHE: Dict[str, tuple] = {}
_CHALLENGE_LOCK = threading.Lock()
CHALLENGE_TTL = int(os.environ.get("CHALLENGE_TTL", "300"))


def _challenge_remember(endpoint: str, accepts: list) -> None:
    if not accepts:
        return
    with _CHALLENGE_LOCK:
        _CHALLENGE_CACHE[endpoint] = (time.time(), accepts)
        if len(_CHALLENGE_CACHE) > 300:
            for k in sorted(_CHALLENGE_CACHE,
                            key=lambda x: _CHALLENGE_CACHE[x][0])[:100]:
                _CHALLENGE_CACHE.pop(k, None)


def _challenge_recall(endpoint: str) -> Optional[list]:
    """Devolve os accepts realmente emitidos, se ainda dentro da janela."""
    with _CHALLENGE_LOCK:
        hit = _CHALLENGE_CACHE.get(endpoint)
    if hit and (time.time() - hit[0]) <= CHALLENGE_TTL:
        return hit[1]
    return None


# ---------------------------------------------------------------------------
# v39.7 — A OFERTA DE ASSINATURA VAI PARA DENTRO DO 402
#
# /pricing existe desde a v39.1 e nunca vendeu nada, por um motivo simples:
# nenhum agente visita uma página. O momento em que a decisão de compra
# acontece é EXATAMENTE quando o cliente recebe o 402 — ele está com a
# carteira na mão, avaliando se aquele preço vale. É ali que a alternativa
# precisa estar, não numa landing.
#
# Então todo desafio 402 passa a carregar um bloco "alternatives" dizendo, com
# número: quantas chamadas deste mesmo endpoint pagam um passe, e onde comprar.
# Um agente que planeja orçamento consegue decidir sem nenhuma chamada extra.
# ---------------------------------------------------------------------------

# v39.7 — GATILHO DE UPGRADE COM DADO REAL
# Dizer "assine" para quem fez uma chamada é spam. Dizer, para quem já gastou
# mais do que um passe custaria, exatamente quanto teria economizado, é
# informação — e é o argumento mais forte que existe, porque é o dinheiro dele.
_PAYER_SPEND: Dict[str, list] = {}
_PAYER_LOCK = threading.Lock()
UPSELL_WINDOW = int(os.environ.get("UPSELL_WINDOW", "604800"))  # v48.3: 7 dias


def _track_spend(payer: str, amount: float) -> None:
    if not payer or amount <= 0:
        return
    agora = time.time()
    with _PAYER_LOCK:
        hist = [x for x in _PAYER_SPEND.get(payer, []) if agora - x[0] < UPSELL_WINDOW]
        hist.append((agora, amount))
        _PAYER_SPEND[payer] = hist
        if len(_PAYER_SPEND) > 500:
            for k in list(_PAYER_SPEND)[:150]:
                _PAYER_SPEND.pop(k, None)


def _payer_spend_window(payer: str, window_s: int):
    """v48.3-PLANS: gasto real do payer lido do LEDGER (SQLite no volume /data,
    compartilhado entre os 4 workers do gunicorn). A versão original deste
    motor (v39.7) usava um dict em memória — cada worker via ~1/4 das chamadas
    do cliente e um redeploy zerava tudo. Cache de 120s por payer."""
    try:
        ck = f"psw:{payer[:48]}:{window_s}"
        cached = LEDGER.cache_get(ck, 120)
        if cached:
            return int(cached["calls"]), float(cached["spent"])
        since = int(time.time()) - window_s
        with LEDGER.lock, LEDGER._conn() as c:
            row = c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM revenue "
                            "WHERE payer=? AND ts>?", (payer, since)).fetchone()
        out = (int(row[0]), float(row[1]))
        LEDGER.cache_set(ck, {"calls": out[0], "spent": out[1]})
        return out
    except Exception:
        return 0, 0.0


def _upsell_note(payer: str) -> Optional[dict]:
    """Só fala quando o número já favorece o cliente. Silêncio caso contrário.
    v48.3: lê o ledger (não a memória do worker), janela de 7 dias, mínimo de
    2 chamadas, e nunca recomenda para as wallets do operador."""
    if not payer:
        return None
    try:
        if (payer or "").lower() in OPERATOR_WALLETS:
            return None
    except Exception:
        pass
    calls, gasto = _payer_spend_window(payer, UPSELL_WINDOW)
    if calls < 2:
        return None
    hist = [(0, gasto)] * 1  # compat: abaixo só len(hist)/soma importam
    agora = time.time()
    # v39.7 — CORRIGIDO na verificação: a primeira versão recomendava o plano
    # mais barato que o cliente já tinha ultrapassado, e isso dava conselho
    # ERRADO. Quem gastou $3.15 ouvia "compre credits por $0.99" — mas credits
    # dá $1.25 de saldo e não teria coberto nem metade. Um upsell que não se
    # sustenta na conta do cliente é pior que nenhum upsell.
    #
    # Agora: o plano mais barato que REALMENTE teria coberto o gasto. Plano de
    # saldo cobre até balance_usd; plano ilimitado cobre qualquer valor.
    candidatos = sorted(
        ((BASE_PRICES[ep], ep, cfg) for ep, cfg in CREDIT_PLANS.items()
         if ep in BASE_PRICES), key=lambda x: x[0])
    for preco, ep, cfg in candidatos:
        cobertura = float("inf") if cfg["balance_usd"] == -1 else cfg["balance_usd"]
        if gasto > preco and cobertura >= gasto:
            economia = gasto - preco
            return {
                "you_spent_usdc": round(gasto, 4),
                "calls_in_window": calls,
                "window_days": UPSELL_WINDOW // 86400,
                "plan": cfg["plan"],
                "plan_price_usdc": round(preco, 2),
                "would_have_saved_usdc": round(economia, 4),
                "buy": f"{_public_base()}{ep}",
                "message": (f"You have spent ${gasto:.4f} across {calls} calls "
                            f"in the last {UPSELL_WINDOW // 86400} days. The "
                            f"{cfg['plan']} plan costs ${preco:.2f} and would "
                            f"have covered all of it with ${economia:.4f} left "
                            f"over — plus no settlement latency."),
            }
    return None


def _subscription_offer(endpoint: str, unit_price: float) -> Optional[dict]:
    """Alternativas mais baratas que pagar esta chamada avulsa, com o
    ponto de equilíbrio calculado no preço deste endpoint."""
    if unit_price <= 0 or endpoint in CREDIT_PLANS:
        return None
    base = _public_base()
    opcoes = []
    for ep, cfg in CREDIT_PLANS.items():
        preco = BASE_PRICES.get(ep)
        if not preco:
            continue
        ilimitado = cfg["balance_usd"] == -1
        equilibrio = int(preco / unit_price) + 1
        item = {
            "plan": cfg["plan"],
            "buy": f"{base}{ep}",
            "price_usdc": round(preco, 2),
            "duration_days": cfg["ttl_days"],
            "grants": ("unlimited calls to every endpoint" if ilimitado
                       else f"${cfg['balance_usd']:.2f} of call credit"),
            "breaks_even_after": equilibrio,
            "note": (f"Cheaper than paying per call from call #{equilibrio} "
                     f"onward, at this endpoint's price."),
        }
        if ilimitado:
            item["includes_mcp_live"] = True
        opcoes.append(item)
    opcoes.sort(key=lambda x: x["price_usdc"])
    # v48.3.6-CONVERT: marca a opção de break-even mais cedo NESTE endpoint.
    # Agente de orçamento não compara 8 planos — ele executa o recomendado.
    if opcoes:
        _best = min(opcoes, key=lambda x: x["breaks_even_after"])
        _best["recommended"] = True
        _best["recommended_reason"] = (
            f"Earliest break-even at this endpoint's price: from call "
            f"#{_best['breaks_even_after']} onward you stop paying per call.")
    return {
        "why": ("If your agent will call this more than a handful of times, "
                "one of these costs less and removes settlement latency "
                "entirely — the key is checked in about a millisecond instead "
                "of waiting for an on-chain confirmation."),
        "how_to_use": "Send the key you receive as the X-API-Key header.",
        "mcp": {"url": f"{base}/mcp",
                "header": "Authorization: Bearer <key>",
                "note": "A subscription turns the whole catalog into a live "
                        "MCP server for Claude Code, Cursor or any MCP client."},
        "plans": opcoes,
        "human_readable": f"{base}/pricing",
    }


def _build_402(endpoint: str, price_override: float = None):
    # v48.1: price_override serve UM desafio promocional (1ª compra reativa).
    amount_usdc = price_override if price_override else get_dynamic_price(endpoint)
    amount_atomic_sol = str(int(amount_usdc * 10 ** USDC_DECIMALS))
    amount_atomic_base = str(int(amount_usdc * 10 ** 6))
    base = _public_base()
    desc = _cap500(ENDPOINT_DESC.get(endpoint, f"Losbeto — {endpoint}"))
    # v48.17.10-FUNNEL: um requestId por desafio, injetado no extra de TODOS os
    # accepts. O cliente v2 copia o accept escolhido para accepted.extra do
    # PaymentPayload — o elo probe→pagamento que faltava para medir conversão.
    _rid = secrets.token_hex(6)

    # extra.feePayer é OBRIGATÓRIO no scheme "exact" da SVM (Solana) — sem isso,
    # clientes x402 corretos (AgentCash, x402-fetch, etc.) rejeitam a payment requirement
    # com "feePayer is required in paymentRequirements.extra for SVM transactions".
    # v20: cadeia de fallback robusta.
    svm_extra = {}
    fee_payer = os.environ.get("SVM_FEE_PAYER_OVERRIDE", "").strip()
    if not fee_payer and FACILITATOR:
        fee_payer = FACILITATOR.get_svm_fee_payer()
    # v20: Último recurso — usa o próprio signer do node como feePayer (o cliente
    # ainda vai fechar a tx com um feePayer real do facilitator no momento do settle,
    # mas o campo não pode faltar senão o AgentCash rejeita antes de tentar).
    if not fee_payer:
        fee_payer = WALLET.solana_address
    if fee_payer:
        svm_extra["feePayer"] = fee_payer
    svm_extra["requestId"] = _rid

    _sol_accept = {
        "scheme":            "exact",
        "network":           f"solana:{SOL_GENESIS}",
        "asset":             USDC_MINT,
        "amount":            amount_atomic_sol,
        "payTo":             RECEIVE_ADDRESS,
        "maxTimeoutSeconds": 300,
        "extra":             svm_extra,
    }
    accepts = []
    if PREFER_BASE and ENABLE_BASE and BASE_PAYTO_EVM:
        # v25.1: ordem dos accepts DECIDE a descoberta. Clientes x402 escolhem
        # tipicamente accepts[0]; com Solana em 1º, os settles iam para o PayAI
        # e NUNCA passavam pela CDP — e só a CDP cataloga no Bazaar (por isso
        # apenas 5 dos 67 endpoints estavam indexados). Base primeiro = cada
        # venda vira uma entrada de catálogo. Solana continua aceita em 2º.
        pass  # Base é inserida logo abaixo; Solana é anexada depois
    else:
        accepts.append(_sol_accept)
    if ENABLE_BASE and BASE_PAYTO_EVM:
        accepts.append({
            "scheme":            "exact",
            "network":           BASE_CAIP2,
            "asset":             BASE_USDC,
            "amount":            amount_atomic_base,
            "payTo":             BASE_PAYTO_EVM,
            "maxTimeoutSeconds": 300,
            # v21.10 FIX: USDC em Base usa EIP-3009 (transferWithAuthorization);
            # o cliente PRECISA do domínio EIP-712 (name/version do contrato)
            # para assinar. Sem isso, TODO pagamento via Base falha no cliente:
            # "EIP-712 domain parameters (name, version) are required".
            "extra":             {"name": "USD Coin", "version": "2",
                                  "requestId": _rid},
        })
    if PREFER_BASE and ENABLE_BASE and BASE_PAYTO_EVM:
        accepts.append(_sol_accept)      # Solana segue disponível, em 2ª opção
    if ENABLE_ALGO:
        # v44.7.0-ALGORAND: 3ª opção de pagamento — USDC na Algorand mainnet
        # (ASA 31566704, 6 casas decimais como Base/Solana) via GoPlausible.
        # Requisito oficial do Global x402 Challenge: campo 'tag' dentro do
        # extra. Posição 3 proposital: Base continua 1ª (indexação CDP/Bazaar)
        # e Solana 2ª — Algorand soma, não canibaliza as rails que já rankeiam.
        accepts.append({
            "scheme":            "exact",
            "network":           ALGO_CAIP2,
            "asset":             ALGO_USDC_ASA,
            "amount":            amount_atomic_base,
            "payTo":             ALGO_PAYTO,
            "maxTimeoutSeconds": 300,
            "extra":             {"feePayer": ALGO_FEEPAYER,
                                  "tag": "x402-global-challenge",
                                  "requestId": _rid},
        })
    # v48.11.0-GLOBAL: 4a e 5a rails — USDC nativo na Polygon e na Arbitrum,
    # EIP-3009 com o mesmo dominio do USDC de Base. amount reutiliza
    # amount_atomic_base (USDC 6 decimais nas tres EVM). _accept_to_v1 devolve
    # None para redes desconhecidas -> ficam v2-only no header, sem quebrar v1.
    if X402_POLYGON and BASE_PAYTO_EVM:
        accepts.append({
            "scheme":            "exact",
            "network":           "eip155:137",
            "asset":             "0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359",
            "amount":            amount_atomic_base,
            "payTo":             BASE_PAYTO_EVM,
            "maxTimeoutSeconds": 300,
            "extra":             {"name": "USD Coin", "version": "2",
                                  "requestId": _rid},
        })
    if X402_ARBITRUM and BASE_PAYTO_EVM:
        accepts.append({
            "scheme":            "exact",
            "network":           "eip155:42161",
            "asset":             "0xaf88d065e77c8cC2239327C5EDb3A432268e5831",
            "amount":            amount_atomic_base,
            "payTo":             BASE_PAYTO_EVM,
            "maxTimeoutSeconds": 300,
            "extra":             {"name": "USD Coin", "version": "2",
                                  "requestId": _rid},
        })
    # v48.9.12-DUAL — O FIX DE COMPATIBILIDADE DECISIVO.
    # Diagnóstico (23/09, teste com o client stock REAL, x402-fetch@1.2.0):
    # o client v1 lê o CORPO do 402 e valida accepts[] contra o schema Zod v1
    # (rede = nome curto "base"/"solana" + maxAmountRequired/resource/
    # description/mimeType). Nosso corpo v2 (CAIP-2 "eip155:8453") lançava
    # ZodError ANTES de qualquer lógica de pagamento — o desafio era
    # ilegível para o client padrão da rede. O client v2 (@x402/fetch) lê o
    # HEADER PAYMENT-REQUIRED primeiro e só aceita body com x402Version===1
    # como fallback. Logo: header segue v2, corpo vira PaymentRequired v1
    # puro, e acceptsV2 preserva o CAIP-2 para consumidores v2 de corpo.
    accepts_v1 = [x for x in (_accept_to_v1(a, endpoint) for a in accepts) if x]

    # v21 FIX: payload compatível com x402scan — campos da spec v2 + challenges
    payment_req = accepts[0] if accepts else {}
    _challenge_remember(endpoint, accepts)   # v39: usado na liquidação
    # v48.17.10-FUNNEL: registra a emissão do desafio (INSERT OR IGNORE, GC de
    # 30d a cada 200 inserções). Falha aqui JAMAIS pode derrubar um 402.
    try:
        LEDGER.funnel_challenge(_rid, endpoint)
    except Exception:
        pass
    # v48.9.1 HOTFIX: o Railway roda Python 3.11 (imagem python:3.11-slim) e
    # f-string NÃO aceita backslash dentro da expressão — SyntaxError no boot
    # (o sandbox validava em 3.12, que aceita; o erro só aparecia no deploy).
    # Por isso o pitch do anúncio é pré-computado aqui, fora da f-string.
    # v48.9.11-PITCH HOTFIX: o corte era split(".") — qualquer descrição com
    # decimal na 1ª frase ("pay $0.10…", "pay $0.99…") virava anúncio "pay $0"
    # em TODO 402 de plano (a linha 'error' é nossa vitrine principal). Agora
    # corta na fronteira de frase (". ") e nunca parte palavra no limite.
    _pitch = desc.split(". ")[0].strip()
    if len(_pitch) > 140:
        _pitch = _pitch[:140].rsplit(" ", 1)[0]
    _pitch = _pitch.replace("\u2014", "-").replace("\u2013", "-")
    _pitch = _pitch.encode("ascii", "ignore").decode()
    # v48.9.23-BAZAARFIX: o blob é montado UMA vez aqui — além de ir ao campo
    # extensions, ele alimenta o outputSchema V1 por accept (fix adiante).
    _bz_blob = _bazaar_blob(endpoint)
    payload = {
        # v48.9.12-DUAL: o CORPO é um PaymentRequired v1 (o client stock v1 só
        # lê o corpo; o client v2 lê o header PAYMENT-REQUIRED, que segue v2).
        "x402Version": 1,
        # v48.8-ADCOPY: "error" é a string que TODO cliente x402 expõe ao agente
        # comprador (x402-fetch loga, carteiras/aggregators exibem, a spec v1 a
        # define como mensagem human-readable opcional). Macete systemprompt.io:
        # "your 402 response IS your listing" — então esta linha é escrita como
        # anúncio: preço, prova grátis, chamada grátis e planos. Quem não usa o
        # campo simplesmente o ignora — custo zero de protocolo.
        "error": (
            f"Payment required: {endpoint} is ${amount_usdc:.4f}/call "
            f"(USDC on Base/Solana/Algorand). "
            f"{_pitch}. "
            f"Free delayed sample: GET {base}{endpoint}?preview=1 | "
            f"1 free real-time call: {base}/welcome | "
            f"plans from $0.10: {base}/plans"
        ),
        "resource": {
            "url":         f"{base}{endpoint}",
            "description": desc,
            "mimeType":    "application/json",
            # v25: Service Metadata da spec oficial do Bazaar — facilitators usam
            # estes campos para enriquecer os resultados de BUSCA com nome legível,
            # tags temáticas e ícone. Regras: serviceName/tags só ASCII imprimível
            # (<=32 chars cada, máx 5 tags); iconUrl absoluto https.
            "serviceName": SERVICE_NAME,
            "tags":        _service_tags(endpoint),
            "iconUrl":     f"{base}/favicon.png",
        },
        "accepts":    accepts_v1,     # v1 (client stock lê o corpo)
        "acceptsV2":  accepts,        # v2 CAIP-2 (header + consumidores v2)
        # v39.7: a alternativa mais barata, no momento exato da decisão.
        "alternatives": _subscription_offer(endpoint, amount_usdc),
        # v47.6.3 (parceria stipend.sh): agente SEM carteira recebe o caminho
        # para se equipar sozinho. JSON estático — nada chama casa, nenhum
        # beacon. A 3ª linha é deliberada: qualquer carteira EIP-3009 serve.
        "no_wallet": {
            "install": "npx -y stipend",
            "docs":    "https://stipend.sh/skill.md",
            "any_wallet_works": "You do not need this one. Any address that "
                                "can sign an EIP-3009 authorisation on Base "
                                "works here.",
        },
        # v1 backward compat: alguns scanners (x402scan legacy) esperam paymentRequirements
        "paymentRequirements": accepts_v1[0] if accepts_v1 else None,
        # challenges: formato alternativo que alguns scanners esperam (v1)
        "challenges": [{
            "scheme": acc.get("scheme", "exact"),
            "network": acc.get("network", "solana"),
            "asset": acc.get("asset", USDC_MINT),
            "maxAmountRequired": acc.get("maxAmountRequired", "0"),
            "payTo": acc.get("payTo", RECEIVE_ADDRESS),
            "maxTimeoutSeconds": acc.get("maxTimeoutSeconds", 300),
        } for acc in accepts_v1],
        # v21.4 FIX: extensions DEVE ser objeto ({}), nunca null — o PayAI rejeita
        # com "extensions: Invalid input: expected record, received null" porque o
        # cliente (AgentCash) ecoa esse campo no PaymentPayload que envia de volta.
        "extensions": {"bazaar": _bz_blob},
        # v23.2: todo 402 é uma vitrine — agente sem saldo sai com um caminho
        "upsell": {
            # v24.6: AMOSTRA EMBUTIDA — o achado da telemetria: 6.000 sondagens/dia
            # e ZERO usos do ?preview=1. Scanners não fazem segunda chamada. Então
            # a amostra agora viaja DENTRO do 402: o agente vê a forma real do dado
            # na mesma resposta em que descobre o preço. Zero requests extras.
            "sample": _inline_sample(endpoint),
            "free_preview": {
                "endpoint": f"{base}{endpoint}?preview=1",
                "cost": "0.00",
                "note": "Same resource, real data delayed ~15min. Evaluate before paying."},
            "try_free": [f"{base}{endpoint}?preview=1", f"{base}/try", f"{base}/sample",
                         f"{base}/losbeto-alpha", f"{base}/receipts"],
            # v41: A PONTE QUE FALTAVA ENTRE AVALIAR E PAGAR.
            # O funil real mostra ~10-20 avaliações/dia (python-requests) que
            # veem a amostra ATRASADA e somem. Amostra atrasada prova que o
            # node está vivo, mas não prova o valor do real-time. Uma chamada
            # REAL de graça (custo marginal ~$0 nos endpoints de dados) é o
            # trial que todo SaaS de API tem — e o x402 não tinha.
            "first_call_free": {
                "endpoint": f"{base}/welcome",
                "cost": "0.00",
                "note": ("One FREE real-time call, no payment and no signup. "
                         "GET /welcome, then send the returned token as the "
                         "X-Welcome-Token header to any whitelisted endpoint.")},
            "tasting_menu": {"endpoint": f"{base}/try", "cost": "0.00",
                             "note": "One free call = live samples from 6 endpoints."},
            "cheapest_paid": _cheapest_paid(base),
            "credits": {"endpoint": f"{base}/buy-credits",
                        "deal": "Pay $0.99 once, get $1.25 of credit (+25%), zero settlement latency",
                        "micro_bundle": {"endpoint": f"{base}/buy-credits-micro",
                                         "deal": "Pay $0.10 once, get $0.11 of credit (+10%)",
                                         "note": "Starter bundle sized to clear the 0.1 USDC default spend cap of stock x402 clients — recommended first autonomous purchase"}},
            "plans_catalog": {"endpoint": f"{base}/plans",
                              "note": ("Machine-readable plan ladder: per-plan "
                                       "break-even math, value ratio and the "
                                       "recommended first purchase.")},
            "llm_gateway": {"endpoint": f"{base}/v1/chat/completions",
                            "openai_compatible": True,
                            "price_usd": f"{globals().get('LLM_PROXY_PRICE', 0.005):.4f}",
                            "status": f"{base}/llm/status",
                            "try_free": f"{base}/llm/free?q=your+prompt",
                            "note": ("Flagship: pay-per-call LLM inference — change "
                                     "base_url in any OpenAI SDK. The same wallet "
                                     "buys every data primitive in this catalog.")},
            # v48.6.0-REGISTER: 42 pedidos/7d batendo em /register·/signup·
            # /auth/callback (radar). A porta existe agora — e todo 402 aponta
            # para ela em JSON puro, no momento exato da decisão de compra.
            "registration": {"needed": False,
                             "docs_get": f"{base}/register",
                             "buy_key_post": f"{base}/register",
                             "price_usdc": 0.99,
                             "note": ("No signup required — payment is the credential. "
                                      "Playbook requires an api_key? POST /register, "
                                      "answer this same x402 flow, and the response IS "
                                      "your key pre-loaded with $1.25 of call credit.")},
            "docs": f"{base}/llms.txt"},
    }
    # v21 FIX: base64 padrão (não URL-safe) — scanners usam b64decode padrão.
    # v25 FIX CRÍTICO: NÃO remover o padding "=". A spec x402 v2 exige o payload
    # PaymentRequired em base64 canônico no header PAYMENT-REQUIRED; sem padding,
    # b64decode() estrito falha com "Incorrect padding" em ~75% dos endpoints
    # (todo payload cujo tamanho não é múltiplo de 3). Isso quebrava a leitura
    # do desafio por clientes/facilitators que seguem a spec à risca — e explica
    # a extensão bazaar chegar VAZIA ({}) no catálogo da CDP.
    # v28.1 FIX CRÍTICO: o CORPO leva tudo; o HEADER leva uma versão enxuta.
    # Diagnóstico: a resposta 402 chegou a 19.627 bytes de cabeçalhos
    # (WWW-Authenticate 6.2k + PAYMENT-REQUIRED 6k + X-PAYMENT-REQUIRED 6k
    # duplicado). Node.js aborta acima de 16 KB e proxies cortam em 8 KB —
    # por isso clientes Node (AgentCash) recebiam NETWORK_ERROR em TODO
    # endpoint pago, enquanto os gratuitos funcionavam. Zero pagamentos em 24h.
    # Solução: amostra embutida e exemplos do bazaar ficam só no corpo.
    def _slim(p: dict) -> dict:
        """Versão do desafio para o CABEÇALHO: só o que um cliente precisa
        para pagar. Marketing, amostras e duplicatas ficam no corpo."""
        import copy
        ext = copy.deepcopy((p.get("extensions") or {}).get("bazaar") or {})
        info_out = (ext.get("info") or {}).get("output") or {}
        # v48.9.23-BAZAARFIX: o extrator V2 do Bazaar (ValidateAndExtract, ver
        # pkg.go.dev coinbase/x402 go/extensions/bazaar) exige info+schema
        # JUNTOS — sem `schema` a extensão inteira do header era descartada.
        # O schema é pequeno (~300 B) e fica. O EXEMPLO de saída (pesado) só
        # fica se couber folgado no orçamento de cabeçalho.
        _ex = info_out.get("example")
        if _ex is not None:
            try:
                if len(json.dumps(_ex, default=str)) > 480:
                    info_out.pop("example", None)
            except Exception:
                info_out.pop("example", None)
        # v34: descrição TRUNCADA no cabeçalho. O pior caso chegou a 7.373 bytes
        # (90% do limite de 8 KB) por causa de descrições longas. O texto integral
        # continua no corpo e nos manifests; no header basta o suficiente para o
        # cliente saber o que está comprando.
        _res = dict(p.get("resource") or {})
        if isinstance(_res.get("description"), str) and len(_res["description"]) > 220:
            _res["description"] = _res["description"][:217].rstrip() + "..."
        _ext_desc = ext.get("description")
        if isinstance(_ext_desc, str) and len(_ext_desc) > 220:
            ext["description"] = _ext_desc[:217].rstrip() + "..."
        return {
            # v48.9.12-DUAL: o CABEÇALHO é sempre o payload v2 (o corpo virou
            # v1). O client @x402/fetch lê este header primeiro.
            "x402Version": 2,
            "resource":    _res,
            "accepts":     p.get("acceptsV2") or p.get("accepts"),
            "extensions":  {"bazaar": ext},
            # "challenges" (cópia de accepts) e "upsell" (amostra, try_free,
            # créditos, docs) permanecem apenas no CORPO — não são necessários
            # para executar o pagamento e custavam ~2 KB de cabeçalho.
        }
    # v39.1: o registro no x402scan avisou "Paid endpoint is missing an input
    # schema" em todos os endpoints com parâmetro. O schema alimenta a busca
    # semântica dos diretórios e diz ao agente COMO chamar sem tentativa e erro.
    _hints = ENDPOINT_PARAM_HINTS.get(endpoint, {})
    _props = {k: {"type": "string",
                  "description": _PARAM_DESC.get(k, f"{k} parameter"),
                  "example": v}
              for k, v in _hints.items() if k != "format"}
    # v44.9.1: endpoints POST declaram o schema do CORPO (não queryParams) —
    # era o warning "missing an input schema" do registro no x402scan.
    _bs402 = ENDPOINT_BODY_SCHEMAS.get(endpoint) if "ENDPOINT_BODY_SCHEMAS" in globals() else None
    if _bs402:
        payload["inputSchema"] = _bs402["schema"]
        payload["inputMethod"] = _bs402["method"]
        payload["inputContentType"] = _bs402["contentType"]
        payload["inputExample"] = _bs402["example"]
    else:
        payload["inputSchema"] = {
            "type": "object",
            "properties": _props,
            # v48.9.19-CATALOG: _props já exclui "format"; o que sobra é
            # parâmetro funcional = obrigatório (mesma regra do bazaar blob).
            "required": sorted(_props.keys()),
            "additionalProperties": False,
        }
    payload["outputSchema"] = {"type": "object", "mimeType": "application/json"}

    # v48.9.10-PLANS: o 402 de um PLANO passa a ser o manual de operação da
    # máquina. Diagnóstico (22/09): os planos já estavam no manifesto e o
    # fluxo de compra já funcionava — mas o corpo não dizia O QUE o pagamento
    # entrega nem COMO operar depois, e o agente autônomo abortava na dúvida
    # (os policy engines recusam em silêncio, sem X-PAYMENT nos logs).
    # Padrão que converte (MapMap): o 402 do topup carrega extra.bundles +
    # instrução de poll; e o bundle de $0.10 passa no teto default de
    # 0.1 USDC dos clients x402 stock.
    if endpoint in CREDIT_PLANS:
        _cp = CREDIT_PLANS[endpoint]
        _bundles = [
            {"endpoint":   _p,
             "price_usdc": BASE_PRICES.get(_p),
             "credit_usd": _cfg.get("balance_usd"),
             "ttl_days":   _cfg.get("ttl_days"),
             "bonus":      _cfg.get("bonus")}
            for _p, _cfg in CREDIT_PLANS.items()
            if _cfg.get("plan") == "credits" and (_cfg.get("balance_usd") or 0) > 0
        ]
        if _cp.get("balance_usd", 0) == -1:
            _what = (f"Unlimited calls on every endpoint in this catalog for "
                     f"{_cp['ttl_days'] * 24}h — one payment, no per-call 402.")
        else:
            _what = (f"Prepaid call credit: pay {amount_usdc:.2f} USDC once, "
                     f"receive {_cp['balance_usd']:.2f} USD of balance "
                     f"({_cp['bonus']} bonus), valid {_cp['ttl_days']} days, "
                     f"spent at public prices on EVERY paid endpoint in this catalog.")
        payload["instructions"] = {
            "what_you_buy":  _what,
            "delivery":      ("Pay this 402 and the JSON response of THIS SAME "
                              "request returns {api_key, balance_usd, expires_iso}. "
                              "The key IS the credential — no signup, no account. "
                              "Idempotent by transaction hash: re-submitting the "
                              "same tx returns the same key, never a double charge."),
            "how_to_use":    ("Send the key as the 'X-API-Key' header on any "
                              "catalog endpoint. The 402 flow is skipped and the "
                              "balance is debited in ~1ms — no per-call settlement "
                              "latency."),
            "balance_check": (f"GET {base}/credits-status?key=YOUR_KEY returns "
                              "remaining balance and expiry. Poll BEFORE re-paying."),
            "topup_loop":    ("Low-water pattern: when balance_usd falls below your "
                              "per-call budget, buy any bundle again. Each purchase "
                              "issues a NEW key — size the bundle to your spend horizon."),
            "bundles":       _bundles,
        }
        payload["extra"] = {
            "bundles": _bundles,
            "spend_cap_note": ("The $0.10 micro-bundle (/buy-credits-micro) clears "
                               "the default maxAmountToPay (0.1 USDC) of "
                               "unconfigured stock x402 clients."),
        }
        payload["outputSchema"] = {
            "type": "object", "mimeType": "application/json",
            "properties": {
                "api_key":     {"type": "string",
                                "description": "Credential for the X-API-Key header. Shown once — store it."},
                "balance_usd": {"type": "number",
                                "description": "Prepaid call balance in USD."},
                "expires_iso": {"type": "string",
                                "description": "UTC expiry of the balance."},
                "idempotent_replay": {"type": "boolean",
                                      "description": "true when this transaction had already issued this key."},
            },
            "required": ["api_key", "balance_usd", "expires_iso"],
        }

    # ------------------------------------------------------------------
    # v48.9.23-BAZAARFIX — A PORTA DE ENTRADA DO ÍNDICE V1 DO BAZAAR.
    # Evidência: x402-foundation/x402 issue #2844 (confirmado lendo o SDK,
    # extensions/bazaar/v1 extract_discovery_info_v1): em payload V1 o
    # extrator do Bazaar lê `outputSchema` EM CADA entrada accepts[], no
    # shape {input:{type:"http",method,discoverable,...}, output:<exemplo
    # DIRETO, sem envelope "example">}. extensions.bazaar é o caminho V2 e
    # NÃO é lido pelo extrator V1; o outputSchema do topo do payload também
    # não. Sem este campo o recurso LIQUIDA normalmente mas fica
    # silenciosamente fora do índice — o nosso sintoma (extension_responses
    # "processing" eterno). O schema Zod v1 do client stock não é strict:
    # campos extras passam sem erro (comprovado pelo campo "amount" que já
    # vai nos accepts v1 e é aceito por PayAI e clientes).
    # ------------------------------------------------------------------
    try:
        _bz_info = (_bz_blob.get("info") or {}) if isinstance(_bz_blob, dict) else {}
        _os_in = dict(_bz_info.get("input") or {})
        if not _os_in:
            _os_in = {"type": "http", "method": "GET"}
        _os_in["discoverable"] = True
        if str(_os_in.get("method", "GET")).upper() != "GET":
            # POST: o extrator V1 espera bodyType/body — espelha o exemplo
            _os_in.setdefault("bodyType", "json")
            if "bodyParams" in _os_in and "body" not in _os_in:
                _os_in["body"] = _os_in["bodyParams"]
        _os_out = (_bz_info.get("output") or {}).get("example")
        if not isinstance(_os_out, dict) or not _os_out:
            # Sem amostra quente no cache: declara a FORMA mínima que toda
            # resposta paga deste nó carrega de fato (ts + version).
            _os_out = {"ts": 1759000000, "version": VERSION}
        _os_v1 = {"input": _os_in, "output": _os_out}
        for _a in accepts_v1:
            _a["outputSchema"] = _os_v1
        # O espelho legacy (scanners que leem paymentRequirements) acompanha.
        if isinstance(payload.get("paymentRequirements"), dict):
            payload["paymentRequirements"]["outputSchema"] = _os_v1
    except Exception as _e:
        log.debug(f"v48.9.23 outputSchema v1 {endpoint}: {_e}")

    # v48.13.0-INTEL: cross-sell dentro do proprio 402 — a recomendacao
    # aparece no instante exato em que o agente ja decidiu pagar. Custo: zero.
    try:
        _ab = _also_bought(endpoint)
        if _ab:
            payload["also_bought"] = _ab[:3]
    except Exception:
        pass
    payload_hdr = _slim(payload)
    b64 = base64.b64encode(
        json.dumps(payload_hdr, separators=(",", ":")).encode()
    ).decode()
    resp = jsonify(payload)            # corpo: payload COMPLETO
    resp.status_code = 402
    # v21.1 FIX: além do blob base64 opaco (challenge="..."), expõe os campos reais
    # do desafio de pagamento como auth-params legíveis (RFC 9110 §11.3), no formato
    # que scanners como o x402scan procuram ("no Payment challenges" era esse warning).
    primary = accepts[0] if accepts else {}
    # v28.1: o challenge base64 NÃO vai aqui — ele já está em PAYMENT-REQUIRED.
    # Repetir o blob triplicava o tamanho dos cabeçalhos.
    # v34 FIX — REGRESSÃO INTRODUZIDA NA v28.1.
    # Ao enxugar os cabeçalhos de 19,6 KB, removi o `challenge="<b64>"` do
    # WWW-Authenticate. Resultado: o registro no x402scan passou a avisar
    # "WWW-Authenticate header contains no Payment challenges" em 70 dos 79
    # recursos — exatamente o aviso que a v21.1 havia eliminado.
    # Correção: challenge volta, mas COMPACTO. O blob completo (~4,8 KB) fica
    # só em PAYMENT-REQUIRED; aqui vai o mínimo que um cliente precisa para
    # pagar: versão + accepts essenciais. ~500 bytes em vez de 6 KB.
    _min_accepts = [{k: a[k] for k in
                     ("scheme", "network", "asset", "amount", "payTo", "maxTimeoutSeconds")
                     if k in a} for a in accepts]
    _chal = base64.b64encode(json.dumps(
        {"x402Version": 2, "accepts": _min_accepts},
        separators=(",", ":")).encode()).decode()
    auth_params = [f'realm="x402"', f'challenge="{_chal}"']
    if primary:
        for k in ("scheme", "network", "asset", "amount", "payTo", "maxTimeoutSeconds"):
            v = primary.get(k)
            if v is not None:
                auth_params.append(f'{k}="{v}"')
    resp.headers["WWW-Authenticate"] = "x402 " + ", ".join(auth_params)
    # v42 — SEGUNDO challenge, no shape MPP (RFC 7235 permite N challenges).
    # O validador da agentic.market/x402scan/MPPScan procura um auth-scheme
    # "Payment"; sem ele, TODOS os 74 endpoints apareciam com warning no
    # registro. O desafio x402 continua primeiro (compat total); este apenas
    # descreve o MESMO pagamento no vocabulário MPP (charge intent mapeia
    # direto o fluxo "exact" do x402 — é o que a spec chama de backward-compat).
    if MPP_CHALLENGE:
        resp.headers.add("WWW-Authenticate", _mpp_challenge(endpoint, primary))
    # v48.14.0-MONETIZE: challenges MPP REAIS (method="tempo") — um por
    # moeda aceita; o agente escolhe a que tem saldo. Settlement push mode.
    if MPP_TEMPO:
        for _cur in MPP_TEMPO_CURRENCIES:
            try:
                resp.headers.add("WWW-Authenticate",
                                 _mpp_tempo_challenge(endpoint, amount_usdc, _cur))
            except Exception:
                pass
    resp.headers["PAYMENT-REQUIRED"]   = b64
    # v28.1: era uma cópia byte a byte de PAYMENT-REQUIRED (+6 KB à toa).
    # Mantido só se couber no orçamento total de cabeçalhos.
    if len(b64) <= 2048:
        resp.headers["X-PAYMENT-REQUIRED"] = b64
    else:
        resp.headers["X-Payment-Required-Ref"] = "see PAYMENT-REQUIRED header"
    # v24.5: cliente que só lê headers (muitos agentes) também descobre o preview
    resp.headers["X-Free-Preview"] = f"{base}{endpoint}?preview=1"
    # v48.3.6-CONVERT: SDKs e crawlers de diretório que só leem HEADERS nunca
    # viam o bloco alternatives.plans (só existe no corpo). A matemática do
    # plano mais barato agora viaja em header puro, calculada no preço DESTE
    # endpoint — a máquina decide sem parsear o corpo.
    resp.headers["X-Plans"] = f"{base}/plans"
    if endpoint not in CREDIT_PLANS and amount_usdc > 0:
        _cheap = min(((BASE_PRICES[ep], ep) for ep in CREDIT_PLANS
                      if BASE_PRICES.get(ep)), default=None)
        if _cheap:
            _be = int(_cheap[0] / amount_usdc) + 1
            resp.headers["X-Cheapest-Plan"] = (
                f"price_usdc={_cheap[0]:.2f};breaks_even_after={_be};"
                f"buy={base}{_cheap[1]}")
    resp.headers["X-402-Version"]      = "1,2"
    resp.headers["X-Node-Id"]          = WALLET.node_id
    resp.headers["X-Accept-Chains"]    = ",".join([a["network"] for a in accepts])
    # Link header para discovery legacy (Web Monetization / ILP compat)
    resp.headers["Link"] = (f'<{base}{endpoint}?preview=1>; rel="preview"; type="application/json", '
                            f'<{base}/.well-known/x402.json>; rel="payment"')
    # Accept-Payment header para compatibilidade com draft specs
    resp.headers["Accept-Payment"] = f'x402; networks={",".join(a["network"] for a in accepts)}'
    # v41: agentes que rodam em browser (fetch/XHR) não conseguem LER o
    # PAYMENT-REQUIRED sem CORS expose — o desafio existia mas era invisível
    # para clientes web (metade das avaliações diárias são navegadores).
    resp.headers["Access-Control-Expose-Headers"] = (
        "PAYMENT-REQUIRED,X-PAYMENT-REQUIRED,WWW-Authenticate,X-Free-Preview,"
        "X-402-Version,X-Accept-Chains,X-Plans,X-Cheapest-Plan")
    return resp

def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()

def _ascii_header(s: str) -> str:
    """v42.1 FIX CRÍTICO: valores de header HTTP devem ser ASCII (RFC 7230).
    ENDPOINT_DESC tem tipografia rica (—, ·, ç, ã) — quando o travessão caía
    nos primeiros 90 chars, o challenge MPP saía com byte não-ASCII e clients
    HTTP estritos (httpx, Node undici) ABORTAVAM a request ao ecoar o valor.
    Foi o que derrubou 6 endpoints no Agentic.Market ([502] 'No valid x402
    response found') e inundou o gunicorn com 'Invalid HTTP Header' — todos
    os 6 tinham U+2014 dentro da janela de 90 chars; os endpoints com — depois
    do char 90 passavam pela truncagem. Coincidência perfeita, bug real."""
    s = (s or "").replace("—", "-").replace("–", "-").replace("·", "|")
    return s.encode("ascii", "ignore").decode("ascii")

def _mpp_challenge(endpoint: str, primary: dict) -> str:
    """v42: challenge no formato MPP (IETF draft-httpauth-payment-00).
    id vinculado aos termos (endpoint+valor+payTo, janela de 5 min) — o mesmo
    padrão stateless da spec; request em base64url com o mapeamento charge→exact:
    amount atômico, moeda, destinatário, rede e asset. Clients MPP reconhecem o
    auth-scheme "Payment" e validadores deixam de marcar o endpoint com warning.

    LIMITAÇÃO DECLARADA (v42.1): method="x402" não é um payment method MPP
    registrado — a spec é agnóstica e métodos são definidos em specs separadas.
    Este challenge satisfaz scanners de diretório (X402Scan/MPPScan/Agentic.
    Market) e documenta os termos num formato legível; o fluxo MPP completo
    (Credential/Receipt) NÃO é implementado. Um client MPP bem-comportado
    ignora métodos desconhecidos e cai no challenge x402 ao lado — que é o
    caminho real de pagamento. Se um dia existir method spec x402 registrada,
    basta implementar o handshake aqui."""
    base = _public_base()
    atomic = str(primary.get("amount") or primary.get("maxAmountRequired") or "0")
    req = {"amount": atomic,
           "currency": "USDC",
           "recipient": primary.get("payTo", ""),
           "network": primary.get("network", ""),
           "asset": primary.get("asset", ""),
           "resource": f"{base}{endpoint}",
           "protocol": "x402-exact"}
    blob = _b64url(json.dumps(req, separators=(",", ":"), sort_keys=True).encode())
    cid = hashlib.sha256(
        f"mpp|{endpoint}|{atomic}|{primary.get('payTo')}|{int(time.time() // 300)}"
        .encode()).hexdigest()[:20]
    desc = _ascii_header(ENDPOINT_DESC.get(endpoint, endpoint) or "")[:90].replace('"', "'")
    exp = datetime.fromtimestamp(time.time() + 300, timezone.utc
                                 ).strftime("%Y-%m-%dT%H:%M:%SZ")
    return (f'Payment id="{cid}", realm="losbeto", method="x402", intent="charge", '
            f'request="{blob}", expires="{exp}", description="{desc}"')

# ============================================================================
# v48.14.0-MONETIZE — TRILHO MPP/TEMPO REAL + INTELIGENCIA DE RECEITA
#
# 1) MPP tempo/charge (IETF draft-httpauth-payment + draft-tempo-charge-00),
#    modo PUSH: o cliente liquida TIP-20 na Tempo (chainId 4217) e volta com
#    Authorization: Payment <credential> carregando o hash da tx. O node
#    verifica o receipt on-chain (evento Transfer do token = valor, destino,
#    moeda), faz anti-replay atomico e devolve Payment-Receipt. Dois desafios
#    sao emitidos por 402 (USDC.e + pathUSD) — o agente escolhe a moeda que
#    tem. SEM Stripe, SEM chave privada no servidor (push mode nao co-assina:
#    quem transmite a tx e o cliente). Captura a onda de saldos AgentCash que
#    nascem na rede Tempo — o node passa a falar o protocolo deles DE VERDADE.
# 2) /ecosystem-pulse ($0.05): o node VENDE a inteligencia que os 64k probes
#    geram — demanda por endpoint, IPs-agente unicos, tendencias 7d vs 7d
#    (z-score) e clusters de demanda emergente. O trafego de scanner vira
#    produto em vez de custo puro.
# 3) Price-elasticity advisor: funil probes→previews→vendas por endpoint,
#    sugestao de preco GLOBAL (nunca por carteira) via Telegram; PRICE_AUTO=1
#    aplica com trava de +-30%/semana e persiste em /data. Padrao: so avisa.
# 4) Radar auto-atendimento ganha fallback SEMANTICO: quando a similaridade
#    lexical falha, embeddings (multilingue se preciso) casam o 404 pelo
#    SIGNIFICADO — /cotacao-bitcoin encontra /pyth-price. Mesmas travas de
#    seguranca (so aliasa para rota real, limiar conservador, cap semanal).
# ============================================================================
MPP_TEMPO = os.environ.get("MPP_TEMPO", "1") != "0"
MPP_TEMPO_RECIPIENT = (os.environ.get("MPP_TEMPO_RECIPIENT")
                       or "0xcC83159a6513E56778dA45A2981f55F44eF8e9E2").strip()
TEMPO_RPC = os.environ.get("TEMPO_RPC_URL", "https://rpc.tempo.xyz").strip()
TEMPO_CHAIN_ID = int(os.environ.get("TEMPO_CHAIN_ID", "4217"))
MPP_MIN_CONF = int(os.environ.get("MPP_MIN_CONF", "2"))
_TIP20_TRANSFER_TOPIC0 = ("0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef")
MPP_TEMPO_CURRENCIES = [c.strip().lower() for c in os.environ.get(
    "MPP_TEMPO_CURRENCIES",
    "0x20c000000000000000000000b9537d11c60e8b50,"   # USDC.e na Tempo mainnet
    "0x20c0000000000000000000000000000000000000"    # pathUSD (Bridge) na Tempo
).split(",") if c.strip()]
_MPP_CHAL_TTL = int(os.environ.get("MPP_CHALLENGE_TTL", "600"))


def _b64url_pad(s: str) -> str:
    return s + "=" * (-len(s) % 4)


def _mpp_tempo_challenge(endpoint: str, amount_usd: float, currency: str) -> str:
    """Challenge MPP real (method=tempo, intent=charge). O id e um HMAC de
    (endpoint, request) — stateless, sem tabela: qualquer worker verifica.
    request carrega amount/currency/recipient/expires — mexer em qualquer
    campo invalida o id. TTL 600s >> cache de desafio (45s)."""
    amt = str(int(round(float(amount_usd) * 1_000_000)))
    exp = datetime.fromtimestamp(time.time() + _MPP_CHAL_TTL, timezone.utc
                                 ).strftime("%Y-%m-%dT%H:%M:%SZ")
    req = {"amount": amt, "currency": currency, "recipient": MPP_TEMPO_RECIPIENT,
           "expires": exp,
           "methodDetails": {"chainId": TEMPO_CHAIN_ID, "supportedModes": ["push"]}}
    blob = _b64url(json.dumps(req, separators=(",", ":"), sort_keys=True).encode())
    cid = hmac.new(JWT_SECRET.encode(), f"mpp|{endpoint}|{blob}".encode(),
                   hashlib.sha256).hexdigest()[:24]
    desc = _ascii_header(ENDPOINT_DESC.get(endpoint, endpoint) or "")[:90].replace('"', "'")
    return (f'Payment id="{cid}", realm="losbeto", method="tempo", intent="charge", '
            f'request="{blob}", expires="{exp}", description="{desc}"')


def _tempo_rpc(method: str, params: list):
    """JSON-RPC contra a Tempo mainnet. Levanta excecao em erro de transporte."""
    r = requests.post(TEMPO_RPC, timeout=12,
                      json={"jsonrpc": "2.0", "id": 1, "method": method,
                            "params": params})
    j = r.json()
    if j.get("error"):
        raise RuntimeError(str(j["error"])[:160])
    return j.get("result")


def _mpp_verify_credential(endpoint: str, cred_b64: str):
    """Verifica um credential MPP tempo/charge push-mode.
    Retorna (ok, reason, info) no mesmo contrato de _verify_payment.
    Ordem de custo: parse local -> HMAC -> termos -> anti-replay atomico ->
    RPC. Lixo morre de graca; falha transitoria devolve a reserva de replay
    (o cliente pode tentar de novo); falha definitiva do cliente QUEIMA o
    hash (nao vira cupom reutilizavel)."""
    try:
        cred = json.loads(base64.urlsafe_b64decode(_b64url_pad(cred_b64)).decode())
        ch = cred.get("challenge") or {}
        payload = cred.get("payload") or {}
        req_b64 = str(ch.get("request") or "")
        req = json.loads(base64.urlsafe_b64decode(_b64url_pad(req_b64)).decode())
    except Exception:
        return False, "malformed-credential", {}
    if ch.get("method") != "tempo" or ch.get("intent") != "charge":
        return False, "unsupported-method", {}
    expect = hmac.new(JWT_SECRET.encode(), f"mpp|{endpoint}|{req_b64}".encode(),
                      hashlib.sha256).hexdigest()[:24]
    if not hmac.compare_digest(str(ch.get("id", "")), expect):
        return False, "challenge-mismatch", {}
    try:
        _exp = datetime.strptime(str(req.get("expires", "")),
                                 "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        if time.time() > _exp.timestamp():
            return False, "challenge-expired", {}
    except Exception:
        return False, "challenge-expired", {}
    try:
        want_amt = int(req["amount"])
    except Exception:
        return False, "bad-amount", {}
    currency = str(req.get("currency", "")).lower()
    recipient = str(req.get("recipient", "")).lower()
    if recipient != MPP_TEMPO_RECIPIENT.lower():
        return False, "wrong-recipient", {}
    if currency not in MPP_TEMPO_CURRENCIES:
        return False, "wrong-currency", {}
    try:
        if int((req.get("methodDetails") or {}).get("chainId", 0)) != TEMPO_CHAIN_ID:
            return False, "wrong-chain", {}
    except Exception:
        return False, "wrong-chain", {}
    # Preco dinamico pode ter andado entre desafio e pagamento — honra a
    # cotacao com 3% de tolerancia (mesma filosofia do challenge-recall x402).
    cur_atomic = int(round(get_dynamic_price(endpoint) * 1_000_000))
    if want_amt < int(cur_atomic * 0.97):
        return False, "insufficient-amount", {}
    if str(payload.get("type")) != "hash":
        return False, "unsupported-mode", {}
    txh = str(payload.get("hash", "")).lower()
    if not re.fullmatch(r"0x[0-9a-f]{64}", txh):
        return False, "bad-tx-hash", {}
    if not LEDGER.replay_claim("mpp:" + txh):
        return False, "replay", {}
    try:
        rcpt = _tempo_rpc("eth_getTransactionReceipt", [txh])
        if not rcpt:
            LEDGER.replay_unmark("mpp:" + txh)
            return False, "tx-not-found", {}
        if str(rcpt.get("status")) != "0x1":
            return False, "tx-failed", {}
        payer, got = "", 0
        for lg in (rcpt.get("logs") or []):
            if str(lg.get("address", "")).lower() != currency:
                continue
            tpcs = lg.get("topics") or []
            if len(tpcs) < 3 or str(tpcs[0]).lower() != _TIP20_TRANSFER_TOPIC0:
                continue
            if not str(tpcs[2]).lower().endswith(recipient[2:]):
                continue
            try:
                v = int(str(lg.get("data", "0x0")), 16)
            except Exception:
                continue
            if v > got:
                got = v
                payer = "0x" + str(tpcs[1])[-40:]
        if got < want_amt:
            return False, "insufficient-amount", {}
        tip = _tempo_rpc("eth_blockNumber", [])
        bn = int(str(rcpt.get("blockNumber", "0x0")), 16)
        if tip is not None and int(str(tip), 16) - bn < MPP_MIN_CONF:
            LEDGER.replay_unmark("mpp:" + txh)
            return False, "insufficient-confirmations", {}
    except Exception as e:
        LEDGER.replay_unmark("mpp:" + txh)
        log.warning(f"mpp tempo rpc: {e}")
        return False, "rpc-error", {}
    usd = round(want_amt / 1_000_000, 6)
    LEDGER.add_revenue(endpoint, usd, txh, payer, source="mpp", chain="tempo")
    receipt = {"method": "tempo", "reference": txh, "status": "success",
               "timestamp": datetime.fromtimestamp(time.time(), timezone.utc
                                                   ).strftime("%Y-%m-%dT%H:%M:%SZ")}
    log.info(f"💰 MPP/tempo ${usd:.4f} em {endpoint} de {payer[:14]}… tx {txh[:18]}…")
    return True, "mpp", {"payer": payer, "tx": txh,
                         "settlement": {"success": True, "transaction": txh,
                                        "payer": payer, "network": "tempo"},
                         "mpp_receipt": receipt}


# ---- /ecosystem-pulse — a inteligencia dos 64k probes/dia, como produto ----
_PULSE_CACHE = {"ts": 0, "data": None}
_PULSE_MONITORS = ("carbonmonitor", "x402-list-monitor", "lumiere",
                   "x402-observer", "forum-labs", "402explorer",
                   "bazaardiscovery", "x402scan", "uptime", "pingdom",
                   "statuscake", "betterstack", "hetrixtools")


def _h_ecosystem_pulse():
    """Vende o que o trafego ENSINA: quem sonda o que, quantos agentes reais,
    o que esta subindo. Dado exclusivo — nenhum concorrente tem o NOSSO funil.
    Cache 10min: a assinatura do dado e horaria, nao por-request."""
    now = int(time.time())
    if _PULSE_CACHE["data"] is not None and now - _PULSE_CACHE["ts"] < 600:
        return _PULSE_CACHE["data"]
    d1, d7, d14 = now - 86400, now - 7 * 86400, now - 14 * 86400
    with LEDGER._conn() as c:
        top = c.execute(
            "SELECT endpoint, COUNT(*) n, COUNT(DISTINCT ip) ips FROM requests "
            "WHERE ts>? GROUP BY endpoint ORDER BY n DESC LIMIT 25", (d1,)).fetchall()
        uas = c.execute(
            "SELECT ua, COUNT(*) n FROM requests WHERE ts>? AND ua!='' "
            "GROUP BY ua ORDER BY n DESC LIMIT 80", (d1,)).fetchall()
        cur7 = dict(c.execute("SELECT endpoint, COUNT(*) FROM requests WHERE ts>? "
                              "GROUP BY endpoint", (d7,)).fetchall())
        prev7 = dict(c.execute("SELECT endpoint, COUNT(*) FROM requests "
                               "WHERE ts>? AND ts<=? GROUP BY endpoint",
                               (d14, d7)).fetchall())
        tot24 = c.execute("SELECT COUNT(*) FROM requests WHERE ts>?", (d1,)).fetchone()[0]
        agent_ips = c.execute(
            "SELECT COUNT(DISTINCT ip) FROM requests WHERE ts>? AND "
            "(LOWER(ua) GLOB 'node*' OR LOWER(ua) GLOB 'python-requests*' "
            "OR LOWER(ua) GLOB 'axios*' OR LOWER(ua) GLOB 'undici*')", (d1,)).fetchone()[0]
        paid24 = c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM revenue "
                           "WHERE ts>?", (d1,)).fetchone()
    mon = sum(n for ua, n in uas if any(m in (ua or "").lower() for m in _PULSE_MONITORS))
    agent_hits = sum(n for ua, n in uas
                     if (ua or "").lower().startswith(("node", "python-requests",
                                                       "axios", "undici", "got")))
    rising = []
    for ep, n7 in cur7.items():
        p7 = prev7.get(ep, 0)
        if n7 >= 20:
            z = (n7 - p7) / math.sqrt(p7 + 1.0)
            if z > 2.0:
                rising.append({"path": ep, "hits_7d": int(n7), "hits_prev_7d": int(p7),
                               "z_score": round(z, 2)})
    rising.sort(key=lambda r: -r["z_score"])
    heat = []
    for ep, n, ips in top:
        z = (cur7.get(ep, 0) - prev7.get(ep, 0)) / math.sqrt(prev7.get(ep, 0) + 1.0)
        heat.append({"path": ep, "probes_24h": int(n), "unique_ips_24h": int(ips),
                     "heat": round(0.6 * max(-1.0, min(z / 5.0, 1.0))
                                   + 0.4 * min(ips / 50.0, 1.0), 3),
                     "served_live": bool(_route_now_live(ep))})
    clusters = []
    try:
        if _CLUSTER_FILE.exists():
            cj = json.loads(_CLUSTER_FILE.read_text())
            clusters = [{"example": c2.get("example"), "size": c2.get("size"),
                         "unique_ips": c2.get("unique_ips")}
                        for c2 in (cj.get("clusters") or [])[:5]]
    except Exception:
        pass
    data = {
        "generated_at": datetime.fromtimestamp(now, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "node": "losbeto",
        "window_hours": 24,
        "totals": {"requests_24h": int(tot24),
                   "agent_class_requests_24h": int(agent_hits),
                   "qos_monitor_requests_24h": int(mon),
                   "monitor_share_24h": round(mon / max(1, tot24), 3),
                   "agent_unique_ips_24h": int(agent_ips),
                   "paid_settlements_24h": int(paid24[0] or 0),
                   "revenue_24h_usd": round(float(paid24[1] or 0.0), 4)},
        "top_probed": heat[:15],
        "rising_7d": rising[:10],
        "emerging_demand_clusters": clusters,
        "methodology": {
            "agent_class": "UA families used by agent SDKs (node, python-requests, axios, undici, got)",
            "qos_monitors": "known uptime/directory scanners — counted separately, never blended into demand",
            "heat": "0.6*clip(7d-vs-prev-7d z-score / 5) + 0.4*clip(unique_ips_24h / 50)",
            "rising": "7d hits >= 20 and Poisson z-score > 2 vs the previous 7d window",
            "clusters": "weekly Agglomerative (cosine) clustering of 404 demand, on-node embeddings"},
        "notes": [
            "This is the node's own first-party traffic — data no third party can replicate.",
            "Counts are request-level probes (incl. unpaid 402 challenges); paid settlements are reported separately.",
            "Not financial advice."],
    }
    _PULSE_CACHE.update({"ts": now, "data": data})
    return data


# ---- price-elasticity advisor — ML de preco com governanca -----------------
PRICE_AUTO = os.environ.get("PRICE_AUTO", "") == "1"
_ML_PRICE_FILE = "/data/ml_price_overrides.json"
_PRICE_ADV_STATE = {"last_run": 0}


def _ml_price_overrides_load():
    """Carrega sugestoes auto-aplicadas (so com PRICE_AUTO=1). Override de ENV
    ( Railway Variables ) sempre vence o ML — operador > modelo."""
    try:
        if not os.path.exists(_ML_PRICE_FILE):
            return
        saved = json.loads(open(_ML_PRICE_FILE).read())
        n = 0
        for ep, rec in (saved or {}).items():
            # sem exigir ep in BASE_PRICES: o bloco roda ANTES do registro
            # dos produtos v47 — o get_dynamic_price consulta por endpoint.
            if _price_env_key(ep) not in os.environ:
                PRICE_OVERRIDES[ep] = float(rec["price"])
                n += 1
        if n:
            log.info(f"🧠💲 price-advisor: {n} precos ML restaurados de /data")
    except Exception as e:
        log.warning(f"price overrides load: {e}")


def _ml_price_advisor():
    """Funil por endpoint (probes 7d -> previews 7d -> vendas 7d) vira
    recomendacao de PRECO DE TABELA — global, igual para todo mundo (preco
    publico nunca varia por carteira; incentivo so pos-pagamento).
    PRICE_AUTO=1 aplica com trava: 1 movimento por endpoint por semana,
    limitado a +-30%, piso $0.01 e teto $0.50. Sem a flag: so Telegram."""
    now = int(time.time())
    d7 = now - 7 * 86400
    with LEDGER._conn() as c:
        probes = dict(c.execute(
            "SELECT endpoint, COUNT(*) FROM requests WHERE ts>? "
            "AND kind IN ('probe','challenge402') GROUP BY endpoint", (d7,)).fetchall())
        previews = dict(c.execute(
            "SELECT endpoint, COUNT(*) FROM requests WHERE ts>? AND kind='preview' "
            "GROUP BY endpoint", (d7,)).fetchall())
        sales = dict(c.execute(
            "SELECT endpoint, COUNT(*) FROM revenue WHERE ts>? GROUP BY endpoint",
            (d7,)).fetchall())
        rev = dict(c.execute(
            "SELECT endpoint, ROUND(SUM(amount),4) FROM revenue WHERE ts>? "
            "GROUP BY endpoint", (d7,)).fetchall())
    sugg = []
    for ep in sorted(BASE_PRICES, key=lambda e: -(probes.get(e, 0) + sales.get(e, 0))):
        p, pv, s = probes.get(ep, 0), previews.get(ep, 0), sales.get(ep, 0)
        if p < 20 and s == 0:
            continue
        cur = get_dynamic_price(ep)
        action = why = None
        newp = None
        if p >= 200 and pv >= 5 and s == 0:
            action, why = "lower", "high probe interest, previews happening, zero conversion"
            newp = max(0.01, round(cur * 0.75, 4))
        elif s >= 5 and pv >= 3 and s / max(1, pv) >= 0.25:
            action, why = "raise", "conversion >= 25% — demand is price-insensitive"
            newp = round(cur * 1.15, 4)
        elif p >= 50 and pv == 0 and s == 0:
            action, why = "review", "probes but no previews — description/teaser may be unclear"
        if action:
            sugg.append({"endpoint": ep, "current_usd": cur,
                         "suggested_usd": newp, "action": action, "why": why,
                         "probes_7d": p, "previews_7d": pv, "sales_7d": s,
                         "revenue_7d_usd": rev.get(ep, 0.0)})
    if not sugg:
        return {"suggestions": 0}
    applied = []
    if PRICE_AUTO:
        try:
            saved = {}
            if os.path.exists(_ML_PRICE_FILE):
                saved = json.loads(open(_ML_PRICE_FILE).read())
            for sg in sugg:
                ep, np_ = sg["endpoint"], sg["suggested_usd"]
                if np_ is None or sg["action"] == "review":
                    continue
                rec = (saved or {}).get(ep) or {}
                last_ts = int(rec.get("ts", 0))
                last_p = float(rec.get("price", sg["current_usd"]))
                if now - last_ts < 7 * 86400:
                    continue
                np_ = min(max(np_, last_p * 0.7), last_p * 1.3)   # trava +-30%/semana
                np_ = min(max(np_, 0.01), 0.50)
                if abs(np_ - sg["current_usd"]) < 0.0005:
                    continue
                if _price_env_key(ep) in os.environ:
                    continue   # operador fixou por env — ML nao pisa
                PRICE_OVERRIDES[ep] = round(np_, 4)
                saved[ep] = {"price": round(np_, 4), "ts": now}
                applied.append((ep, sg["current_usd"], round(np_, 4)))
            with open(_ML_PRICE_FILE, "w") as f:
                json.dump(saved, f, indent=1)
        except Exception as e:
            log.warning(f"price advisor apply: {e}")
    lines = []
    for sg in sugg[:6]:
        if sg["action"] == "review":
            lines.append(f"• `{sg['endpoint']}`: {sg['probes_7d']} probes, 0 previews — revisar descricao/teaser")
        else:
            lines.append(f"• `{sg['endpoint']}` ${sg['current_usd']:.3f} → ${sg['suggested_usd']:.3f} "
                         f"({sg['why']}; {sg['probes_7d']}p/{sg['previews_7d']}pv/{sg['sales_7d']}s)")
    _notify_telegram(
        f"🧠💲 *PRICE ADVISOR (semanal)*\n\n" + "\n".join(lines) +
        (f"\n\n✅ Auto-aplicados: {len(applied)} (trava +-30%/semana)"
         if PRICE_AUTO else "\n\nℹ️ Modo consultivo — PRICE_AUTO=1 para aplicar com trava.") +
        "\n_Preco de tabela global — nunca por carteira._")
    if applied:
        log.warning(f"🧠💲 price-advisor aplicou: {applied}")
    return {"suggestions": len(sugg), "applied": len(applied)}


# ---- radar semantico — o 404 encontra o catalogo pelo SIGNIFICADO ----------
_RADAR_SEM_MIN = float(os.environ.get("RADAR_SEM_MIN", "0.72"))


def _radar_semantic_target(path: str) -> str:
    """Fallback do radar: _suggest_paths e lexical (tokens do nome); aqui o
    embedding casa pela SEMANTICA (multilingue se o caminho nao for ingles).
    Retorna path do catalogo ou ''. Limiar conservador (0.72) — alias errado
    e pior que 404 honesto."""
    if not _ML_EMB_OK or _NP is None:
        return ""
    try:
        q = re.sub(r"[^a-z0-9à-ÿ]+", " ", (path or "").lower()).strip()
        if len(q) < 3:
            return ""
        key = "multi" if _needs_multi(q) else "base"
        paths, vecs = _emb_catalog(key)
        if not paths or vecs is None:
            return ""
        qv = _emb_encode([q], key)
        if qv is None:
            return ""
        V = _NP.array(vecs)
        V = V / (_NP.linalg.norm(V, axis=1, keepdims=True) + 1e-9)
        qn = _NP.array(qv[0])
        qn = qn / (_NP.linalg.norm(qn) + 1e-9)
        sims = V @ qn
        j = int(sims.argmax())
        if float(sims[j]) < _RADAR_SEM_MIN:
            return ""
        tgt = paths[j]
        return tgt if _radar_safe_target(tgt) else ""
    except Exception:
        return ""


