# ============================================================================
# 16. PREMIUM SUITE v24.4 — onde está 95% do volume x402 ($1+ por chamada).
#     5 produtos de síntese: uma chamada = inteligência pronta, não dado bruto.
#     Todos compostos dos 60 endpoints existentes + LLM (fallback determinístico
#     se nenhum LLM estiver configurado — o produto NUNCA quebra).
# ============================================================================

def _safe_call(fn, default=None):
    try:
        return fn()
    except Exception as e:
        log.debug(f"premium compose: {e}")
        return default if default is not None else {}

def _ai(prompt: str, max_tokens=700) -> str:
    """IA opcional: se falhar, o produto ainda tem valor sem ela."""
    try:
        out = LLM.ask(prompt, max_tokens=max_tokens, temperature=0.35)
        if out and "LLM offline" not in out:
            return out
    except Exception as e:
        log.debug(f"premium ai: {e}")
    return ""


def _ai_required(prompt: str, max_tokens=700) -> str:
    """IA obrigatória: usar quando a síntese É o produto.

    v39 — a v38 chamava _ai() em /council-deep, /br-brief, /portfolio-stress e
    /equity-dossier e, quando a cadeia de LLM estava fora, devolvia o campo de
    síntese VAZIO cobrando o preço cheio. Aqui a falha vira LLMUnavailable, que
    o decorador paid_endpoint converte em 503 + estorno em crédito.
    """
    out = _ai(prompt, max_tokens=max_tokens)
    if not out:
        raise LLMUnavailable()
    return out

def _premium_db_put(key: str, data: dict) -> None:
    try:
        c = _preview_db()
        try:
            c.execute("""CREATE TABLE IF NOT EXISTS premium_cache(
                key TEXT PRIMARY KEY, ts REAL, data TEXT)""")
            c.execute("INSERT OR REPLACE INTO premium_cache(key,ts,data) VALUES(?,?,?)",
                      (key, time.time(), json.dumps(data, default=str)))
            c.commit()
        finally:
            c.close()
    except Exception as e:
        log.debug(f"premium_db_put {key}: {e}")

def _premium_db_get(key: str, max_age: int = 90000):
    try:
        c = _preview_db()
        try:
            c.execute("""CREATE TABLE IF NOT EXISTS premium_cache(
                key TEXT PRIMARY KEY, ts REAL, data TEXT)""")
            row = c.execute("SELECT ts, data FROM premium_cache WHERE key=?",
                            (key,)).fetchone()
        finally:
            c.close()
        if row and time.time() - row[0] <= max_age:
            return json.loads(row[1])
    except Exception as e:
        log.debug(f"premium_db_get {key}: {e}")
    return None


class Premium:
    """Flagships $1+ — o formato que efetivamente vende no x402 em 2026."""

    # ------------------------------------------------------------------ 1
    @staticmethod
    def _brief_is_good(b) -> bool:
        """v25.5: um brief só pode ser servido (pago OU como preview) se foi
        gerado pela versão atual E tem dado real. Sem isso, o cache diário
        perpetuava para sempre um snapshot ruim: era exatamente o brief da
        v24.9 (ouro 2385 estático, SPY/QQQ/NVDA em 0) que a auditoria do
        x402-list reprovou — servido meses depois pelo ?preview=1."""
        try:
            if not isinstance(b, dict) or b.get("version") != VERSION:
                return False
            snap = b.get("snapshot") or {}
            eq = snap.get("equities") or {}
            cm = snap.get("commodities") or {}
            fx = snap.get("forex") or {}
            def _layer(d, key):
                """(presente, saudável) — 'presente com tudo zerado' é FALHA,
                não é 'camada ausente'. Era assim que o brief com SPY/QQQ/NVDA
                em 0 passava despercebido."""
                if not d:
                    return False, True
                vals = [(v or {}).get(key) for v in d.values()]
                return True, any(bool(x) for x in vals)
            eq_present, eq_ok = _layer(eq, "price")
            cm_present, cm_ok = _layer(cm, "price")
            fx_present, fx_ok = _layer(fx, "rate")
            # nenhuma camada declarada pode estar zerada
            if not (eq_ok and cm_ok and fx_ok):
                return False
            # e ao menos 2 camadas tradicionais precisam existir de fato
            return sum([eq_present, cm_present, fx_present]) >= 2
        except Exception:
            return False

    @staticmethod
    def global_morning_brief():
        """Brief diário cross-asset (raro no x402): forex + commodities +
        equities + crypto + macro do dia, fechado por síntese AI. Gerado 1x/dia
        e servido do cache — margem alta, latência mínima."""
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        cached = _premium_db_get(f"brief:{today}", max_age=90000)
        if cached and Premium._brief_is_good(cached):
            cached["served_from"] = "daily-cache"
            return cached
        # cache ausente, velho ou de baixa qualidade -> regenera agora
        return Premium._generate_brief(today)

    @staticmethod
    def _generate_brief(day: str) -> dict:
        ts = int(time.time())
        fx = {p: _safe_call(lambda p=p: _brain_with_args(Brain.forex_rate, {"pair": p}))
              for p in ("EUR/USD", "GBP/USD", "USD/JPY")}
        cmd = {s: _safe_call(lambda s=s: _brain_with_args(Brain.commodity_price, {"symbol": s}))
               for s in ("GOLD", "OIL_WTI")}
        eq = {s: _safe_call(lambda s=s: _brain_with_args(Brain.stock_quote, {"symbol": s}))
              for s in ("SPY", "QQQ", "NVDA")}
        fg = _safe_call(Market.fear_greed)
        rg = _safe_call(Brain.regime)
        cal = _safe_call(Brain.macro_calendar).get("events", [])
        cal_today = [e for e in cal if e.get("date", "") >= day][:4]

        # v24.10: não montar um brief cross-asset com tudo zerado. Exige ao menos
        # forex OU commodities OU equities reais (crypto/regime sempre existem,
        # mas o produto se vende como CROSS-ASSET — precisa de mercados tradicionais).
        trad_ok = (any(_quote_ok(v) for v in fx.values())
                   or any(_quote_ok(v) for v in cmd.values())
                   or any(_quote_ok(v) for v in eq.values()))
        if not trad_ok:
            return {"status": "unavailable", "product": "Global Morning Brief",
                    "error": "Traditional-market data sources temporarily unreachable. "
                             "No charge — retry shortly.",
                    "ts": ts, "provider": "Losbeto/Premium", "version": VERSION}, 503
        live_layers = {"forex": any(_quote_ok(v) for v in fx.values()),
                       "commodities": any(_quote_ok(v) for v in cmd.values()),
                       "equities": any(_quote_ok(v) for v in eq.values())}

        snapshot = {"forex": {k: {"rate": v.get("rate"), "src": v.get("source")}
                              for k, v in fx.items() if isinstance(v, dict)},
                    "commodities": {k: {"price": v.get("price"), "chg": v.get("change_pct")}
                                    for k, v in cmd.items() if isinstance(v, dict)},
                    "equities": {k: {"price": v.get("price"), "chg": v.get("change_pct")}
                                 for k, v in eq.items() if isinstance(v, dict)},
                    "crypto_fear_greed": fg.get("value"),
                    "market_regime": rg.get("regime"),
                    "macro_events_ahead": cal_today,
                    "live_data_layers": live_layers}

        synthesis = _ai_required(
            "You are the chief strategist of a cross-asset trading desk. Using ONLY "
            f"this snapshot, write today's morning brief in English:\n"
            f"{json.dumps(snapshot, default=str)[:1800]}\n"
            "Format: (1) one-line market mood; (2) THREE risks (bullets); "
            "(3) THREE opportunities (bullets); (4) the single chart/level to watch "
            "today. Max 220 words. No financial advice disclaimer needed.")
        if not synthesis:
            synthesis = (f"Mood: {rg.get('regime','n/a')} regime, crypto fear-greed "
                         f"{fg.get('value','n/a')}. Watch: "
                         + "; ".join(e.get("event", "") for e in cal_today[:3]))

        brief = {"product": "Global Morning Brief", "date": day, "ts": ts,
                 "snapshot": snapshot, "synthesis": synthesis,
                 "coverage": "forex + commodities + equities + crypto + macro (deep Brazil coverage)",
                 "provider": "Losbeto/Premium", "version": VERSION,
                 "disclaimer": "Research, not financial advice."}
        _premium_db_put(f"brief:{day}", brief)
        return brief

