# ---------------------------------------------------------------------------
# v48.15.0-BANDIT — SALDO+BLOCKHASH SOLANA SERVER-SIDE para o checkout /pay.
# O browser do comprador às vezes não alcança NENHUM RPC público (rede
# corporativa, DNS, extensão de privacidade) e o checkout morria com
# "Could not reach the Solana network" mesmo com saldo na carteira. O
# Railway enxerga a Solana muito melhor: esta rota gratuita consulta o
# saldo de USDC (ATA passada pelo cliente; se vazia, varre TODAS as token
# accounts do mint via dataSlice de 8 bytes) e devolve também um blockhash
# fresco — o browser deixa de depender de RPC próprio. Cache 8s/carteira,
# 30 req/min/IP. Nunca expõe nada além do que a própria chain expõe.
# ---------------------------------------------------------------------------
_SOL_BAL_CACHE: Dict[str, dict] = {}
_SOL_BAL_RL: Dict[str, list] = {}
_SOL_BAL_RPCS = [u for u in [
    os.environ.get("SOLANA_RPC", ""), os.environ.get("X402_SOLANA_RPC", ""),
    "https://solana-rpc.publicnode.com", "https://api.mainnet-beta.solana.com",
    "https://solana.drpc.org"] if u]
_seen_sol_rpcs: set = set()
_SOL_BAL_RPCS = [u for u in _SOL_BAL_RPCS if not (u in _seen_sol_rpcs or _seen_sol_rpcs.add(u))]


def _sol_rpc_call(url: str, method: str, params: list, timeout: int = 6):
    r = requests.post(url, json={"jsonrpc": "2.0", "id": 1,
                                 "method": method, "params": params},
                      timeout=timeout)
    j = r.json()
    if isinstance(j, dict) and j.get("error"):
        raise RuntimeError(str(j["error"])[:120])
    return j.get("result")


# ---------------------------------------------------------------------------
# v48.16.6-EXACT3 — VIGIA DA CAMADA 7: a verificação estática dos
# facilitadores EXIGE que a ATA de USDC do payTo já exista on-chain (e proíbe
# criar ATA dentro da tx de pagamento — seria "instrução extra" e cairia no
# mesmo erro enganoso smart_wallet_program_not_allowed MESMO com a tx perfeita
# de 3 instruções). Se a ATA faltar, a correção é UMA transferência comum de
# USDC (qualquer valor) para o RECEIVE_ADDRESS — transação separada, fora do
# fluxo x402. Este vigia deriva a ATA (mesmo algoritmo do getAssociatedToken
# Address do web3.js), consulta getAccountInfo em background (TTL 6h) e expõe
# o resultado em /health/providers ("sol_dest_ata") — a camada 7 deixa de ser
# uma rejeição silenciosa e vira um sinal observável. NUNCA bloqueia request
# e NUNCA derruba premium_ready (exists=None significa "RPC mudo", não "falta").
# ---------------------------------------------------------------------------
_ED_P = 2**255 - 19
_ED_D = (-121665 * pow(121666, _ED_P - 2, _ED_P)) % _ED_P


def _ed_on_curve(point: bytes) -> bool:
    """Teste de ponto na curva ed25519 (para derivar PDA: o endereço válido é
    o que NÃO está na curva)."""
    y = int.from_bytes(point, "little") & ((1 << 255) - 1)
    if y >= _ED_P:
        return True
    y2 = y * y % _ED_P
    x2 = (y2 - 1) * pow((_ED_D * y2 + 1) % _ED_P, _ED_P - 2, _ED_P) % _ED_P
    return x2 == 0 or pow(x2, (_ED_P - 1) // 2, _ED_P) == 1


def _sol_ata_of(owner_b58: str, mint_b58: str) -> Optional[str]:
    """Associated Token Address = PDA de [dono, TokenProgram, mint] sob o
    programa ATA, bump 255→0 até o hash cair FORA da curva ed25519."""
    if not owner_b58 or not mint_b58:
        return None
    try:
        owner = base58.b58decode(owner_b58)
        mint = base58.b58decode(mint_b58)
        token = base58.b58decode("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA")
        ata_p = base58.b58decode("ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL")
        for bump in range(255, -1, -1):
            h = hashlib.sha256(owner + token + mint + bytes([bump]) + ata_p
                               + b"ProgramDerivedAddress").digest()
            if not _ed_on_curve(h):
                return base58.b58encode(h).decode()
    except Exception:
        return None
    return None


_SOL_DEST_ATA = {"ts": 0.0, "ata": None, "exists": None, "balance": None,
                 "checking": False, "checking_since": 0.0}
_SOL_DEST_ATA_TTL = int(os.environ.get("SOL_DEST_ATA_TTL", "21600"))  # 6h


def _sol_dest_ata_refresh():
    """Roda SÓ em thread daemon: getAccountInfo da ATA derivada. Nunca levanta
    exceção — o pior caso é exists=None ('desconhecido', RPCs mudos).
    v48.17.2-WATCHDOG: ts marcado na LARGADA (thread travada num RPC drip-feed
    nunca mais deixa ts=0 pra sempre), timeout (connect, read) e orçamento
    total de ~25s; o resultado sai no log p/ diagnóstico."""
    t0 = time.time()
    try:
        ata = _sol_ata_of(RECEIVE_ADDRESS, USDC_MINT)
        _SOL_DEST_ATA.update({"ata": ata, "ts": t0})
        if not ata:
            _SOL_DEST_ATA["exists"] = None
            return
        for url in _SOL_BAL_RPCS[:4]:
            if time.time() - t0 > 25:
                break
            try:
                v = ((_sol_rpc_call(url, "getAccountInfo",
                                    [ata, {"encoding": "jsonParsed"}],
                                    timeout=(3, 6))
                      or {}).get("value"))
                if v is None:
                    _SOL_DEST_ATA.update({"ts": time.time(), "exists": False,
                                          "balance": 0.0})
                else:
                    info = ((v.get("data") or {}).get("parsed") or {}).get("info") or {}
                    _SOL_DEST_ATA.update({"ts": time.time(), "exists": True,
                                          "balance": (info.get("tokenAmount") or {}).get("uiAmount")})
                log.info(f"🔗 sol_dest_ata: exists={_SOL_DEST_ATA['exists']} "
                         f"balance={_SOL_DEST_ATA['balance']}")
                return
            except Exception:
                continue
        _SOL_DEST_ATA["exists"] = None
        log.info("🔗 sol_dest_ata: RPCs mudos — exists=None (não afeta vendas)")
    except Exception:
        _SOL_DEST_ATA["exists"] = None
    finally:
        _SOL_DEST_ATA["checking"] = False


def _sol_dest_ata_status() -> dict:
    """Snapshot não-bloqueante p/ /health/providers; dispara o refresh em
    background quando o cache vence. exists True/False/None(desconhecido).
    v48.17.2: se a thread travar (RPC que pinga sem responder), após 150s o
    flag é liberado e a próxima leitura tenta de novo — o vigia se auto-cura."""
    now = time.time()
    if (_SOL_DEST_ATA.get("checking")
            and now - float(_SOL_DEST_ATA.get("checking_since") or 0) > 150):
        _SOL_DEST_ATA["checking"] = False   # thread travada vaza (daemon); flag não
    snap = dict(_SOL_DEST_ATA)
    if (not snap.get("checking")
            and now - float(snap.get("ts") or 0) > _SOL_DEST_ATA_TTL):
        _SOL_DEST_ATA.update({"checking": True, "checking_since": now})
        try:
            threading.Thread(target=_sol_dest_ata_refresh, daemon=True).start()
        except Exception:
            _SOL_DEST_ATA["checking"] = False
    snap = dict(_SOL_DEST_ATA)
    snap.pop("checking", None)
    snap.pop("checking_since", None)
    return snap


@app.route("/api/sol-usdc-balance")
def api_sol_usdc_balance():
    owner = (request.args.get("owner") or "").strip()
    ata   = (request.args.get("ata") or "").strip()
    mint  = (request.args.get("mint") or "").strip() or USDC_MINT
    if not owner or len(owner) < 32:
        return jsonify({"ok": False, "error": "owner_required"}), 400
    ip = request.headers.get("CF-Connecting-IP") or request.remote_addr or "?"
    agora = time.time()
    rl = [t for t in _SOL_BAL_RL.get(ip, []) if agora - t < 60]
    if len(rl) >= 30:
        return jsonify({"ok": False, "error": "rate_limited"}), 429
    rl.append(agora)
    _SOL_BAL_RL[ip] = rl
    if len(_SOL_BAL_RL) > 2000:
        for k in [k for k, v in _SOL_BAL_RL.items()
                  if not v or agora - v[-1] > 300][:500]:
            _SOL_BAL_RL.pop(k, None)
    ck = f"{owner}:{mint}"
    hit = _SOL_BAL_CACHE.get(ck)
    if hit and agora - hit["ts"] < 8:
        return jsonify(hit["data"])
    out = {"ok": True, "answered": False, "found": False, "have": 0.0,
           "src": ata or None, "blockhash": None,
           "lastValidBlockHeight": None, "rpc": None}
    for url in _SOL_BAL_RPCS[:4]:
        try:
            found, have, src_addr = False, 0.0, (ata or None)
            if ata:
                try:
                    bal = _sol_rpc_call(url, "getTokenAccountBalance",
                                        [ata, {"commitment": "confirmed"}])
                    have = int(bal["value"]["amount"]) / 1e6
                    found = True
                except Exception:
                    found = False   # ATA inexistente — varre pelo owner
            if not found:
                accs = _sol_rpc_call(
                    url, "getTokenAccountsByOwner",
                    [owner, {"mint": mint},
                     {"encoding": "base64",
                      "dataSlice": {"offset": 64, "length": 8},
                      "commitment": "confirmed"}])
                best_amt, best_key = -1, None
                for a in (accs or {}).get("value", []):
                    try:
                        raw = base64.b64decode(a["account"]["data"][0])
                        amt = int.from_bytes(raw[:8], "little")
                        if amt > best_amt:
                            best_amt, best_key = amt, a["pubkey"]
                    except Exception:
                        continue
                # resposta VÁLIDA da rede: sem conta => saldo zero honesto
                found = True
                if best_key is not None:
                    have, src_addr = best_amt / 1e6, best_key
            bh = _sol_rpc_call(url, "getLatestBlockhash",
                               [{"commitment": "confirmed"}])
            out.update({"answered": True, "found": found,
                        "have": round(have, 6), "src": src_addr,
                        "blockhash": bh["value"]["blockhash"],
                        "lastValidBlockHeight": bh["value"]["lastValidBlockHeight"],
                        "rpc": url})
            break
        except Exception:
            continue
    _SOL_BAL_CACHE[ck] = {"ts": agora, "data": out}
    if len(_SOL_BAL_CACHE) > 500:
        for k in sorted(_SOL_BAL_CACHE,
                        key=lambda x: _SOL_BAL_CACHE[x]["ts"])[:100]:
            _SOL_BAL_CACHE.pop(k, None)
    return jsonify(out)


