# v44.8.0: cache do probe de IA do /health/providers (ver comentário na rota).
AI_PROBE_TTL = int(os.environ.get("AI_PROBE_TTL", "900"))  # 15 min
_AI_PROBE_CACHE = {"ts": 0.0, "probe": "", "live": False}

def _ai_probe_cached():
    """Probe LLM com cache de AI_PROBE_TTL segundos — o diagnóstico segue
    fresco para auditoria, mas monitores não queimam a cota gratuita."""
    now = time.time()
    if now - _AI_PROBE_CACHE["ts"] < AI_PROBE_TTL:
        return _AI_PROBE_CACHE["probe"], _AI_PROBE_CACHE["live"]
    probe = ""
    try:
        probe = LLM.ask("Reply with exactly: OK", max_tokens=8, temperature=0)
    except Exception as e:
        probe = f"error: {e}"
    live = bool(probe) and "LLM offline" not in probe and not probe.startswith("error")
    _AI_PROBE_CACHE.update({"ts": now, "probe": probe, "live": live})
    return probe, live

@app.route("/health/providers")
def health_providers():
    """v25.3: autodiagnóstico público das fontes que sustentam as promessas do
    catálogo. Existe porque a auditoria do x402-list reprovou o nó por vender
    produtos cujas fontes estavam mudas. Agora qualquer um (inclusive um
    revisor) confere em 1 request se dado e IA estão realmente vivos."""
    out = {"version": VERSION, "ts": int(time.time())}
    # 1) IA: os produtos premium prometem síntese — isto prova se ela funciona
    # v44.8.0 FIX — O PRÓPRIO DIAGNÓSTICO SANGRAVA A COTA. Cada chamada a este
    # endpoint disparava UM probe LLM ao vivo; monitores + operador batendo
    # toda hora = centenas de chamadas/dia contra o tier gratuito do
    # Gemini/Groq → os 429 recorrentes. Agora o probe tem cache de 15 min:
    # o diagnóstico continua verdadeiro (15 min é fresco p/ auditoria) e a
    # cota fica para quem PAGA.
    probe, ai_live = _ai_probe_cached()
    out["ai"] = {"live": ai_live,
                 "providers_configured": [n for n, k in
                     (("deepseek", DEEPSEEK_KEY), ("claude", CLAUDE_KEY),
                      ("groq", GROQ_KEY), ("gemini", GEMINI_KEY),
                      ("moonshot", MOONSHOT_KEY), ("openrouter", OPENROUTER_KEY)) if k],
                 "probe": (probe or "")[:60],
                 "probe_cache_ttl_s": AI_PROBE_TTL}
    out["ml"] = {"sklearn": bool(_ML_SK),
                 "demand_classifier": _ML_CLF["n"] or ("file" if _ML_CLF_FILE.exists() else 0),
                 "anomaly_detector": _ML_IF["n"] or ("file" if _ML_IF_FILE.exists() else 0),
                 "discover": _ML_EMB.get("mode") or ("semantic" if _ML_EMB_OK else "keyword"),
                 "forecast_symbols": _fc_health_symbols(),
                 "llm_bandit": _llm_bandit_stats(),  # v48.16.1: roteador ML visível p/ auditoria
                 "llm_bandit_eps_eff": round(_llm_bandit_eps_eff(), 4),  # v48.17.0: ε adaptativo
                 "recommender_endpoints": len(_ALSO["map"]),
                 "local_llm": "on" if _LOCAL_LLM_ON else "off",
                 "public_status": "/ml",
                 "mpp_tempo": ("on" if MPP_TEMPO else "off"),
                 "price_advisor": ("auto" if PRICE_AUTO else "advisory")}
    # 2) mercados tradicionais: o que a auditoria reprovou
    checks = {}
    for path, fn in (("/stock-quote", Brain.stock_quote),
                     ("/commodity-price", Brain.commodity_price),
                     ("/forex-rate", Brain.forex_rate)):
        try:
            with app.test_request_context(path):
                r = fn()
            # v25.4 FIX: cada handler nomeia o valor de forma diferente
            # (/forex-rate usa "rate", os demais "price"). A checagem anterior só
            # olhava "price" e marcava o forex como morto mesmo com dado real —
            # falso negativo que travava premium_ready.
            val = None
            if isinstance(r, dict):
                val = r.get("price") if r.get("price") is not None else r.get("rate")
            stale = bool(isinstance(r, dict) and
                         str(r.get("source", "")).startswith("fallback"))
            checks[path] = {"live": bool(val and not (isinstance(r, dict) and r.get("status"))
                                         and not stale),
                            "source": (r.get("source") or r.get("status")) if isinstance(r, dict) else "n/a"}
        except Exception as e:
            checks[path] = {"live": False, "source": f"error: {str(e)[:40]}"}
    out["market_data"] = checks
    out["premium_ready"] = ai_live and all(v["live"] for v in checks.values())
    # v48.16.6-EXACT3: camada 7 vigiada — a ATA de USDC do payTo Solana precisa
    # EXISTIR on-chain p/ o facilitador liquidar. exists=None = RPC mudo (nunca
    # derruba premium_ready); exists=False = criar com 1 envio comum de USDC.
    try:
        out["sol_dest_ata"] = _sol_dest_ata_status()
    except Exception:
        out["sol_dest_ata"] = {"ata": None, "exists": None, "balance": None}
    # v48.17.6-RAILGUARD: estado dos DOIS rails de facilitator, visível de
    # fora. "available": false = disjuntor aberto (conta irregular / free
    # tier esgotado) — settles daquele rail nem são tentados até o cooldown.
    try:
        out["facilitators"] = {
            "cdp": {"available": _cdp_available(),
                    "retry_in_s": max(0, int(_CDP_BREAKER["open_until"] - time.time()))},
            # v48.17.7: "auth" = lane autenticada ativa (key válida no boot).
            # auth=false + available=false = pool grátis esgotado SEM saída —
            # criar key+créditos é a única restauração (free tier é lifetime).
            "payai": {"available": _payai_available(),
                      "retry_in_s": max(0, int(_PAYAI_BREAKER["open_until"] - time.time())),
                      "auth": bool(PAYAI_AUTH["ok"])},
            "manual_rail": "always on — direct USDC send + POST /api/claim-transfer",
        }
    except Exception:
        pass
    out["note"] = ("premium_ready=false means AI or market sources are down; "
                   "premium endpoints return HTTP 503 and do not charge.")
    return jsonify(out)

@app.route("/try")
def try_menu():
    """v24.6 TASTING MENU (grátis) — a resposta ao dado mais importante da
    telemetria: milhares de sondagens, zero avaliações. Scanners fazem UMA
    chamada e vão embora. Aqui, essa única chamada já entrega amostras reais
    de 6 endpoints (inclusive premium), com preço e link de compra ao lado.
    Sem pagamento, sem cadastro, sem segunda requisição."""
    base = _public_base()
    items = []
    for path in TRY_MENU:
        if path not in BASE_PRICES:
            continue
        sample = _inline_sample(path)
        # v42: card frio? tenta um reserva aquecido no lugar — o cardápio
        # nunca mostra placeholder se houver QUALQUER dado real para mostrar.
        if sample.get("status") in ("warming", "unavailable"):
            for alt in TRY_BACKFILL:
                if alt in BASE_PRICES and not any(i["endpoint"] == alt for i in items):
                    alt_sample = _inline_sample(alt)
                    if alt_sample.get("data") is not None:
                        path, sample = alt, alt_sample
                        break
        items.append({
            "endpoint": path,
            "title": ENDPOINT_DESC.get(path, path)[:120],
            "price_usdc": f"{get_dynamic_price(path):.4f}",
            "buy": f"{base}{path}",
            "free_preview": f"{base}{path}?preview=1",
            "sample": sample,
        })
    try:
        LEDGER.log_request("/try", True, 0,
                           (request.headers.get("X-Forwarded-For", request.remote_addr) or ""),
                           kind="preview", ua=request.headers.get("User-Agent", ""),
                                       params=_clean_params())
    except Exception:
        pass
    return jsonify({
        "node": "Losbeto",
        "pitch": "Global markets on x402: forex, equities, commodities, macro + crypto. "
                 "The only node that isn't crypto-only.",
        "cost_of_this_call": "0.00 USDC (free)",
        "first_call_free": {
            "endpoint": f"{base}/welcome",
            "note": ("One FREE real-time call (not delayed): GET /welcome, send "
                     "the token as X-Welcome-Token to any whitelisted endpoint.")},
        "how_to_buy": "Repeat the request to any 'buy' URL; pay the 402 challenge "
                      "with USDC on Solana or Base. No signup, no API key.",
        "samples": items,
        "all_endpoints": f"{base}/get-pricing",
        "credits": {"endpoint": f"{base}/buy-credits",
                    "deal": "$1 -> $1.25 balance, zero settlement latency"},
        "transparency": f"{base}/receipts",
        "building_something": _building_block(),
        "version": VERSION,
    })

