def _oracle_pyth(feed_id):
    # v48.14.1: sem chave o Hermes so responde 401 — falha rapido e deixa o
    # consenso multi-oraculo seguir com as fontes restantes.
    if not PYTH_API_KEY:
        raise ValueError("pyth: PYTH_API_KEY ausente")
    p = _pyth_latest([feed_id]).get(str(feed_id).lower().lstrip("0x"), {}).get("price", {})
    px = float(p.get("price", 0)) * (10 ** float(p.get("expo", 0)))
    conf = float(p.get("conf", 0)) * (10 ** float(p.get("expo", 0)))
    if px <= 0:
        raise ValueError("pyth zero")
    return {"price": px, "confidence_interval": round(conf, 6)}

def _oracle_binanceus(pair):
    r = requests.get("https://api.binance.us/api/v3/ticker/price",
                     params={"symbol": pair}, timeout=4)
    px = float(r.json().get("price", 0))
    if px <= 0:
        raise ValueError("binance.us no price")
    return {"price": px}

def _oracle_bitstamp(pair):
    r = requests.get(f"https://www.bitstamp.net/api/v2/ticker/{pair}/", timeout=4)
    px = float(r.json().get("last", 0))
    if px <= 0:
        raise ValueError("bitstamp no price")
    return {"price": px}

def _oracle_coinbase(pair):
    r = requests.get(f"https://api.coinbase.com/v2/prices/{pair}/spot", timeout=4)
    px = float(r.json().get("data", {}).get("amount", 0))
    if px <= 0:
        raise ValueError("coinbase zero")
    return {"price": px}

def _oracle_kraken(pair):
    r = requests.get("https://api.kraken.com/0/public/Ticker",
                     params={"pair": pair}, timeout=4)
    res = r.json().get("result", {})
    first = next(iter(res.values()), {})
    px = float((first.get("c") or [0])[0])
    if px <= 0:
        raise ValueError("kraken zero")
    return {"price": px}

def _oracle_coingecko(cg_id):
    r = requests.get("https://api.coingecko.com/api/v3/simple/price",
                     params={"ids": cg_id, "vs_currencies": "usd"}, timeout=4)
    px = float(r.json().get(cg_id, {}).get("usd", 0))
    if px <= 0:
        raise ValueError("coingecko zero")
    return {"price": px}

def _collect_oracles(symbol: str) -> list:
    """Consulta todas as fontes EM PARALELO. Latência total = a da mais lenta,
    não a soma. Cada fonte reporta seu próprio tempo de resposta."""
    feed, bi, cb, kr, cg, bs = ORACLE_SYMBOLS[symbol]
    tarefas = [("Pyth Network", "oracle", lambda: _oracle_pyth(feed)),
               ("Coinbase",     "cex",    lambda: _oracle_coinbase(cb)),
               ("Kraken",       "cex",    lambda: _oracle_kraken(kr)),
               ("Binance.US",   "cex",    lambda: _oracle_binanceus(bi)),
               ("Bitstamp",     "cex",    lambda: _oracle_bitstamp(bs)),
               ("CoinGecko",    "index",  lambda: _oracle_coingecko(cg))]
    out, lock = [], threading.Lock()

    def _run(nome, tipo, fn):
        t0 = time.time()
        try:
            d = fn()
            reg = {"source": nome, "type": tipo, "price": round(d["price"], 6),
                   "latency_ms": int((time.time() - t0) * 1000), "ok": True}
            if "confidence_interval" in d:
                reg["confidence_interval"] = d["confidence_interval"]
        except Exception as e:
            reg = {"source": nome, "type": tipo, "ok": False,
                   "error": str(e)[:60],
                   "latency_ms": int((time.time() - t0) * 1000)}
        with lock:
            out.append(reg)

    ths = [threading.Thread(target=_run, args=t, daemon=True) for t in tarefas]
    for t in ths:
        t.start()
    for t in ths:
        t.join(timeout=5)
    return out

def _median(v: list) -> float:
    v = sorted(v)
    n = len(v)
    return v[n // 2] if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2

def _oracle_consensus_handler():
    """Consenso multi-oráculo com detecção de divergência.

    O que a fonte gratuita NÃO dá:
      - preço mediano robusto (resistente a uma fonte manipulada)
      - divergência máxima em basis points
      - desvio absoluto mediano (MAD) — dispersão real, não média enganosa
      - qual fonte está fora da curva e por quanto
      - veredito de execução: seguro / cautela / não execute
      - latência por fonte (útil para escolher rota de execução)
    """
    symbol = (request.args.get("symbol", "SOL") or "SOL").upper()[:8]
    if symbol not in ORACLE_SYMBOLS:
        return {"error": "unsupported_symbol", "symbol": symbol,
                "supported": sorted(ORACLE_SYMBOLS),
                "note": "Ask for more symbols — endpoints are added on request.",
                "ts": int(time.time())}, 400

    t0 = time.time()
    fontes = _collect_oracles(symbol)
    vivas = [f for f in fontes if f.get("ok")]
    precos = [f["price"] for f in vivas]

    # v30: com menos de 2 fontes não existe consenso — e não se cobra por isso.
    if len(precos) < 2:
        return {"status": "unavailable", "symbol": symbol,
                "error": "Fewer than 2 oracle sources responded — no consensus "
                         "can be formed. No charge.",
                "sources": fontes, "ts": int(time.time()),
                "provider": "Losbeto/OracleConsensus", "version": VERSION}, 503

    # v30.1 METODOLOGIA: o consenso sai das fontes PRIMÁRIAS (oráculo + bolsas).
    # Índices agregados (CoinGecko) derivam das mesmas bolsas e chegam com atraso;
    # incluí-los na mediana seria contar a mesma informação duas vezes. Ficam
    # como referência cruzada, e é justamente aí que o atraso deles vira sinal.
    primarias = [f for f in vivas if f.get("type") in ("oracle", "cex")]
    base = [f["price"] for f in primarias] or precos
    mediana = _median(base)
    desvios = [abs(p - mediana) for p in base]
    mad = _median(desvios)
    spread_bps = ((max(base) - min(base)) / mediana * 10000) if mediana else 0
    mad_bps = (mad / mediana * 10000) if mediana else 0

    for f in vivas:
        d = f["price"] - mediana
        f["deviation_bps"] = round((d / mediana * 10000) if mediana else 0, 2)
        f["deviation_usd"] = round(d, 6)
        # Z-score modificado (Iglewicz & Hoaglin) — teste robusto padrão para
        # outlier com MAD. O limiar fixo anterior (30bps) deixava passar uma
        # fonte 20bps fora quando as outras concordavam em 0,5bps: em termos
        # estatísticos era um outlier gritante.
        f["modified_z"] = (round(0.6745 * d / mad, 2) if mad > 0
                           else (0.0 if abs(d) < 1e-9 else 999.0))
    def _e_outlier(f):
        # exige as duas coisas: significância estatística E relevância prática
        return abs(f.get("modified_z", 0)) > 3.5 and abs(f["deviation_bps"]) >= 5.0
    fora = [f for f in vivas if _e_outlier(f)]
    outlier = max(fora, key=lambda f: abs(f["deviation_bps"])) if fora else \
              max(vivas, key=lambda f: abs(f["deviation_bps"]))
    tem_outlier = bool(fora)

    # veredito de execução — o que o agente realmente quer saber
    if spread_bps <= 10:
        verdict, action = "tight", "Safe to execute at consensus price."
    elif spread_bps <= 50:
        verdict, action = "normal", "Normal dispersion. Execute with usual slippage."
    elif spread_bps <= 200:
        verdict, action = "wide", ("Sources disagree materially. Widen slippage "
                                   "or split the order.")
    else:
        verdict, action = "divergent", ("Do not execute on a single feed. One "
                                        "source may be stale or manipulated.")

    return {
        "product": "Oracle Consensus",
        "symbol": symbol,
        "consensus_price_usd": round(mediana, 6),
        "sources_ok": len(vivas), "sources_queried": len(fontes),
        "dispersion": {
            "spread_bps": round(spread_bps, 2),
            "mad_bps": round(mad_bps, 2),
            "high": round(max(precos), 6), "low": round(min(precos), 6),
        },
        "outliers": [{"source": f["source"], "deviation_bps": f["deviation_bps"],
                      "modified_z": f["modified_z"],
                      "flag": ("lagging_index" if f.get("type") == "index"
                               else "stale_or_manipulated")} for f in fora] or None,
        "outlier": ({"source": outlier["source"],
                     "deviation_bps": outlier["deviation_bps"],
                     "modified_z": outlier.get("modified_z"),
                     "flag": ("lagging_index" if outlier.get("type") == "index"
                              else "stale_or_manipulated")} if tem_outlier else None),
        "execution": {"verdict": verdict, "action": action,
                      "recommended_slippage_bps": round(max(10.0, spread_bps * 1.5), 1)},
        "sources": sorted(fontes, key=lambda f: (not f.get("ok"), f.get("latency_ms", 9999))),
        "fastest_source": (min(vivas, key=lambda f: f["latency_ms"])["source"]
                           if vivas else None),
        "consensus_basis": {
            "primary_sources": [f["source"] for f in primarias],
            "reference_only": [f["source"] for f in vivas
                               if f.get("type") == "index"],
            "note": "Aggregated indices are cross-checked, not averaged in — "
                    "they derive from the same exchanges and lag them.",
        },
        "methodology": ("Median of independent oracles and exchanges (aggregated "
                        "indices excluded from the median to avoid double-counting). "
                        "Dispersion via MAD. Outliers flagged by modified Z-score "
                        "(Iglewicz & Hoaglin, |Z|>3.5) with a 5bps practical floor. "
                        "All sources queried in parallel."),
        "why_not_free": ("Each oracle publishes only its own number. This is the "
                         "agreement between them — and the disagreement."),
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": int(time.time()),
        "provider": "Losbeto/OracleConsensus", "version": VERSION,
    }

# registro do endpoint
BASE_PRICES["/oracle-consensus"] = 0.03
ENDPOINT_DESC["/oracle-consensus"] = (
    "Multi-oracle price consensus (?symbol=SOL|BTC|ETH): median across Pyth, "
    "Binance, Coinbase, Kraken and CoinGecko queried in parallel, with spread in "
    "basis points, outlier detection for stale or manipulated feeds, per-source "
    "latency and an execution verdict. Each oracle publishes only its own price; "
    "this is the agreement between them.")
ENDPOINT_TAGS["/oracle-consensus"] = ["Crypto", "Trading", "Oracle"]
ENDPOINT_PARAM_HINTS["/oracle-consensus"] = {"symbol": "SOL"}
ENDPOINT_HANDLERS["/oracle-consensus"] = _oracle_consensus_handler
app.add_url_rule("/oracle-consensus", "oracle_consensus",
                 paid_endpoint("/oracle-consensus")(_oracle_consensus_handler))
if "/oracle-consensus" in FEATURED_ENDPOINTS:
    FEATURED_ENDPOINTS.remove("/oracle-consensus")
FEATURED_ENDPOINTS.insert(0, "/oracle-consensus")
log.info("🔮 Oracle Consensus registrado ($0.03) — 5 fontes em paralelo")

# ============================================================================
# 18. MACHINE DEMAND INTELLIGENCE (v29) — o que as máquinas PEDEM e não temos.
#     Registrávamos QUEM sondava (user-agent) mas nunca O QUE procurava. Um 404
#     não é erro: é uma máquina declarando uma necessidade que o catálogo não
#     atende. Cada caminho inexistente pedido por um agente real é um pedido de
#     produto — de graça, direto da demanda.
# ============================================================================

# Caminhos que scanners hostis varrem: ruído, não demanda.
# v44.3.0: `/wp/` (sem hífen) escapava do filtro e o radar de demanda chamava
# sonda de WordPress de "produto novo" — 4 IPs em 7d poluindo a leitura.
_SCAN_NOISE = re.compile(
    r"(\.env|\.git|\.aws|\.ssh|credentials|id_rsa|/wp(/|$)|wp-|wordpress|phpmyadmin|"
    r"\.php|phpinfo|_profiler|admin|backup|dump|\.sql|\.bak|service[-_]?account|_environment|firebase|"
    r"secrets?\.|config\.(json|yml|yaml)|actuator|/api/v1/(pods|namespaces)|"
    r"\.well-known/(acme|security)|favicon|robots|sitemap|apple-touch|"
    r"\.map$|\.asp|cgi-bin|xmlrpc|\.svn|docker|kube|"
    # v48.4.0: observado no radar de demanda classificando sonda de segredo
    # como "produto novo" (/env, /config/master.key, /appsettings.json) —
    # são scanners de vazamento de credenciais, não cliente em potencial.
    # v48.9.17: /storage/logs/laravel.log (9 hits/9 IPs) — scanner de log
    # Laravel exposto, mesma família. Não é demanda de produto.
    # v48.9.18: /api/session/properties (12 hits/11 IPs) — sonda de SDK de
    # analytics (Statsig/PostHog-style) atrás de config vazada. Também não.
    r"(^|/)\.?env$|/config/[^/]*\.key$|appsettings(\..*)?\.json$|"
    r"master\.key$|\.pem$|\.pfx$|\.p12$|\.htpasswd|\.htaccess|"
    r"\.log$|/storage/logs?/|laravel|/api/session/properties$|"
    # v48.11.0-GLOBAL: fugiam do filtro e viravam "produto novo" no radar —
    # /env.txt /env.js (a regra exigia .env com ponto ou env no fim),
    # /settings.json (sem o prefixo appsettings) e /config/aws.yml (a regra
    # pedia config. com ponto, nao config/ com barra). Mesma familia: caca a
    # credencial vazada, nao demanda.
    r"(^|/)\.?env\.(txt|js|json|ya?ml|local|prod(uction)?)$|"
    r"(^|/)settings\.json$|(^|/)config/[^/]+\.(ya?ml|xml|ini|conf)$)", re.I)

def _is_scan_noise(path: str) -> bool:
    return bool(_SCAN_NOISE.search(path or ""))

def _route_now_live(path: str) -> bool:
    """v44.1.0: a rota pedida EXISTE hoje? O radar é janela de 7 dias — um
    caminho que era 404 quando registrado pode ter sido construído depois
    (foi o caso de /ip e /health/). Sem esta checagem, o painel chamava de
    'not built' um produto que já estava no ar.
    v44.6.0: match real pelo roteador do Flask (MapAdapter) em vez de
    comparação exata de string — rotas-curinga como /bootstrap-trust/<sub>
    passam a contar como 'atendido', senão o radar continuaria chamando de
    alias_candidate um caminho que a regra-curinga já resolve."""
    p = (path or "").strip()
    if not p:
        return False
    try:
        from werkzeug.routing import RequestRedirect
        adapter = app.url_map.bind("radar.local")
        for cand in (p, p.rstrip("/")):
            if not cand:
                continue
            try:
                adapter.match(cand, method="GET")
                return True
            except RequestRedirect:
                return True   # rota existe, só difere pela barra final
            except Exception:
                continue      # NotFound / MethodNotAllowed -> próximo
    except Exception:
        pass
    return False

def _demand_classify(path: str) -> dict:
    """v29.1: separa pedido que já dá para atender AGORA de pedido que exige
    fonte de dados nova. A primeira categoria é ganho barato — um apelido de
    rota, zero dado novo. A segunda é decisão de produto.
    v44.1.0: antes de tudo, resolve o rótulo NA HORA da renderização — se a
    rota já existe, o pedido virou 'atendido', não 'produto novo'."""
    # v44.3.0: sonda de exploração NÃO é demanda — sai do radar de produto e
    # não dispara alerta no Telegram. Dados crus seguem gravados no ledger.
    if _is_scan_noise(path):
        return {"kind": "scanner_noise",
                "action": "Sonda de exploração (WordPress/CMS/config) — ruído filtrado",
                "closest": []}
    if _route_now_live(path):
        return {"kind": "resolved",
                "action": "Já atendido — a rota existe hoje",
                "closest": []}
    sug = _suggest_paths(path, n=2)
    if sug:
        # existe endpoint parecido -> provavelmente é questão de NOME
        return {"kind": "alias_candidate",
                "action": "Rota equivalente já existe — criar apelido resolve",
                "closest": sug}
    return {"kind": "new_product",
            "action": "Nada equivalente no catálogo — exige fonte de dados nova",
            "closest": []}

# ============================================================================
# v48.12.0-ML — CAMADA DE MACHINE LEARNING EMBARCADA
# Tres modelos treinados nos dados do PROPRIO node (60k+ probes + ledger de
# receita): nenhum concorrente pode copiar — eles nao tem o nosso trafego.
# Tudo import-guarded: sem scikit-learn/fastembed instalado, o node roda
# exatamente como antes (as features dormem, nada quebra). ML_DISABLED=1
# desliga tudo. Deps novas no requirements: scikit-learn, fastembed.
# ============================================================================
ML_DISABLED = os.environ.get("ML_DISABLED", "") == "1"
_ML_SK = None
try:
    if not ML_DISABLED:
        import joblib as _joblib
        from sklearn.ensemble import (GradientBoostingClassifier, IsolationForest,
                                      HistGradientBoostingRegressor)
        from sklearn.cluster import AgglomerativeClustering
        _ML_SK = True
except Exception as _mle:
    _ML_SK = None
    log.info(f"🧠 ML: scikit-learn ausente ({_mle.__class__.__name__}) — classificador/anomalias dormem")

_ML_DIR = Path(HOME_DIR)
_ML_CLF_FILE = _ML_DIR / "ml_demand_clf.joblib"
_ML_IF_FILE  = _ML_DIR / "ml_ops_iforest.joblib"
_ML_ANOM_FILE = _ML_DIR / "ml_anomalies.json"
_ML_CLF = {"model": None, "trained_at": 0, "n": 0}
_ML_IF  = {"model": None, "trained_at": 0, "n": 0}
_ML_LABELS = ["scanner_noise", "resolved", "alias_candidate", "new_product"]


def _ml_path_features(path: str) -> list:
    """Vetor de features de um caminho pedido — o 'DNA' que o modelo aprende."""
    p = (path or "").lower()
    segs = [s for s in p.split("/") if s]
    tail = p.rsplit("/", 1)[-1]
    ext = tail.rsplit(".", 1)[-1] if "." in tail else ""
    kws = ("wp", "admin", "config", "env", "backup", "dump", "api", "token",
           "price", "data", "login", "auth", "debug", "test", "php", "sql")
    return [
        len(p), len(segs), len(ext),
        sum(c.isdigit() for c in p), sum(c.isupper() for c in (path or "")),
        len(set(p)) / max(1, len(p)),
        float(p.count(".")), float(p.count("%")),
        float(any(k in p for k in ("wp-", "wordpress", "phpmyadmin", "xmlrpc"))),
        float(ext in ("php", "asp", "aspx", "jsp", "cgi")),
        float(ext in ("env", "pem", "key", "p12", "pfx", "sql", "bak", "log")),
        float(ext in ("json", "yml", "yaml", "xml", "ini", "conf", "txt", "js")),
        float(any(k in p for k in ("config", "credential", "secret", "settings"))),
        float(any(k in p for k in ("api", "v1", "v2", "graphql"))),
        float(any(k in p for k in ("price", "rates", "macro", "llm", "br-", "x402"))),
        float(p.endswith("/")),
    ] + [float(k in p) for k in kws]


def _ml_train_demand() -> dict:
    """Auto-rotulagem: as regras atuais (_is_scan_noise/_route_now_live/
    _suggest_paths) rotulam o historico de 404s; o GradientBoosting generaliza
    para variacoes que o regex nunca viu. Sem dados suficientes, dorme."""
    if not _ML_SK:
        return {"trained": False, "reason": "sklearn ausente"}
    try:
        with LEDGER._conn() as c:
            rows = c.execute(
                "SELECT endpoint, COUNT(*) FROM requests "
                "WHERE kind='notfound' GROUP BY endpoint").fetchall()
        if len(rows) < 60:
            return {"trained": False, "reason": f"amostras insuficientes ({len(rows)})"}
        X, y = [], []
        for path, _n in rows:
            if _is_scan_noise(path):
                lbl = "scanner_noise"
            elif _route_now_live(path):
                lbl = "resolved"
            elif _suggest_paths(path, n=1):
                lbl = "alias_candidate"
            else:
                lbl = "new_product"
            X.append(_ml_path_features(path))
            y.append(_ML_LABELS.index(lbl))
        if len(set(y)) < 2:
            return {"trained": False, "reason": "uma so classe no historico"}
        clf = GradientBoostingClassifier(n_estimators=120, max_depth=3,
                                         learning_rate=0.08, random_state=42)
        clf.fit(X, y)
        _joblib.dump(clf, _ML_CLF_FILE)
        _ML_CLF.update({"model": clf, "trained_at": int(time.time()), "n": len(X)})
        dist = {_ML_LABELS[i]: y.count(i) for i in sorted(set(y))}
        log.info(f"🧠 ML demanda: treinado com {len(X)} caminhos {dist}")
        return {"trained": True, "n": len(X), "dist": dist}
    except Exception as e:
        log.warning(f"🧠 ML demanda treino: {e}")
        return {"trained": False, "reason": str(e)[:120]}


def _ml_clf_load():
    if _ML_CLF["model"] is None and _ML_SK and _ML_CLF_FILE.exists():
        try:
            _ML_CLF["model"] = _joblib.load(_ML_CLF_FILE)
            _ML_CLF["trained_at"] = int(_ML_CLF_FILE.stat().st_mtime)
        except Exception as e:
            log.warning(f"🧠 ML demanda load: {e}")


def _ml_predict_path(path: str):
    """Devolve (label, confianca) ou None se o modelo nao esta ativo."""
    if not _ML_SK:
        return None
    _ml_clf_load()
    clf = _ML_CLF["model"]
    if clf is None:
        return None
    try:
        proba = clf.predict_proba([_ml_path_features(path)])[0]
        j = int(proba.argmax())
        # classes_ guarda os indices de _ML_LABELS vistos no treino — se uma
        # classe estava ausente, argmax NAO bate com o indice do rótulo.
        i = int(clf.classes_[j])
        return (_ML_LABELS[i], round(float(proba[j]), 3))
    except Exception:
        return None


def _demand_classify_ml(path: str) -> dict:
    """_demand_classify com a segunda opiniao do ML anexada. As REGRAS
    continuam soberanas; o ML enriquece painel/alerta e — com confianca alta —
    rebaixa para scanner_noise o 'produto novo' que o regex nao cobriu."""
    out = _demand_classify(path)
    pred = _ml_predict_path(path)
    if pred:
        out["ml"] = {"label": pred[0], "confidence": pred[1],
                     "agrees": pred[0] == out["kind"]}
        if pred[0] == "scanner_noise" and out["kind"] == "new_product" and pred[1] >= 0.85:
            out["kind"] = "scanner_noise"
            out["action"] = "Sonda de exploracao (detectada por ML; regex nao cobria)"
    return out


def _ml_hourly_aggregates(days=30) -> list:
    """Agrega requests+revenue em amostras horarias p/ o IsolationForest."""
    try:
        corte = int(time.time()) - days * 86400
        with LEDGER._conn() as c:
            req = dict(c.execute(
                "SELECT ts/3600 h, COUNT(*) FROM requests WHERE ts>? GROUP BY h",
                (corte,)).fetchall())
            ips = dict(c.execute(
                "SELECT ts/3600 h, COUNT(DISTINCT ip) FROM requests WHERE ts>? GROUP BY h",
                (corte,)).fetchall())
            paid = dict(c.execute(
                "SELECT ts/3600 h, COUNT(*) FROM requests WHERE ts>? AND kind='paid' GROUP BY h",
                (corte,)).fetchall())
            rev = dict(c.execute(
                "SELECT ts/3600 h, COALESCE(SUM(amount),0) FROM revenue WHERE ts>? GROUP BY h",
                (corte,)).fetchall())
            payers = dict(c.execute(
                "SELECT ts/3600 h, COUNT(DISTINCT payer) FROM revenue WHERE ts>? GROUP BY h",
                (corte,)).fetchall())
        return [[req.get(h, 0), ips.get(h, 0), paid.get(h, 0),
                 round(rev.get(h, 0.0), 4), payers.get(h, 0)] for h in sorted(req)]
    except Exception as e:
        log.debug(f"🧠 ML hourly: {e}")
        return []


def _ml_train_anomaly() -> dict:
    if not _ML_SK:
        return {"trained": False, "reason": "sklearn ausente"}
    try:
        X = _ml_hourly_aggregates(30)
        if len(X) < 72:
            return {"trained": False, "reason": f"horas insuficientes ({len(X)})"}
        iforest = IsolationForest(n_estimators=150, contamination=0.05, random_state=42)
        iforest.fit(X)
        _joblib.dump(iforest, _ML_IF_FILE)
        _ML_IF.update({"model": iforest, "trained_at": int(time.time()), "n": len(X)})
        log.info(f"🧠 ML anomalias: treinado com {len(X)} amostras horarias")
        return {"trained": True, "n": len(X)}
    except Exception as e:
        log.warning(f"🧠 ML anomalias treino: {e}")
        return {"trained": False, "reason": str(e)[:120]}


def _ml_if_load():
    if _ML_IF["model"] is None and _ML_SK and _ML_IF_FILE.exists():
        try:
            _ML_IF["model"] = _joblib.load(_ML_IF_FILE)
        except Exception as e:
            log.warning(f"🧠 ML anomalias load: {e}")


def _ml_score_current_hour() -> dict:
    """Pontua a ultima hora COMPLETA; anomalia -> log + arquivo + Telegram (1/6h)."""
    if not _ML_SK:
        return {}
    _ml_if_load()
    iforest = _ML_IF["model"]
    if iforest is None:
        return {}
    try:
        X = _ml_hourly_aggregates(2)
        if len(X) < 2:
            return {}
        cur = X[-2]  # hora fechada — a corrente e parcial e pareceria anomala
        pred = int(iforest.predict([cur])[0])
        score = round(float(iforest.score_samples([cur])[0]), 4)
        out = {"anomaly": pred == -1, "score": score,
               "features": {"requests": cur[0], "ips": cur[1], "paid": cur[2],
                            "revenue": cur[3], "payers": cur[4]}}
        if out["anomaly"]:
            hist = []
            if _ML_ANOM_FILE.exists():
                try:
                    hist = json.loads(_ML_ANOM_FILE.read_text())
                except Exception:
                    hist = []
            # v48.13.0-INTEL: severidade. Anomalia de VOLUME puro (sem vendas
            # nem pagadores) vira so log/arquivo — o retreino diario absorve o
            # regime novo de trafego. So comportamento de COMPRADOR/receita
            # acorda o operador no Telegram (fim do apito de hora em hora).
            sev = "buyer" if (cur[2] > 0 or cur[3] > 0 or cur[4] > 0) else "volume"
            out["severity"] = sev
            hist.append({"ts": int(time.time()), **out})
            _ML_ANOM_FILE.write_text(json.dumps(hist[-50:]))
            last = getattr(_ml_score_current_hour, "_last_alert", 0)
            if sev == "buyer" and time.time() - last > 6 * 3600:
                _ml_score_current_hour._last_alert = time.time()
                _notify_telegram(
                    f"🧠 *ANOMALIA OPERACIONAL*\n\n"
                    f"Ultima hora fora do padrao (score {score}):\n"
                    f"• requests: {cur[0]} · IPs: {cur[1]}\n"
                    f"• vendas: {cur[2]} · receita: ${cur[3]:.4f} · pagadores: {cur[4]}\n\n"
                    f"IsolationForest treinado em {_ML_IF['n']}h do proprio node.")
            log.warning(f"🧠 ANOMALIA: {out}")
        return out
    except Exception as e:
        log.debug(f"🧠 ML anomalia score: {e}")
        return {}


def ml_ops_loop():
    """Ciclo ML: primeiro treino 10 min apos o boot; re-treina 1x/dia (o node
    aprende com o trafego novo) e pontua a ultima hora fechada a cada hora.
    v48.13.0: recomendador tambem recalcula 1x/dia e o clustering semantico
    dos 404s roda 1x/semana com digest no Telegram."""
    time.sleep(600)
    if not _ML_SK:
        return
    _ml_train_demand()
    _ml_train_anomaly()
    _ml_also_bought()
    ultimo_treino = time.time()
    ultimo_cluster = time.time()  # primeiro clustering 7d apos o deploy
    while True:
        try:
            _ml_score_current_hour()
            if time.time() - ultimo_treino > 86400:
                _ml_train_demand()
                _ml_train_anomaly()
                _ml_also_bought()
                ultimo_treino = time.time()
            if time.time() - ultimo_cluster > 7 * 86400:
                if _ml_cluster_demand():
                    _ml_cluster_digest()
                _ml_price_advisor()          # v48.14.0: elasticidade semanal
                ultimo_cluster = time.time()
        except Exception as e:
            log.debug(f"ml_ops: {e}")
        time.sleep(3600)


# ---- /discover — descoberta semantica do catalogo (FastEmbed/ONNX) ----------
_ML_EMB = {"model": None, "vectors": None, "paths": [], "hash": ""}
try:
    if not ML_DISABLED:
        from fastembed import TextEmbedding as _TextEmbedding
        _ML_EMB_OK = True
    else:
        _ML_EMB_OK = False
        _TextEmbedding = None
except Exception as _mle:
    _ML_EMB_OK = False
    _TextEmbedding = None
    log.info(f"🧠 /discover: fastembed ausente ({_mle.__class__.__name__}) — modo palavra-chave")


def _discover_keyword(q: str, n: int) -> list:
    """Fallback sem embeddings: overlap de tokens entre query e descricoes."""
    toks = {t for t in re.findall(r"[a-z0-9]+", (q or "").lower()) if len(t) > 2}
    scored = []
    for path, desc in ENDPOINT_DESC.items():
        dtoks = set(re.findall(r"[a-z0-9]+", (path + " " + (desc or "")).lower()))
        inter = len(toks & dtoks)
        if inter:
            scored.append((inter / max(1, len(toks)), path))
    scored.sort(key=lambda t: (-t[0], t[1]))
    return [p for _s, p in scored[:n]]


def _discover_embed(q: str, n: int) -> list:
    """Busca vetorial 100% local. v48.13.0: modo multilingue sob demanda
    (query PT/ES/ZH -> catalogo EN) e reranker cross-encoder re-pontuando os
    top-k (olha query+documento juntos — muito mais preciso que cosseno)."""
    if not _ML_EMB_OK:
        return []
    key = "multi" if _needs_multi(q) else "base"
    paths, vecs = _emb_catalog(key)
    if paths is None and key == "multi":
        key = "base"
        paths, vecs = _emb_catalog("base")
    if paths is None:
        return []
    try:
        import numpy as _np
        qlist = _emb_encode([q], key)
        if not qlist:
            return []
        qv = _np.array(qlist[0])
        V = _np.array(vecs)
        sims = (V @ qv) / (_np.linalg.norm(V, axis=1) * _np.linalg.norm(qv) + 1e-9)
        k = max(n, 8) if _ML_RERANK_ON else n
        idx = sims.argsort()[::-1][:k]
        cands = [(paths[int(i)], float(sims[int(i)])) for i in idx]
        mode = "semantic-multilingual" if key == "multi" else "semantic"
        if _ML_RERANK_ON and len(cands) > n:
            rk = _rerank(q, [f"{p}: {ENDPOINT_DESC.get(p, '')}" for p, _s in cands])
            if rk:
                order = sorted(range(len(cands)), key=lambda i: rk[i], reverse=True)
                cands = [(cands[i][0], float(rk[i])) for i in order]
                mode += "+rerank"
        _ML_EMB["mode"] = mode
        return [(p, round(s, 3)) for p, s in cands[:n]]
    except Exception as e:
        log.warning(f"🧠 /discover embed: {e}")
        return []


@app.route("/discover")
def discover():
    """GET /discover?q=... — descoberta SEMANTICA do catalogo, gratis.
    O agente descreve a tarefa em linguagem natural; o node rankeia os
    proprios endpoints por similaridade vetorial (MiniLM ONNX local) — ou
    por palavra-chave se o fastembed nao estiver instalado. Funil: quem
    acha o endpoint certo, compra."""
    q = (request.args.get("q") or "").strip()[:300]
    try:
        n = max(1, min(int(request.args.get("n", 5)), 10))
    except (TypeError, ValueError):
        n = 5
    if not q:
        return ({"error": "missing q",
                 "example": "/discover?q=validate brazilian tax id",
                 "endpoints": len(ENDPOINT_DESC), "version": VERSION}, 400)
    t0 = time.perf_counter()
    hits = _discover_embed(q, n)
    mode = _ML_EMB.get("mode") or "semantic-minilm-onnx"
    if not hits:
        mode = "keyword-fallback"
        hits = [(p, None) for p in _discover_keyword(q, n)]
    out = []
    for path, sim in hits:
        item = {"endpoint": path,
                "price_usd": round(BASE_PRICES.get(path, 0.0), 4),
                "description": _cap500(ENDPOINT_DESC.get(path, ""), 220),
                "tags": ENDPOINT_TAGS.get(path, []),
                "pay_with": f"{_public_base()}{path}"}
        if sim is not None:
            item["similarity"] = sim
        out.append(item)
    return {"query": q, "mode": mode, "results": out,
            "how_it_works": ("Describe the task in plain language; the node ranks its "
                             "own catalog by vector similarity (local MiniLM ONNX — "
                             "no data leaves this node). Free discovery; pay per call "
                             "with USDC via x402."),
            "compute_ms": round((time.perf_counter() - t0) * 1000, 1),
            "endpoints_indexed": len(ENDPOINT_DESC),
            "ts": int(time.time()), "version": VERSION}


