@app.route("/chat/send", methods=["POST"])
def chat_send():
    """Visitante manda mensagem. Vai direto para o Telegram do operador."""
    try:
        body = request.get_json(silent=True) or {}
    except Exception:
        body = {}
    texto = (body.get("text") or "").strip()
    sid = (body.get("sid") or "").strip()[:40]
    if not texto:
        return jsonify({"error": "empty"}), 400
    if not re.fullmatch(r"[a-zA-Z0-9_-]{8,40}", sid or ""):
        sid = secrets.token_urlsafe(12)
    ip = (request.headers.get("X-Forwarded-For", request.remote_addr) or "").split(",")[0].strip()
    ua = request.headers.get("User-Agent", "")

    if not _chat_rate_ok(sid, ip):
        return jsonify({"sid": sid, "queued": False,
                        "error": "rate_limited",
                        "note": "Too many messages this hour. Try again later or "
                                "open an issue: " + FEEDBACK_GITHUB}), 429

    _chat_add(sid, "visitor", texto, ip, ua)
    curto = _chat_short(sid)
    # contexto útil para o operador decidir como responder
    try:
        hist = 0
        c = _chat_db()
        try:
            hist = c.execute("SELECT COUNT(*) FROM chat WHERE sid=? AND who='visitor'",
                             (sid,)).fetchone()[0]
        finally:
            c.close()
    except Exception:
        hist = 1
    # v48.9.21: a IA concierge responde em thread (o visitante recebe via
    # /chat/poll em segundos) e o Telegram recebe pergunta+resposta com tag.
    # Se a IA escalar ou cair, o Telegram avisa "🙋 precisa de você" — o
    # operador NUNCA perde uma mensagem.
    try:
        threading.Thread(target=_chat_ai_worker,
                         args=(sid, texto, curto, hist, ua),
                         daemon=True).start()
    except Exception:
        _tg_id = _tg_send_capture(
            f"💬 *Visitante no site* `[{curto}]`\n\n"
            f"{texto[:700]}\n\n— mensagem #{hist} desta sessão\n\n"
            f"*Para responder:* dê REPLY nesta mensagem "
            f"(ou `/r {curto} sua resposta`)")
        if _tg_id:
            _chat_tg_map(_tg_id, sid)
    return jsonify({"sid": sid, "queued": True,
                    "note": "Our AI concierge replies in seconds right here. "
                            "A human operator also sees every message and can "
                            "join this same thread. Poll /chat/poll?sid=<sid>."})

@app.route("/chat/poll")
def chat_poll():
    """A página busca as respostas do operador."""
    sid = (request.args.get("sid") or "").strip()[:40]
    if not re.fullmatch(r"[a-zA-Z0-9_-]{8,40}", sid or ""):
        return jsonify({"messages": []})
    try:
        desde = int(request.args.get("since", "0"))
    except Exception:
        desde = 0
    try:
        c = _chat_db()
        try:
            rows = c.execute("SELECT id, ts, who, text FROM chat "
                             "WHERE sid=? AND id > ? ORDER BY id LIMIT 60",
                             (sid, desde)).fetchall()
            # v43: confirmação de entrega — o visitante BUSCOU as respostas,
            # então marca as do operador como entregues. O /chats passa a
            # distinguir "respondido e lido" de "respondido, não lido".
            if rows:
                _max_id = max(r[0] for r in rows)
                c.execute("UPDATE chat SET delivered=1 WHERE sid=? AND "
                          "who IN ('operator','ai') AND id<=?", (sid, _max_id))
                c.commit()
        finally:
            c.close()
    except Exception:
        rows = []
    return jsonify({"messages": [{"id": r[0], "ts": r[1], "who": r[2], "text": r[3]}
                                 for r in rows]})

def _chat_operator_reply(short: str, texto: str) -> bool:
    """Chamado pelo bot do Telegram quando o operador usa /r."""
    sid = _chat_sid_from_short(short)
    if not sid:
        return False
    _chat_add(sid, "operator", texto)
    return True

@app.route("/chat/history")
def chat_history():
    """Painel do operador: todas as conversas. Protegido por token."""
    if not _dash_token_ok(request.args.get("token", "")):
        return jsonify({"error": "unauthorized"}), 401
    try:
        c = _chat_db()
        try:
            rows = c.execute(
                "SELECT sid, MIN(ts), MAX(ts), COUNT(*), "
                "SUM(CASE WHEN who='visitor' THEN 1 ELSE 0 END) "
                "FROM chat GROUP BY sid ORDER BY MAX(ts) DESC LIMIT 40").fetchall()
            out = []
            for sid, t0, t1, n, nv in rows:
                msgs = c.execute("SELECT ts, who, text FROM chat WHERE sid=? "
                                 "ORDER BY id", (sid,)).fetchall()
                out.append({"sid": _chat_short(sid), "started": t0, "last": t1,
                            "messages": n, "from_visitor": nv,
                            "thread": [{"ts": m[0], "who": m[1], "text": m[2]}
                                       for m in msgs]})
        finally:
            c.close()
    except Exception as e:
        return jsonify({"error": str(e)[:120]}), 500
    return jsonify({"conversations": out, "ts": int(time.time())})

@app.route("/bazaar-audit")
def bazaar_audit():
    """Auditoria de indexação no Bazaar — protegida por token do painel,
    porque faz N chamadas autenticadas à CDP.
      /bazaar-audit?token=...            -> amostra dos 12 principais
      /bazaar-audit?token=...&all=1      -> catálogo inteiro (lento)
      /bazaar-audit?token=...&ep=/x      -> um endpoint específico
    """
    if not _dash_token_ok(request.args.get("token", "")):
        return jsonify({"error": "unauthorized"}), 401
    um = request.args.get("ep")
    if um:
        return jsonify({"result": _audit_one(um if um.startswith("/") else "/" + um),
                        "ts": int(time.time())})
    alvo = (list(BASE_PRICES) if request.args.get("all") == "1"
            else [e for e in FEATURED_ENDPOINTS[:8] if e in BASE_PRICES]
                 + ["/pyth-price", "/fear-greed", "/trust-hash", "/portfolio-copilot"])
    alvo = list(dict.fromkeys(alvo))
    out, lock = [], threading.Lock()

    def _run(p):
        r = _audit_one(p)
        with lock:
            out.append(r)

    # 6 por vez: a API da CDP tem limite e não queremos ser rudes
    for i in range(0, len(alvo), 6):
        ths = [threading.Thread(target=_run, args=(p,), daemon=True)
               for p in alvo[i:i + 6]]
        for t in ths: t.start()
        for t in ths: t.join(timeout=15)

    indexados = [r for r in out if r.get("status") == "indexed"]
    fora = [r for r in out if r.get("status") == "not_indexed"]
    desconhecidos = [r for r in out if r.get("status") == "unknown"]
    return jsonify({
        "summary": {"checked": len(out), "indexed": len(indexados),
                    "not_indexed": len(fora), "unknown": len(desconhecidos)},
        "indexed": sorted(r["endpoint"] for r in indexados),
        "not_indexed": fora,
        "unknown": desconhecidos[:5],
        "method": ("CDP POST /v2/x402/validate — no-payment probe. Field is "
                   "'resource', not 'url'."),
        "source": "x402 Slack #wg-domain-discovery, 2026-07-29",
        "ts": int(time.time()), "version": VERSION,
    })

