@app.route("/launch-risk-preview")
def launch_risk_preview():
    """v21.18 GRATIS — degustação do flagship. Agentes que sondam o catálogo
    recebem valor real imediato + o caminho claro para a versão completa paga.
    Funil: preview grátis → compra do /launch-risk."""
    ts = int(time.time())
    fresh = []
    try:
        for t in (Market.pump_new() or [])[:8]:
            if t.get("chainId") == "solana" and len(t.get("tokenAddress", "")) >= 32:
                fresh.append(t["tokenAddress"])
    except Exception:
        pass
    return jsonify({
        "product": "launch-risk-brief (FREE PREVIEW)",
        "fresh_solana_launches": fresh[:5],
        "what_you_get_in_full": [
            "risk_score 0-100 + verdict (LOW/MEDIUM/HIGH/EXTREME)",
            "on-chain checks: mint authority, mutability, holder concentration",
            "DEX: liquidity USD, volume, pair age, socials",
            "AI brief (4 frases) com recomendação AVOID/WATCH/SMALL-SIZE-ONLY",
        ],
        "full_version": {
            "endpoint": f"{_public_base()}/launch-risk",
            "price_usdc": f"{get_dynamic_price('/launch-risk'):.2f}",
            "how": "GET com pagamento x402 (o 402 traz as instruções) — ou ?token=<mint> para alvo específico",
        },
        "honesty": "The preview and the paid version use the same declared methodology \u2014 heuristics plus AI. Not financial advice.",
        "ts": ts, "version": VERSION,
    })

@app.route("/api/health")
@app.route("/health")
def health():
    return jsonify({"ok": True, "version": VERSION, "ts": int(time.time())})


