def _cheapest_call_label() -> str:
    """Menor preço entre os endpoints de dado (planos não contam)."""
    try:
        pagos = [p for p in BASE_PRICES if p not in CREDIT_PLANS]
        return f"${min(get_dynamic_price(p) for p in pagos):.3f}"
    except Exception:
        return "$0.003"


