# Carteiras que o próprio operador controla do lado COMPRADOR. O bug de hoje
# é que só o lado RECEBEDOR estava listado. Configure via env (uma linha,
# separada por vírgula) e o /receipts para de chamar seu teste de "orgânico".
BUYER_WALLETS = {w.strip().lower() for w in
                 (os.environ.get("BUYER_WALLETS") or "").split(",") if w.strip()}

# Varredura de catálogo: mesmo pagador liquidando N endpoints DISTINTOS
# dentro de uma janela curta. Nenhum comprador real faz isso — um comprador
# real chama o MESMO endpoint várias vezes, não 50 endpoints diferentes em
# ordem de preço. Este é o detector que sobrevive à troca de carteira.
SWEEP_MIN_ENDPOINTS = int(os.environ.get("SWEEP_MIN_ENDPOINTS", "8"))
SWEEP_WINDOW_S      = int(os.environ.get("SWEEP_WINDOW_S", "600"))


def _self_pay_wallets() -> set:
    """Todo endereço que este nó controla ou já declarou como próprio."""
    s = set(OPERATOR_WALLETS) | set(BUYER_WALLETS)
    for a in (RECEIVE_ADDRESS, BASE_PAYTO_EVM, ALGO_PAYTO,
              getattr(WALLET, "solana_address", "")):
        if a:
            s.add(str(a).lower())
    return s


def _sweep_payers(limit_rows: int = 4000) -> dict:
    """Devolve {payer_lower: n_endpoints_distintos_na_rajada} para pagadores
    que varreram o catálogo. Lê o ledger direto, sem alterar nada.
    v48.3.2: leitura SEM LEDGER.lock — conexão thread-local + WAL; o lock do
    app é para escritas. Era ele que travava /receipts sob rajada de crawler."""
    out = {}
    try:
        with LEDGER._conn() as c:
            rows = c.execute(
                "SELECT ts, endpoint, payer FROM revenue "
                "WHERE payer IS NOT NULL AND payer != '' "
                "ORDER BY ts DESC LIMIT ?", (limit_rows,)).fetchall()
    except Exception as e:
        log.debug(f"sweep scan: {e}")
        return out
    by_payer = defaultdict(list)
    for ts_, ep_, p_ in rows:
        by_payer[(p_ or "").lower()].append((int(ts_ or 0), ep_ or ""))
    for payer, evs in by_payer.items():
        evs.sort()
        i = 0
        best = 0
        for j in range(len(evs)):
            while evs[j][0] - evs[i][0] > SWEEP_WINDOW_S:
                i += 1
            best = max(best, len({e for _, e in evs[i:j + 1]}))
        if best >= SWEEP_MIN_ENDPOINTS:
            out[payer] = best
    return out


_SWEEP_CACHE = {"ts": 0.0, "data": {}}
_SWEEP_TX_CACHE = {"ts": 0.0, "data": set()}


def _sweep_unattributed_txs(limit_rows: int = 4000) -> set:
    """v48.10.1 — rajadas SEM pagador registrado. O detector original agrupa
    por pagador e ignora payer vazio; em rails onde o pagador não chegava ao
    ledger (caso real: 50 endpoints liquidados em ~210s via Algorand), a
    varredura de catálogo saía como 'organic' no /receipts. Aqui a rajada é
    detectada por chain+tempo: >= SWEEP_MIN_ENDPOINTS endpoints distintos em
    SWEEP_WINDOW_S segundos, sem pagador atribuído. Devolve o conjunto de
    tx_sig marcados como varredura."""
    flagged = set()
    try:
        with LEDGER._conn() as c:
            rows = c.execute(
                "SELECT ts, endpoint, tx_sig, chain FROM revenue "
                "WHERE (payer IS NULL OR payer = '') "
                "AND tx_sig IS NOT NULL AND tx_sig != '' "
                "ORDER BY ts DESC LIMIT ?", (limit_rows,)).fetchall()
    except Exception as e:
        log.debug(f"sweep-unattributed scan: {e}")
        return flagged
    by_chain = defaultdict(list)
    for ts_, ep_, tx_, ch_ in rows:
        by_chain[(ch_ or "").lower()].append((int(ts_ or 0), ep_ or "", tx_))
    for _ch, evs in by_chain.items():
        evs.sort()
        i = 0
        for j in range(len(evs)):
            while evs[j][0] - evs[i][0] > SWEEP_WINDOW_S:
                i += 1
            win = evs[i:j + 1]
            if len({e for _, e, _ in win}) >= SWEEP_MIN_ENDPOINTS:
                flagged.update(t for _, _, t in win)
    return flagged


def _sweep_unattributed_cached(ttl: int = 300) -> set:
    now = time.time()
    if now - _SWEEP_TX_CACHE["ts"] > ttl:
        _SWEEP_TX_CACHE.update({"ts": now, "data": _sweep_unattributed_txs()})
    return _SWEEP_TX_CACHE["data"]


def _sweep_payers_cached(ttl: int = 300) -> dict:
    now = time.time()
    if now - _SWEEP_CACHE["ts"] > ttl:
        _SWEEP_CACHE.update({"ts": now, "data": _sweep_payers()})
    return _SWEEP_CACHE["data"]


def classify_payer(payer: str, source: str = "", tx: str = "") -> str:
    """operator-test | self-sweep | unattributed | organic. Uma só definição,
    usada em TODO lugar que fala de receita — dashboard, recibos, manifests.
    v48.10.1: pagamento sem pagador NÃO é 'organic' — só é cliente quem foi
    identificado como carteira externa. Sem pagador: rajada => self-sweep,
    senão => unattributed (não conta como venda orgânica)."""
    p = (payer or "").lower()
    if source == "bootstrap":
        return "operator-test"
    if not p:
        if tx and tx in _sweep_unattributed_cached():
            return "self-sweep"
        return "unattributed"
    if p and p in _self_pay_wallets():
        return "operator-test"
    if p and p in _sweep_payers_cached():
        return "self-sweep"
    return "organic"


def revenue_split(window_s: int = 0) -> dict:
    """A única métrica que importa: quanto veio de FORA. Tudo o mais é
    contabilidade interna e não deve aparecer como 'Receita Total'."""
    out = {"organic_usdc": 0.0, "organic_tx": 0, "organic_buyers": 0,
           "organic_repeat_buyers": 0, "organic_repeat_tx": 0,
           "operator_usdc": 0.0, "operator_tx": 0,
           "self_sweep_usdc": 0.0, "self_sweep_tx": 0,
           "unattributed_usdc": 0.0, "unattributed_tx": 0,
           "window_seconds": window_s or None}
    try:
        cutoff = int(time.time()) - window_s if window_s else 0
        with LEDGER._conn() as c:  # v48.3.2: leitura sem o lock do app (WAL)
            rows = c.execute(
                "SELECT amount, payer, source, tx_sig FROM revenue WHERE ts > ?",
                (cutoff,)).fetchall()
    except Exception as e:
        out["error"] = str(e)[:80]
        return out
    buyers = set()
    # v48.17.10: repeat purchase — a métrica que o ecossistema inteiro ainda
    # não mede (pergunta do relatório do Beck). Conta settlements POR carteira
    # orgânica; >1 = cliente que voltou sem ser convocado.
    _buyer_tx: Dict[str, int] = {}
    for amt, payer, src, _tx in rows:
        k = classify_payer(payer or "", src or "", _tx or "")
        a = float(amt or 0)
        if k == "organic":
            out["organic_usdc"] += a
            out["organic_tx"] += 1
            if payer:
                _pk = (payer or "").lower()
                buyers.add(_pk)
                _buyer_tx[_pk] = _buyer_tx.get(_pk, 0) + 1
        elif k == "self-sweep":
            out["self_sweep_usdc"] += a
            out["self_sweep_tx"] += 1
        elif k == "unattributed":
            out["unattributed_usdc"] += a
            out["unattributed_tx"] += 1
        else:
            out["operator_usdc"] += a
            out["operator_tx"] += 1
    out["organic_buyers"] = len(buyers)
    # v48.17.10: quantos voltaram — e quanto do volume vem de quem voltou.
    out["organic_repeat_buyers"] = sum(1 for n in _buyer_tx.values() if n > 1)
    out["organic_repeat_tx"] = sum(n for n in _buyer_tx.values() if n > 1)
    for k in ("organic_usdc", "operator_usdc", "self_sweep_usdc",
              "unattributed_usdc"):
        out[k] = round(out[k], 6)
    # v48.17.10-FUNNEL: conversão desafio→pagamento (janela 7d), medida pelo
    # requestId ecoado no PaymentPayload. Só existe para clientes v2; clientes
    # v1 legados não ecoam o accept — o denominador é honesto mesmo assim.
    try:
        out["conversion_funnel_7d"] = LEDGER.funnel_stats(7 * 86400)
    except Exception:
        pass
    return out


def _receipts_json_v45():
    """Substitui a rota /receipts. Mesma URL, mesma forma — mas nenhum
    pagamento seu é mais anunciado ao mundo como venda orgânica.

    v48.3.2-HARDENING: a rota morria 45s (WORKER TIMEOUT → SIGKILL) a cada
    rajada horária de crawlers (HEAD /receipts). Causa: as LEITURAS pegavam
    LEDGER.lock — o lock Python process-wide que serializa todas as ESCRITAS
    (16k probes/dia logando request + settles + threads de fundo) — e ainda
    disparavam o varredor de sweep a cada miss de cache. Em WAL, leitura não
    precisa do lock do app. Agora: resposta cacheada 180s, paginação
    ?limit/?offset, leituras sem lock, e stale-on-error como último recurso.
    """
    try:
        limit = max(1, min(int(request.args.get("limit", "50")), 200))
        offset = max(0, int(request.args.get("offset", "0")))
    except Exception:
        limit, offset = 50, 0
    cache_key = f"receipts:v2:{limit}:{offset}"
    try:
        cached = LEDGER.cache_get(cache_key, 180)
        if cached:
            resp = jsonify(cached)
            resp.headers["Cache-Control"] = "public, max-age=120"
            return resp
    except Exception:
        pass
    out = []
    try:
        # leitura SEM LEDGER.lock — conexão thread-local + WAL; o lock do app
        # existe para escritas, e era ele que travava o worker sob rajada.
        with LEDGER._conn() as _c:
            rows = _c.execute(
                "SELECT ts, endpoint, amount, tx_sig, chain, payer, source "
                "FROM revenue WHERE tx_sig IS NOT NULL AND tx_sig != '' "
                "ORDER BY ts DESC LIMIT ? OFFSET ?", (limit, offset)).fetchall()
            total = _c.execute(
                "SELECT COUNT(*) FROM revenue "
                "WHERE tx_sig IS NOT NULL AND tx_sig != ''").fetchone()[0]
        for ts_, ep_, amt_, sig_, ch_, payer_, src_ in rows:
            origin = classify_payer(payer_ or "", src_ or "", sig_ or "")
            out.append({
                "ts": ts_, "endpoint": ep_,
                "amount_usdc": f"{float(amt_ or 0):.4f}",
                "tx": sig_, "chain": ch_,
                "origin": origin, "settled_via": src_,
                "explorer": (_explorer_url(ch_, sig_)
                             if _valid_txid(sig_) else None),
            })
        split = revenue_split()
    except Exception as e:
        stale = None
        try:
            stale = LEDGER.cache_get(cache_key, 30 * 86400)
        except Exception:
            pass
        if stale:
            resp = jsonify(stale)
            resp.headers["X-Cache"] = "STALE"
            return resp
        return jsonify({"error": str(e)}), 500
    base = _public_base()
    payload = {
        "receipts": out, "count": len(out),
        "pagination": {"limit": limit, "offset": offset, "total": total,
                       "next": (f"{base}/receipts?limit={limit}&offset={offset + limit}"
                                if offset + limit < total else None)},
        "revenue_truth": split,
        "legend": {
            "organic": "paid by a wallet this node does not control",
            "operator-test": "paid by the operator's own declared wallet",
            "self-sweep": ("same wallet settled >= "
                           f"{SWEEP_MIN_ENDPOINTS} distinct endpoints within "
                           f"{SWEEP_WINDOW_S}s — catalog sweep, not demand"),
            "unattributed": ("settled but the facilitator did not disclose the "
                             "payer; NOT counted as an organic customer"),
        },
        "note": ("Every line is verifiable on-chain. Operator-funded traffic "
                 "is labelled as such: only 'organic' is a real customer."),
    }
    try:
        LEDGER.cache_set(cache_key, payload)
    except Exception:
        pass
    resp = jsonify(payload)
    resp.headers["Cache-Control"] = "public, max-age=120"
    return resp


try:
    app.view_functions["receipts_json"] = _receipts_json_v45
    log.info("🧾 v45: /receipts agora separa orgânico × teste do operador × varredura")
except Exception as _e:
    log.warning(f"v45 receipts override: {_e}")


# ---------------------------------------------------------------------------
# v47.9.4-TOKENFILE — A CEREJA: /funnel.json, o funil do paywall PÚBLICO E ASSINADO
#
# Ninguém no ecossistema x402 publica o próprio funil: quantos 402 saem,
# quantos voltam pagando, quantos pagadores são carteiras VISTAS PELA
# PRIMEIRA VEZ depois de uma data de referência. É o número que o stipend.sh
# pediu para medir a conversão do bloco no_wallet — e vira mais uma prova
# de transparência auditável, no espírito do honest-revenue.
# ---------------------------------------------------------------------------

@app.route("/funnel.json")
@app.route("/.well-known/funnel.json")
def funnel_json():
    st = LEDGER.stats() or {}
    # pagadores cuja PRIMEIRA liquidação no ledger é recente (= converteram
    # depois do bloco no_wallet entrar no ar — a métrica que o Matt pediu)
    try:  # defina no Railway como número unix; texto inválido vira 0 (sem 500)
        ref = int(os.environ.get("FUNNEL_REF_TS", "0") or 0)
    except (TypeError, ValueError):
        ref = 0
    new_payers = []
    try:
        with LEDGER._conn() as c:
            rows = c.execute(
                "SELECT payer, MIN(ts) first_ts, COUNT(*) n, SUM(amount) amt "
                "FROM revenue WHERE payer<>'' GROUP BY payer").fetchall()
        new_payers = [
            {"payer": r[0], "first_seen": r[1], "calls": r[2],
             "total_usdc": round(r[3] or 0, 6)}
            for r in rows if (not ref) or (r[1] >= ref)
        ]
        new_payers.sort(key=lambda x: x["first_seen"])
    except Exception:
        pass
    challenges = st.get("challenges_24h", 0)
    paid_24h = st.get("paid_24h", 0)
    body = {
        "node": BRAND_NAME,
        "url": _public_base(),
        "generated_at": datetime.now(timezone.utc).isoformat(
            timespec="seconds").replace("+00:00", "Z"),
        "window_24h": {
            "challenges_402_issued": challenges,
            "settlements": paid_24h,
            "organic_usdc": (st.get("revenue_truth_24h") or {}).get("organic_usdc", 0),
            "challenge_to_settlement_pct": round(
                (paid_24h / challenges * 100) if challenges else 0, 3),
        },
        "new_payers_since_ref": {
            "ref_ts": ref or None,
            "ref_note": ("set FUNNEL_REF_TS (unix) on Railway to the stipend "
                         "block deploy time; empty = all payers ever"),
            "payers": new_payers,
            "count": len(new_payers),
        },
        "stipend_block_live": True,
        "stipend_ua": "stipend/0.46.1 (+https://stipend.sh)",
        "receipts": f"{_public_base()}/receipts",
        "ts": int(time.time()),
    }
    blob = json.dumps(body, sort_keys=True, separators=(",", ":"), default=str)
    body["sha256"] = hashlib.sha256(blob.encode()).hexdigest()
    try:
        body["signature"] = base64.b64encode(
            WALLET.sign(f"losbeto-funnel|{body['sha256']}".encode())).decode()
        body["signer"] = WALLET.solana_address
    except Exception as e:
        body["signature_error"] = str(e)[:60]
    resp = jsonify(body)
    resp.headers["Access-Control-Allow-Origin"] = "*"
    resp.headers["Cache-Control"] = "public, max-age=300"
    return resp

@app.route("/.well-known/honest-revenue.json")
def honest_revenue_json():
    """O documento que se manda para um avaliador (Algorand Challenge, CDP,
    investidor) quando ele pergunta 'quem está pagando?'. Assinado Ed25519.
    Contém os números RUINS de propósito: um relatório que só tem número
    bom não prova nada."""
    all_time = revenue_split()
    d1 = revenue_split(86400)
    d7 = revenue_split(7 * 86400)
    body = {
        "node": BRAND_NAME,
        "node_id": getattr(WALLET, "node_id", ""),
        "url": _public_base(),
        "generated_at": datetime.now(timezone.utc).isoformat(
            timespec="seconds").replace("+00:00", "Z"),
        "methodology": {
            "organic": "payer wallet is not controlled or declared by the operator",
            "excluded": ["operator wallets (OPERATOR_WALLETS + BUYER_WALLETS)",
                         "bootstrap settlements",
                         f"catalog sweeps (>= {SWEEP_MIN_ENDPOINTS} distinct "
                         f"endpoints from one payer in {SWEEP_WINDOW_S}s)"],
            "source": "this node's own SQLite ledger; every tx_sig is on-chain",
        },
        "all_time": all_time,
        "last_24h": d1,
        "last_7d": d7,
        "self_declared_operator_wallets": sorted(_self_pay_wallets()),
        "receipts": f"{_public_base()}/receipts",
    }
    blob = json.dumps(body, sort_keys=True, separators=(",", ":"), default=str)
    body["sha256"] = hashlib.sha256(blob.encode()).hexdigest()
    try:
        body["signature"] = base64.b64encode(
            WALLET.sign(f"losbeto-honest-revenue|{body['sha256']}".encode())).decode()
        body["signer"] = WALLET.solana_address
    except Exception as e:
        body["signature_error"] = str(e)[:60]
    return jsonify(body)


# ============================================================================
# BLOCO B — FRESCOR (o /try de uma semana atrás nunca mais)
# ============================================================================

_NO_STORE_PREFIXES = ("/try", "/live", "/receipts", "/health", "/sample",
                      "/archive", "/dash", "/x402-resources", "/get-pricing",
                      "/br-asof", "/br-revisions", "/br-pit-proof",
                      "/.well-known/honest-revenue.json", "/why-buy")


@app.after_request
def _v45_no_store(resp):
    """Rotas vivas param de ser cacheáveis por CDN, proxy ou fetcher.
    Sem isto, uma amostra de 04/ago segue sendo servida em 11/ago com
    'age_seconds: 50' — que é pior do que não ter amostra nenhuma."""
    try:
        p = request.path or ""
        if resp.status_code == 402 or p == "/" or any(
                p.startswith(x) for x in _NO_STORE_PREFIXES):
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["Vary"] = "X-PAYMENT, Authorization, X-API-Key, Accept"
            resp.headers["X-Generated-At"] = str(int(time.time()))
    except Exception:
        pass
    return resp


# Idade máxima que uma amostra pode ter antes de ser rotulada como velha.
SAMPLE_STALE_S = int(os.environ.get("SAMPLE_STALE_S", "7200"))   # 2h
_v45_inline_sample_orig = _inline_sample


def _inline_sample(endpoint: str) -> dict:            # noqa: F811
    """Mesma amostra, agora com a verdade sobre a idade dela. Um avaliador
    que recebe dado velho rotulado como velho ainda pode confiar no nó;
    dado velho rotulado como fresco queima a confiança de uma vez só."""
    s = _v45_inline_sample_orig(endpoint)
    try:
        age = int(s.get("age_seconds") or 0)
        if s.get("data") is not None and age > SAMPLE_STALE_S:
            s["stale"] = True
            s["note"] = (f"Cached sample is {age // 3600}h old — the paid call "
                         "is computed live at request time.")
    except Exception:
        pass
    return s


# ============================================================================
# BLOCO C — A COTA DE LLM PERTENCE A QUEM PAGA
# ============================================================================

LLM_DAILY_BUDGET  = int(os.environ.get("LLM_DAILY_BUDGET", "800"))
LLM_PAID_RESERVE  = int(os.environ.get("LLM_PAID_RESERVE", "300"))
_llm_budget = {"day": "", "used": 0}
_llm_budget_lock = threading.Lock()


def llm_budget_take(paid: bool) -> bool:
    """True se pode gastar uma chamada de LLM agora.
    Chamada gratuita (warmer, probe, preview) NUNCA encosta na reserva."""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    with _llm_budget_lock:
        if _llm_budget["day"] != today:
            _llm_budget.update({"day": today, "used": 0})
        left = LLM_DAILY_BUDGET - _llm_budget["used"]
        if left <= 0:
            return False
        if not paid and left <= LLM_PAID_RESERVE:
            return False
        _llm_budget["used"] += 1
        return True


def llm_budget_state() -> dict:
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    with _llm_budget_lock:
        used = _llm_budget["used"] if _llm_budget["day"] == today else 0
    return {"day": today, "used": used, "budget": LLM_DAILY_BUDGET,
            "reserved_for_paid": LLM_PAID_RESERVE,
            "free_calls_left": max(0, LLM_DAILY_BUDGET - used - LLM_PAID_RESERVE),
            "paid_calls_left": max(0, LLM_DAILY_BUDGET - used)}


@app.route("/health/llm-budget")
def health_llm_budget():
    return jsonify(llm_budget_state())


