_ZERO_UPSTREAM = {"/br-pix-parse", "/br-pix-code", "/br-bizdays", "/br-doc"}


def _iso(s: str):
    try:
        return date.fromisoformat((s or "").strip())
    except Exception:
        return None


def _h_pix_parse():
    code = (request.args.get("code") or request.args.get("brcode") or "").strip()
    ts_now = int(time.time())
    if not code:
        return ({"status": "bad_request", "charged": False,
                 "error": "code=<BR Code payload> is required",
                 "hint": "the full EMV string, ending in the 4-hex CRC",
                 "ts": ts_now, "version": VERSION}, 400)
    t0 = time.perf_counter()
    try:
        out = _pix_parse(code)
    except ValueError as e:
        return ({"status": "invalid_payload", "charged": False,
                 "error": str(e)[:120],
                 "note": "Malformed input is rejected free of charge.",
                 "ts": ts_now, "version": VERSION}, 400)
    return {"product": "PIX BR Code decoder", "input_length": len(code),
            "decoded": out,
            "verdict": "VALID" if out["crc_valid"] else "CRC_MISMATCH",
            "spec": "BACEN Manual de Padroes para Iniciacao do PIX (EMV-MPM)",
            "upstream_calls": 0,
            "compute_ms": round((time.perf_counter() - t0) * 1000, 3),
            "ts": ts_now, "version": VERSION}


def _h_pix_code():
    a = request.args
    key = (a.get("key") or "").strip()
    ts_now = int(time.time())
    if not key:
        return ({"status": "bad_request", "charged": False,
                 "error": "key=<pix key> is required (CPF/CNPJ, email, phone or EVP)",
                 "example": "/br-pix-code?key=pay@example.com&name=ACME&city=SAO PAULO&amount=10.00",
                 "ts": ts_now, "version": VERSION}, 400)
    amt = a.get("amount")
    try:
        amt = float(amt) if amt not in (None, "") else None
        if amt is not None and (amt <= 0 or amt > 99999999.99):
            raise ValueError
    except ValueError:
        return ({"status": "bad_request", "charged": False,
                 "error": "amount must be a positive number below 100000000",
                 "ts": ts_now, "version": VERSION}, 400)
    t0 = time.perf_counter()
    code = _pix_build(key, a.get("name") or "RECEBEDOR",
                      a.get("city") or "SAO PAULO", amt,
                      a.get("txid") or "***", a.get("description"),
                      a.get("cep"))
    check = _pix_parse(code)
    return {"product": "PIX BR Code generator",
            "brcode": code, "length": len(code),
            "static": amt is None,
            "self_check": {"reparsed_ok": check["crc_valid"],
                           "crc": check["crc_expected"]},
            "fields": {"key": key, "amount": f"{amt:.2f}" if amt else None,
                       "txid": (a.get("txid") or "***")[:25]},
            "spec": "BACEN Manual de Padroes para Iniciacao do PIX (EMV-MPM)",
            "upstream_calls": 0,
            "compute_ms": round((time.perf_counter() - t0) * 1000, 3),
            "ts": ts_now, "version": VERSION}


def _h_bizdays():
    a = request.args
    ts_now = int(time.time())
    d1, d2 = _iso(a.get("from") or a.get("start")), _iso(a.get("to") or a.get("end"))
    if a.get("year") and not (d1 or d2):
        try:
            y = int(a["year"])
            if not 1990 <= y <= 2100:
                raise ValueError
        except ValueError:
            return ({"status": "bad_request", "charged": False,
                     "error": "year must be between 1990 and 2100",
                     "ts": ts_now, "version": VERSION}, 400)
        hol = br_bank_holidays(y)
        return {"product": "Brazilian bank calendar",
                "year": y, "holidays": dict(sorted(hol.items())),
                "holiday_count": len(hol),
                "business_days": br_bizdays(date(y, 1, 1), date(y + 1, 1, 1)),
                "basis": "ANBIMA 252-business-day convention",
                "upstream_calls": 0, "ts": ts_now, "version": VERSION}
    if not d1 or not d2:
        return ({"status": "bad_request", "charged": False,
                 "error": "from=YYYY-MM-DD&to=YYYY-MM-DD, or year=YYYY",
                 "example": "/br-bizdays?from=2026-01-02&to=2026-07-01",
                 "ts": ts_now, "version": VERSION}, 400)
    if abs((d2 - d1).days) > 366 * 30:
        return ({"status": "bad_request", "charged": False,
                 "error": "range limited to 30 years",
                 "ts": ts_now, "version": VERSION}, 400)
    t0 = time.perf_counter()
    du = br_bizdays(d1, d2)
    hol = _hol_range(min(d1, d2).year, max(d1, d2).year)
    inrange = {k: v for k, v in sorted(hol.items())
               if d1.isoformat() <= k < d2.isoformat()}
    return {"product": "Brazilian business-day count",
            "from": d1.isoformat(), "to": d2.isoformat(),
            "convention": "[from, to) — ANBIMA",
            "business_days": du,
            "calendar_days": (d2 - d1).days,
            "year_fraction_252": round(du / 252.0, 8),
            "holidays_in_range": inrange,
            "from_is_business_day": br_is_bizday(d1),
            "to_is_business_day": br_is_bizday(d2),
            "note": ("Use business_days as the exponent denominator when "
                     "annualising CDI: (1+i)^(du/252). Carnaval, Good Friday "
                     "and Corpus Christi move with Easter; Consciencia Negra "
                     "is national from 2024 (Lei 14.759/2023)."),
            "upstream_calls": 0,
            "compute_ms": round((time.perf_counter() - t0) * 1000, 3),
            "ts": ts_now, "version": VERSION}


def _h_doc():
    v = (request.args.get("doc") or request.args.get("value") or "").strip()
    ts_now = int(time.time())
    if not v:
        return ({"status": "bad_request", "charged": False,
                 "error": "doc=<CNPJ or CPF> is required",
                 "ts": ts_now, "version": VERSION}, 400)
    digits = re.sub(r"\D", "", v)
    t0 = time.perf_counter()
    if len(digits) == 14:
        kind, valid = "CNPJ", _cnpj_valid(digits)
        fmt = (f"{digits[:2]}.{digits[2:5]}.{digits[5:8]}/"
               f"{digits[8:12]}-{digits[12:]}") if valid else None
        extra = {"is_headquarters": digits[8:12] == "0001",
                 "branch_number": digits[8:12]}
    elif len(digits) == 11:
        kind, valid = "CPF", _cpf_valid(digits)
        fmt = (f"{digits[:3]}.{digits[3:6]}.{digits[6:9]}-{digits[9:]}"
               ) if valid else None
        extra = {}
    else:
        return ({"status": "bad_request", "charged": False,
                 "error": f"expected 11 digits (CPF) or 14 (CNPJ), got {len(digits)}",
                 "ts": ts_now, "version": VERSION}, 400)
    return {"product": "Brazilian document check-digit validation",
            "type": kind, "valid": valid, "formatted": fmt,
            "digits": len(digits), **extra,
            "algorithm": "modulo 11 with the Receita Federal weight vectors",
            "scope": ("Check-digit validation only. This does NOT confirm the "
                      "document is registered or active — for registry status "
                      "an official Receita Federal query is required."),
            "upstream_calls": 0,
            "compute_ms": round((time.perf_counter() - t0) * 1000, 3),
            "ts": ts_now, "version": VERSION}


def _h_global_rates():
    """GET /global-rates — taxas de juros dos 6 maiores bancos centrais.
    Serie oficial diaria do BIS (WS_CBPOL) + cross-check ao vivo nas fontes
    primarias (FRED, ECB SDW, BCB SGS). Nenhum concorrente x402 tem."""
    import csv as _csv
    import io as _io
    from concurrent.futures import ThreadPoolExecutor as _TPE
    t0 = time.perf_counter()
    ts_now = int(time.time())
    _BANKS = {"US": "Federal Reserve",
              "XM": "European Central Bank",
              "CN": "People's Bank of China (LPR 1y)",
              "JP": "Bank of Japan",
              "RU": "Central Bank of Russia",
              "BR": "Banco Central do Brasil (Selic)"}

    def _bis():
        r = requests.get(
            "https://stats.bis.org/api/v2/data/dataflow/BIS/WS_CBPOL/1.0/"
            "D.US+XM+CN+JP+RU+BR?format=csvfile&lastNObservations=1", timeout=10)
        rows = {}
        if r.ok:
            for row in _csv.DictReader(_io.StringIO(r.text)):
                a, v, per = row.get("REF_AREA"), row.get("OBS_VALUE"), row.get("TIME_PERIOD")
                if a and v:
                    try:
                        rows[a] = {"rate_pct": float(v), "as_of": per}
                    except (TypeError, ValueError):
                        continue
        return rows, (None if r.ok else f"HTTP {r.status_code}")

    def _fed():
        r = requests.get("https://fred.stlouisfed.org/graph/fredgraph.csv?id=DFEDTARU",
                         timeout=8)
        if not r.ok:
            return None, f"HTTP {r.status_code}"
        linhas = [l for l in r.text.strip().splitlines()
                  if l and not l.startswith("DATE")]
        if not linhas:
            return None, "sem linhas"
        d, v = linhas[-1].split(",")[:2]
        return {"rate_pct": float(v), "as_of": d,
                "series": "FRED DFEDTARU (target upper bound)"}, None

    def _ecb():
        r = requests.get("https://data-api.ecb.europa.eu/service/data/FM/"
                         "B.U2.EUR.4F.KR.MRR_FR.LEV?lastNObservations=1&format=csvdata",
                         timeout=8)
        if not r.ok:
            return None, f"HTTP {r.status_code}"
        for row in _csv.DictReader(_io.StringIO(r.text)):
            if row.get("OBS_VALUE"):
                return {"rate_pct": float(row["OBS_VALUE"]),
                        "as_of": row.get("TIME_PERIOD"),
                        "series": "ECB SDW MRR (main refi)"}, None
        return None, "sem observacoes"

    def _bcb():
        try:
            r = _http_get_retry("https://api.bcb.gov.br/dados/serie/bcdata.sgs.11/"
                                "dados/ultimos/1?formato=json", timeout=8)
        except requests.exceptions.RequestException as e:
            return None, f"rede BCB: {str(e)[:80]}"   # degrada a linha, não o handler
        if not r.ok:
            return None, f"HTTP {r.status_code}"
        arr = r.json()
        if arr:
            return {"rate_pct_per_day": float(arr[0]["valor"]),
                    "as_of": arr[0]["data"],
                    "series": "BCB SGS 11 (Selic diaria %/dia)"}, None
        return None, "sem observacoes"

    rows, errs, checks = {}, {}, {}
    with _TPE(max_workers=4) as ex:
        futs = {"bis": ex.submit(_bis), "US": ex.submit(_fed),
                "XM": ex.submit(_ecb), "BR": ex.submit(_bcb)}
        bis_rows, bis_err = futs["bis"].result()
        rows.update(bis_rows)
        if bis_err:
            errs["bis"] = bis_err
        for area in ("US", "XM", "BR"):
            val, err = futs[area].result()
            if val:
                checks[area] = val
            if err:
                errs[area.lower()] = err
    if not rows:
        return ({"status": "unavailable", "charged": False,
                 "error": "all rate sources failed", "detail": errs,
                 "ts": ts_now, "version": VERSION}, 502)
    us = rows.get("US", {}).get("rate_pct")
    out = {}
    for area, bank in _BANKS.items():
        r = rows.get(area)
        if not r:
            continue
        item = {"bank": bank, "policy_rate_pct": r["rate_pct"],
                "as_of": r["as_of"], "source": "BIS WS_CBPOL daily (official)"}
        if area in checks:
            item["live_check"] = checks[area]
        if us is not None:
            item["differential_vs_us_pp"] = round(r["rate_pct"] - us, 3)
        out[area] = item
    missing = [a for a in _BANKS if a not in out]
    return {"product": "Global central bank policy rates — Fed, ECB, PBoC, BOJ, CBR, BCB",
            "rates": out,
            "missing": missing or None,
            "source_errors": errs or None,
            "note": ("Headline rates are the BIS daily policy-rate series (official). "
                     "Fed/ECB/BCB carry an additional live cross-check from the "
                     "primary source (FRED, ECB SDW, BCB SGS). BIS publishes with a "
                     "short lag; as_of dates are per-series."),
            "compute_ms": round((time.perf_counter() - t0) * 1000, 1),
            "ts": ts_now, "version": VERSION}


