# --- v48.5.0-FUNIL: /blog/ e /login — gaps medidos pelo radar ---------------
# /blog/ tinha 62 req/7d (maioria com rest_route=/batch/v1 = scanner de
# WordPress, mas o 404 não nos servia nada) e /login 9 req/7d (agentes
# procurando auth). Responder 200 útil converte scanner em avaliador e
# explica o modelo: sem conta — o pagamento É a credencial.

@app.route("/blog/")
@app.route("/blog")
def blog_index():
    """Índice machine-readable — quem pede /blog/ quer saber o que este node
    publica. Entregamos o mapa (todos os links abaixo existem de verdade)."""
    posts = [
        {"slug": "why-agents-buy", "title": "What AI agents actually pay for",
         "url": f"{_public_base()}/what-agents-buy"},
        {"slug": "why-buy", "title": "Why buy from this node",
         "url": f"{_public_base()}/why-buy"},
        {"slug": "honest-revenue", "title": "Honest revenue, on-chain",
         "url": f"{_public_base()}/.well-known/honest-revenue.json"},
        {"slug": "proof-of-revenue", "title": "Proof of revenue",
         "url": f"{_public_base()}/.well-known/proof-of-revenue.json"},
        {"slug": "pit-proof", "title": "Point-in-time Brazil: the free proof",
         "url": f"{_public_base()}/br-pit-proof"},
        {"slug": "scorecard", "title": "Evaluator scorecard",
         "url": f"{_public_base()}/scorecard.json"},
    ]
    if _wants_html():
        items = "".join(
            f'<li style="margin:10px 0"><a href="{p["url"]}" style="color:#60a5fa">'
            f'{p["title"]}</a></li>' for p in posts)
        return app.response_class(
            f'<!doctype html><html lang="en"><head><meta charset="utf-8">'
            f'<meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<title>Losbeto — index</title></head><body style="background:#0a0b0d;'
            f'color:#e8eaed;font:15px/1.6 -apple-system,sans-serif;max-width:640px;'
            f'margin:0 auto;padding:40px 20px"><a href="/" style="color:#60a5fa">← losbeto</a>'
            f'<h1 style="font-family:monospace;font-size:22px">Published thinking</h1>'
            f'<ul style="padding-left:20px">{items}</ul></body></html>',
            mimetype="text/html")
    return jsonify({"node": BRAND_NAME, "version": VERSION,
                    "posts": posts, "count": len(posts)})


@app.route("/login")
def login_info():
    """Agentes batem em /login procurando autenticação. A resposta correta num
    node x402: não há login — o pagamento por chamada É a credencial."""
    if _wants_html():
        return redirect("/pricing", code=302)
    return jsonify({
        "auth_model": "x402 — pay per call, no account, no login",
        "how_to_authenticate": {
            "pay_per_call": f"{_public_base()}/get-pricing",
            "browser_wallet_checkout": f"{_public_base()}/pay/<endpoint>",
            "api_key_credits": f"{_public_base()}/buy-credits",
        },
        "note": "There is no username/password. Every paid response is the "
                "credential. Buy credits once, reuse with X-API-Key.",
        "version": VERSION}), 200


# --- v48.6.0-REGISTER — a porta do playbook SaaS das máquinas ----------------
# Demanda medida pelo radar (7d): /register 17 req/3 IPs · /auth/callback 14/2 ·
# /signup 11/3 — agentes rodando o playbook clássico de API (achar endpoint →
# "registrar" → receber key) e levando 404. A resposta x402-nativa: conta não
# existe, o pagamento É a credencial. Mas se o playbook EXIGE uma key, ela se
# compra aqui: POST /register cobra o MESMO pacote de /buy-credits ($0.99 →
# $1.25 de saldo, +25%) e devolve a key no corpo. Registrar = comprar a entrada.
def _register_doc():
    base = _public_base()
    return {
        "registration": "not_required",
        "auth_model": "x402 — the payment is the credential. No account, no form.",
        "instant_access": {
            "pay_per_call": "send any documented endpoint, answer the 402, retry with payment",
            "pricing": f"{base}/get-pricing",
            "browser_checkout_for_humans": f"{base}/pay/<endpoint>"},
        "if_your_playbook_requires_an_api_key": {
            "how": ("POST /register (or /signup) and answer the x402 challenge "
                    "($0.99). The 200 response IS your api_key, pre-loaded with "
                    "$1.25 of call credit (+25% bonus, 30 days)."),
            "method": "POST", "url": f"{base}/register", "price_usdc": 0.99,
            "use_as": "X-API-Key: <api_key> — zero settlement latency per call",
            "check_balance": f"{base}/credits-status?key=<api_key>",
            "bigger_packs": f"{base}/plans"},
        "free_evaluation": {
            "one_real_time_call_free": f"{base}/welcome",
            "six_samples_one_call": f"{base}/try",
            "delayed_preview_any_endpoint": "?preview=1 on any paid path"},
        "provider": "Losbeto", "version": VERSION}

@app.route("/register", methods=["GET"])
@app.route("/signup", methods=["GET"])
def register_info():
    if _wants_html():
        return redirect("/pricing", code=302)
    return jsonify(_register_doc()), 200

@app.route("/auth/callback", methods=["GET", "POST"])
def auth_callback_info():
    # Sonda de OAuth esperando troca de código por token. Não há OAuth aqui —
    # mesma resposta do /login (JSON para máquina, 302→/pricing para navegador).
    return login_info()

# A "matrícula": POST paga o pacote de entrada e devolve a key. Reusa a máquina
# de créditos já provada em produção (emissão idempotente por tx + Telegram).
# O 402 descreve /buy-credits de propósito: é LITERALMENTE o mesmo produto na
# mesma tabela pública — outra porta, zero preço especial.
app.add_url_rule("/register", "register_paid",
                 paid_endpoint("/buy-credits")(_credits_purchase_handler("/buy-credits")),
                 methods=["POST"])
app.add_url_rule("/signup", "signup_paid",
                 paid_endpoint("/buy-credits")(_credits_purchase_handler("/buy-credits")),
                 methods=["POST"])

# RFC 9116 — o hermes-contact-discovery (456 hits/24h) e scanners enterprise
# procuram isto; sem a rota, essa atenção virava 404 e ruído no radar.
@app.route("/.well-known/security.txt")
@app.route("/security.txt")
def security_txt():
    txt = ("Contact: mailto:roberto.martins622@gmail.com\n"
           f"Contact: {_public_base()}/support\n"
           "Expires: " + time.strftime("%Y-%m-%dT%H:%M:%SZ",
               time.gmtime(time.time() + 180 * 86400)) + "\n"
           "Preferred-Languages: en, pt\n"
           f"Canonical: {_public_base()}/.well-known/security.txt\n")
    r = app.response_class(txt, mimetype="text/plain")
    r.headers["Cache-Control"] = "public, max-age=86400"
    return r


# ---------------------------------------------------------------------------
# v48.9.16-SELLER — AGENT ECONOMY REPORT: claim por controle de domínio.
# O serviço envia UM token por host e o verifica DIARIAMENTE nesta rota, nos
# DOIS hosts (api.losbeto.xyz e o host railway). Tokens NUNCA no repo: chegam
# por Railway Variables (AGENT_ECONOMY_TOKEN_API / AGENT_ECONOMY_TOKEN_RAILWAY).
# Sem token configurado a rota responde 404 seco — nunca um token inventado.
# ---------------------------------------------------------------------------
_AGENT_ECONOMY_HOST_ENV = {
    "api.losbeto.xyz": "AGENT_ECONOMY_TOKEN_API",
    "losbeto-production-dd7c.up.railway.app": "AGENT_ECONOMY_TOKEN_RAILWAY",
}

@app.route("/.well-known/agenteconomy-verify.txt")
def agenteconomy_verify():
    host = (request.host or "").split(":")[0].lower().strip()
    env_name = _AGENT_ECONOMY_HOST_ENV.get(host)
    token = (os.environ.get(env_name, "") if env_name else "").strip()
    if not token and host:
        # host customizado futuro: tenta o token do domínio principal como
        # fallback SOMENTE se for alias conhecido do mesmo serviço.
        token = ""
    if not token:
        return ("not configured\n", 404, {"Content-Type": "text/plain; charset=utf-8"})
    r = app.response_class(token + "\n", mimetype="text/plain")
    # o verificador relê todo dia; cache curto p/ não atrasar uma rotação.
    r.headers["Cache-Control"] = "public, max-age=60"
    return r


